INSERT  IGNORE INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES (14001,4,6,0,0,0,2000,0,0,'Oh, thank heavens that you survived, $n! I thought for sure that you\'d drowned when I saw you go over the side!$B$B<Sassy\'s eyes fill up with tears as she hugs you.>$B$BLook at all of these folks you saved!',39804),(14442,0,0,0,0,0,0,0,0,'Have you come to assist me with my work? My claws are quite dexterous, but I must reluctantly confess that my arms are debilitatingly short.',41359),(24622,3,0,0,0,0,0,0,0,'Nice ta see new faces \'round here, mon. It\'s easy ta get ta feelin\' isolated since we left Orgrimmar.',39653),(24623,1,0,0,0,0,0,0,0,'Thank ya so much! They can be vicious when provoked, but most of da time dey don\'t know betta.',39653),(24624,1,0,0,0,0,0,0,0,'Thank you, $c.$B$BIt will be takin\' brave and determined people like you ta drive da Darkspear up again. I hope dere are more people even half as dedicated to come.',39653),(24625,1,273,0,0,0,60,0,0,'Well done, $n! Dis naga has set us back quite some time, but nothin\' will be holdin\' us down foreva.$B$BIt\'s good ta be havin\' ya wit us, $n. Ya have a fierce heart within ya.',39653),(24626,0,0,0,0,0,0,0,0,'Swiftclaw! Kijara was tellin\' me about him and he sounded like he\'d be a handful. I don\'t mind da challenge - it\'s da spirited ones like dat that be makin\' da bravest and truest companions when real times of need be comin\'.$B$BTank ya, hon. Ya\'ve been very helpful.',39653),(24812,1,0,0,0,0,0,0,0,'Well fought, young $r.',39653),(24813,1,0,0,0,0,0,0,0,'Dat should keep dem at bay.',39653),(24814,1,0,0,0,0,0,0,0,'Tha power dat burst forth when tha Sea Witch died was immense. I can use dis power ta enact a vision of places far away.$B$BObserve, youngblood. I want ya ta be here when I make contact wit\' Thrall, perhaps it will be grantin\' ya insight as well.',39653),(25035,1,0,0,0,0,0,0,0,'Good to have ya, $G brotha:sista;.$B$BVol\'jin makes us all proud in dese moments. It feels good ta be tacklin\' threats head on.',39653),(25073,1,0,0,0,0,0,0,0,'Welcome, young $r.$B$BYa come highly recommended, mon. It\'s nice ta finally be meetin\' ya in person.',39653),(26397,1,397,0,0,0,0,0,0,'The Grimtotem have been forced out of Mulgore? You must be a fierce warrior to earn the praise of Baine Bloodhoof. The Horde needs heroes, ones that hold honor in their hearts. Very well, $c. I accept you as one of us.\n\nFor the Horde!',39804),(26901,1,0,0,0,0,0,0,0,'Well done! This is just what we need, $n.',45338),(26905,0,0,0,0,0,0,0,0,'Take this gift. You have earned my blessing this day.',45338),(26906,0,0,0,0,0,0,0,0,'<The Spirit of Agamaggan looks at you. An ancient voice echoes inside your head.>$B$BI\'ve been waiting for you to come here.',45338),(26907,0,0,0,0,0,0,0,0,'You\'ve done well this day. Charlga\'s advisors are as much a threat as any.',45338),(27128,0,0,0,0,0,0,0,0,'Little $r did it! Now Horde more powerful than ever! YAR!',40725),(27185,275,0,0,0,0,0,0,0,'Nicely done, lad! Without them new weapons, they\'re just as easy t\' kill as they were when they were alive!',45338),(27208,1,0,0,0,0,0,0,0,'It\'s good we stopped Balnazzar now. Before long, his army would have overtaken all of Stratholme, giving him a powerful center for his new unholy empire.',45338),(27223,1,0,0,0,0,0,0,0,'You may have this as a suitable reward. I found it nestled in the armor of one of the scourge here.',45338),(27227,1,0,0,0,0,0,0,0,'Stratholme will become a paragon of all that is good in this world. You have my thanks for your part in this mission.',39427),(27228,1,0,0,0,0,0,0,0,'I respect the power you demonstrated in killing Ramstein. With proper rage backing your actions, I think even the Scourge can know fear.',39427),(27230,1,0,0,0,0,0,0,0,'Great! Without a steady flow of their weapons, we\'ll win through attrition!',39427),(27305,378,0,0,0,0,0,0,0,'Master Fordring will be glad beyond measure to see this painting again.',45338),(27352,4,0,0,0,0,0,0,0,'Excellent! I think the holy water will prove devastating in large volumes.',39427),(27359,1,0,0,0,0,0,0,0,'Oh my... the banshees are very tortured souls indeed. Merely holding their essence is emotionally painful...$B$BEnough of that for now. I\'ll get to work on counteracting their magic, then we\'ll have a portal up and running in no time. Stratholme will be ours soon, I just know it.',39427),(27440,0,0,0,0,0,0,0,0,'Pardon my saying so, but I am surprised you completed the task set out before you alive. Those monsters were responsible for the deaths of countless thousands, a great many of them heroes still spoken highly of to this day.$B$BYou have earned my respect and a reward for your courage.',40725),(27672,0,0,0,0,0,0,0,0,'Don\'t worry about the chamber, my boys will check it out! You have more important things to do!',45338),(27673,0,0,0,0,0,0,0,0,'This is incredible, $n. The power coursing through each core...the contrasting powers so close together!$B$BI\'ll take this to the proper dwarves right away. These cores are extremely important!',45338),(27676,71,0,0,0,0,0,0,0,'Fantastic! Great work! We\'ll know all that Dig Three has to tell us in no time at all!',45338),(27677,0,0,0,0,0,0,0,0,'Well done, lad! Now go to the discs and learn all you can!',45338),(27698,0,0,0,0,0,0,0,0,'Without her powerful servants, Princess Theradras is significantly more vulnerable. Find her lair, $n...it is time to strike.$B$B<You feel a sizable lump of gold appear in your bags, clearly a reward for your work here.>',45745),(28734,6,0,0,0,0,0,0,0,'Ilthalaine sent you? He was wise to do so. I am indeed in need of help.',37474),(28954,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28955,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28956,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28957,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28959,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28960,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28961,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28962,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28963,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28964,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28965,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28967,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28968,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28969,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28970,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28971,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28972,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28977,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28978,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28979,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28980,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28981,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28982,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28983,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28984,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28985,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28986,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28990,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(28991,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(29535,396,0,0,0,0,0,0,0,'These vials could mean the end of the fel orcs. I hope you understand just how important that is to our campaign here.',40944),(29536,396,396,0,0,0,0,0,0,'<You tell Caza\'rez everything you saw in the Blood Furnace.>$B$BI see.$B$BIf they can do this to the Mag\'har brown orcs, they can do it to us! We must be careful lest they turn all of Thrallmar into those mindless beasts.',40944),(29537,396,0,0,0,0,0,0,0,'The interference has gone down, but we still cannot access that area. We will continue to investigate the matter. Thank you for your help.',40944),(29598,6,0,0,0,0,0,0,0,'You are friends of Taretha? So this is her new plan? Very well then...',45745),(29599,1,1,0,0,0,0,0,0,'You have done a great thing, $n. Alas, the young warchief\'s memory of these events must be as they originally were...',45745),(29611,1,0,0,0,0,0,0,0,'Ahh, good. You\'re here. And not a moment too soon...',39804),(29650,0,0,0,0,0,0,0,0,'I will sing many songs of his glories.',39427),(29651,18,0,0,0,0,0,0,0,'Caza\'rez...is no more.',39427),(29653,0,0,0,0,0,0,0,0,'We should not forget the orc Kargath once was, nor the lessons to be learned from his downfall.',39427),(29655,0,0,0,0,0,0,0,0,'Well done. This will show those blood crazed monsters what they\'re up against.',39427),(29684,0,0,0,0,0,0,0,0,'...Come closer, $r... Listen carefully to my words....',41359),(29685,396,0,0,0,0,0,0,0,'<Larethor listens intently as you explain your deeds in Magisters\' Terrace.>$b$bTyrith will be missed - good man, that one. Thanks to you though, his death wasn\'t in vain.',41359),(29686,396,0,0,0,0,0,0,0,'Excellent! I can\'t wait to present this project to my superiors!',41359),(29687,113,0,0,0,0,0,0,0,'Well done, soldier. One step at a time.',41359),(29690,5,0,0,0,0,0,0,0,'$n!?$b$bThey told me you were dead...$b$bI\'m glad to see it wasn\'t true. There\'s Alliance to kill!',44908),(30112,66,0,0,0,0,0,0,0,'Revenge feels good.  To think that this is but a taste of what\'s to come.$B$BArthas will get what he deserves soon enough.',40944),(30969,1,0,0,0,0,0,0,0,'Good work, $n. This will make it very clear how Garrosh is going to deal with failures...',41079),(30983,1,0,0,0,0,0,0,0,'It would seem that the dark shaman experiments drove Gordoth insane.$b$bHopefully we\'ve seen the last of this, $n.',41079),(30984,396,0,0,0,0,0,0,0,'That\'s all that survived?$b$bI don\'t know who these Dark Shaman are working for, but they are going to pay for this.',41079),(31853,0,0,0,0,0,0,0,0,'Welcome aboard Hellscream\'s Fist, $n!$b$bThis\'ll be her maiden voyage. Ain\'t she a beauty?',44908),(32276,1,0,0,0,0,0,0,0,'With your help, we\'re one giant step closer to our goal.',44730),(32505,1,0,0,0,0,0,0,0,'Ah! To feel whole again! You have my gratitude, servant. Take this stone and use it wisely. Should you encounter his majesty the Thunder King in your travels, do not tell him where you received it, or you will be standing in a statue next to me for the remainder of eternity.',44730),(32525,1,0,0,0,0,0,0,0,'Their dead shall rise no more, thanks to you, $n. Excellent work.',44730),(32527,1,0,0,0,0,0,0,0,'Excellent. You have dealt the mogu a blow that they shall not easily forget.',44730),(32530,1,0,0,0,0,0,0,0,'I am glad to hear that this piece of filth is slain. You have done us all a great favor, $n.',44730),(32532,1,0,0,0,0,0,0,0,'Wonderful work, $c. This will help our offensive a great deal.',44730),(32533,1,0,0,0,0,0,0,0,'I am glad to hear that you left the quilen in a thousand tiny pieces. They are little more than a nuisance to my work here on the island.',44730),(32544,1,0,0,0,0,0,0,0,'I hope that creature has the intelligence necessary to know who saved it. It seems to me that it would be a dangerous foe if provoked.',44730),(32549,1,0,0,0,0,0,0,0,'<The voice of Archmage Vargoth echoes in your mind.>$b$bIs it done yet? Ah, good.$b$bI can complete the second half of the enchantment now. You will soon see your disguise appear. As long as you stay out of combat, the saurok should see you as one of their own.$b$bGood luck!',44908),(32550,1,0,0,0,0,0,0,0,'These trolls have been using dark magics to achieve their goals. No patience, no honor. You have done the world a good service in reducing their numbers today.',44730),(32552,1,0,0,0,0,0,0,0,'Well done, champion. These beasts are strong enough. We don\'t need them infused with an angry spirit now do we?',44730),(32554,1,0,0,0,0,0,0,0,'Very interesting results. I am sure there is a mage somewhere that cares about the specifics. I, on the other hand, am just glad to hear the sound of trolls being assaulted by their own beasts.',44730),(32555,1,0,0,0,0,0,0,0,'This is very interesting, $c. The crystal hums with the rage of its captive inhabitants. Even after the passage of time their devotion has not decreased.$b$bI will need to study this further.',44730),(32558,1,0,0,0,0,0,0,0,'It\'s a shame really that these masks must be destroyed. I would have liked to study this ancient magic, but it is better that they be destroyed than become the tools of the Horde.$b$bGood work, $c.',44730),(32560,1,0,0,0,0,0,0,0,'Well done, $c. The more Zandalari we destroy, the less chance their magic will fall into Horde hands.',44730),(32567,1,0,0,0,0,0,0,0,'Today, we hunt the hunters!',44730),(32568,1,0,0,0,0,0,0,0,'The Zandalari here are not to be under-estimated, $c. Powerful magic overwhelms this space.$b$bWe must be diligent in our efforts.',44730),(32572,1,0,0,0,0,0,0,0,'Your efforts are appreciated, $c.',44730),(32575,1,0,0,0,0,0,0,0,'When I give you a task, it gets handled.$B$BWell done, $c.',44730),(32581,1,0,0,0,0,0,0,0,'One less threat at our doorstep. Thank you, $n.',44730),(32586,1,0,0,0,0,0,0,0,'Time to push ahead - to the forge!',44730),(32587,1,0,0,0,0,0,0,0,'Good work. What you did today brings us one step closer to our ultimate goal.',44730),(32588,1,0,0,0,0,0,0,0,'Time to push ahead - to the forge!',44730),(32608,1,0,0,0,0,0,0,0,'What\'s this? A necklace? What are you trying to- ahh, I see... A relic from the Thunder King\'s vault! Fascinating... Powerful, too.$B$BThe Kirin Tor will keep it safe. In return, please accept this.',44730),(32644,1,0,0,0,0,0,0,0,'Yes! You have done it, champion!$B$BNow, the Thunder King will taste the full force of the Kirin Tor!',44730),(32652,1,0,0,0,0,0,0,0,'Incredible work. This presents us with a monumental opportunity.',44730),(32654,1,0,0,0,0,0,0,0,'With your help, we\'re one giant step closer to our goal.',44730),(32655,1,0,0,0,0,0,0,0,'Well done. That warship won\'t be raining fire on us again any time soon.$B$BTaran Zhu has informed me that the Shado-Pan will keep vigil over Stormsea Landing, freeing up Kirin Tor resources to press the siege elsewhere. Taoshi will be there. I am sure she will be glad to work with you again.$B$BWe are all grateful for your contributions, $n. Thank you.',44730),(32656,1,0,0,0,0,0,0,0,'You\'ve done it, $c! Shan Bu is dead once and for all, and we\'ve learned that Lor\'themar may not be all that he seems.',44730),(32664,0,0,0,0,0,0,0,0,'Don\'t forget to buy your mount while you are here! You can buy one from Lelanai right here.',37474),(32670,0,0,0,0,0,0,0,0,'Don\'t forget to buy your mount while you are here! You can buy one from Harb Clawhoof over there.',39804),(32672,0,0,0,0,0,0,0,0,'Don\'t forget to buy your mount while you are here! You can buy one from Zachariah Post here.',36753),(32731,1,0,0,0,0,0,0,0,'Yes, good, come... there is work to be done.',44730),(32732,1,0,0,0,0,0,0,0,'You have good timing. I am quite in need of your assistance.',44908),(32733,1,0,0,0,0,0,0,0,'One more to join the Zandalari hunt?  Good.  Very good.',44730),(33125,0,0,0,0,0,0,0,0,'You bring honor to the clan by giving my family a proper burial, $n.',37988),(33132,0,0,0,0,0,0,0,0,'Wolfchew is defeated? *cough* Glorious.',37988),(33662,0,0,0,0,0,0,0,0,'Good work, but we need to move quickly before the plants realize the way is open...',37988),(34012,0,0,0,0,0,0,0,0,'<Prowler Sasha nods and assembles two necklaces.>',37988),(34066,66,0,0,0,500,0,0,0,'You have done well, $c.$b$bNow before we can continue our assault we need to look for any supplies in the area that could help our fight.',37988),(34067,0,0,0,0,0,0,0,0,'Rope? Do you expect me to tie a noose and ask the Thunderlords to go hang themselves?$b$bWait... that gives me an idea. Yea, I think I can make this work with the right materials.$b$bGood Job.',38556),(34069,0,0,0,0,0,0,0,0,'Hrm, yes these spears look pretty good.$b$bNot bad! I know just what to use these for!',37988),(34072,0,0,0,0,0,0,0,0,'Ugh, those smell awful! No, I don\'t need to see them. I\'ll take you at your word that you have them all.$b$bLet\'s get a move on before another Thunderlord patrol stumbles upon me.',38556),(34227,1,1,0,0,0,3000,0,0,'Unfortunate that there are those that would pervert such noble creatures.$B$BYou have honored their family once more, $n. They will not forget.$B$BNow it is time to take the fight directly to the Shadow Council.',37988),(34228,274,273,0,0,0,3000,0,0,'We haven\'t seen these creatures here in a generation.$B$BTheir sudden appearance and the shaking of the ground are most definitely connected.',37988),(34229,273,274,25,0,0,3000,3000,0,'I\'ve heard of these strange Pale orcs you saw. They sound like the Warsingers of Nagrand. But no, that cannot be....$B$BAs for the ogre, his name is Cho\'gall. You should kill him if you get the chance. He brings nothing but destruction in his wake.',37988),(34230,273,0,0,0,0,0,0,0,'Yes, this will do nicely. Let\'s use the Shadow Council\'s magic against them.',37988),(34277,5,0,0,0,0,0,0,0,'We should have killed them all at the Dark Portal in the beginning and damn the consequences.',37988),(34278,274,25,0,0,0,3000,0,0,'For what they\'ve done, it is not enough.$B$B$n, when you find their base, you salt the earth.',37988),(34280,1,0,0,0,0,0,0,0,'Gul\'dan is there! We must move quickly to capture him.',37988),(34291,1,0,0,0,0,0,0,0,'A heart? How touching.$B$BQuickly. We must use it to destroy the fel crystals and get to Gul\'dan.',37988),(34292,1,0,0,0,0,0,0,0,'Necessary business. We don\'t dare risk letting them grow more powerful.',37988),(34294,1,0,0,0,0,0,0,0,'The barrier is down. Now it\'s time to capture Gul\'dan.',37988),(34295,2,1,0,0,0,3000,0,0,'Unfortunate, but not surprising. At least we were able to defeat one of the inner council members.$B$BAll is not lost, $n. We know what the Shadow Council is up to and where they\'re heading.$B$BWe\'ll regroup in Talador. Together, we\'ll put an end to Teron\'gor and his plans for Auchindoun.$B$BDid you hear that?...',37988),(34447,0,0,0,0,0,0,0,0,'A wise elder of my order once told me, \"True power is the strength to act and the wisdom to know when not to act.\" May those words and the memory of Kaelynara stay with you on your journey, $n.',38134),(34569,1,0,0,0,0,0,0,0,'You\'re the one in charge around here, right? I\'ve heard the guards talk about your exploits and if I wasn\'t looking at you now I\'d swear they were lying.$b$bI\'ve only ever wanted to make the finest blades and put them in the hands of the strongest of fighters. I can tell already that you\'re exactly the type I want to carry my weapons.$b$bIf you can give me a chance I swear you will not be disappointed.',37988),(34576,1,0,0,0,0,0,0,0,'This won\'t be as good as some of the mixes we had back in the Blackrock foundries, but it will do.',37988),(34577,0,0,0,0,0,0,0,0,'Good size chunks and without a lot of the matrix material on them.$b$bThese will do just fine.',37988),(34579,66,1,0,0,0,500,0,0,'Thank you boss, this is just what I needed.$b$bBy the way, Goren gas is rather difficult to come by. We should probably hold off on clearing those guys out till we can stockpile enough.$b$bJust a thought.',37988),(34673,0,0,0,0,0,0,0,0,'Dat was amazin\', $n! De Old Gods be thinkin\' twice before tryin\' to take anudder bite outta you, mon.',41079),(34697,0,0,0,0,0,0,0,0,'The Laughing Skull sent you? If they were any other clan I would find that ironic.$b$bI am Kash\'drakor, hero of the Frostwolf clan, and champion of the slave pits of Stonemaul.$b$bAnd yet, despite all these titles, I need your help.',37988),(34698,0,0,0,0,0,0,0,0,'You have shown more honor in this one act than I have seen in many years.$b$bWhen this is over, I will swear my axe to your forces and pass my knowledge on to your troops.',37988),(34699,153,0,0,0,0,0,0,0,'Thank you, strange one. Now we are free to split that chieftain Kor\'gall wide open!',37988),(34700,66,0,0,0,0,0,0,0,'This deed will never be forgotten as long as I or my son live. You have my gratitude, hero, and my loyalty.',37988),(34702,0,0,0,0,0,0,0,0,'Me watch you from afar. Me like your fighting skills, show much promise.',37988),(34703,0,0,0,0,0,0,0,0,'This blade has caused enough pain and suffering for one lifetime. We shall see to it that it is properly disposed of.',37988),(34704,0,0,0,0,0,0,0,0,'You do not have the look of a Stonemaul bounty hunter.$b$bWe escaped the clutches of their vile arena but at a heavy cost. We were forced to leave too many allies behind and too many ogres breathing.$b$bWe could use a fresh face, one that is unknown to the ogres.',37988),(34837,1,273,0,0,100,1100,0,0,'I crafted a few things before we left that we may need: some bombs, a grappling hook, even was able to get one of the goblins to get a spare rocket pack.$b$bI\'m sure we\'ll find a use for everything.',38134),(34840,0,0,0,0,0,0,0,0,'Now that we\'re inside we have much to do.',38134),(34855,1,11,0,0,0,600,0,0,'Now with the viziers gone the whole Gordunni enchantment trade with the Iron Horde will come crashing down!$b$bWe can now turn our attention to dealing with Morkurk.',38134),(34858,0,0,0,0,0,0,0,0,'Thank you, commander. With this another stain on my honor has been removed.',38134),(34860,1,11,0,0,0,1000,0,0,'Alright, that should be the last one we need. $b$bNothing feels as good as knowing you are stronger than your enemy!',38134),(34870,1,1,0,0,0,500,0,0,'Fine work commander! Your combat skills are clearly second to none. I am honored to be your armorer!$b$bLet\'s get back to the outpost so we can take stock of our new inventory. I saved a few flares to call us in a ride back.',38134),(34948,0,0,0,0,0,0,0,0,'These orders appear to have come from Orgrim Doomhammer.',37988),(34971,1,4,0,0,0,700,0,0,'The outpost is now fully up and running and we have enough material to outfit an army - your army!',38134),(34972,1,2,0,0,0,500,0,0,'It took a lot of hard work but we have made a beautiful arsenal here.$b$bSir, I\'ve been able to outfit your soldiers here with new equipment but I\'d like to do more.$b$bI\'d be deeply honored if you would let me work for you in your main garrison.',38134),(35025,1,0,0,0,0,0,0,0,'Thank you, friend. I am in your debt.$b$bThis arrogant Iron Horde has made a dangerous enemy today.',37988),(35026,0,0,0,0,0,0,0,0,'<Nisha laps up the water.>',37988),(35035,11,0,0,0,0,0,0,0,'Watch them burn!',37988),(35036,5,0,0,0,0,0,0,0,'That half-orc burned my toes!',37988),(35037,396,0,0,0,0,0,0,0,'They are enslaving gronn? This is an even bigger problem than it might seem.',37988),(35038,0,0,0,0,0,0,0,0,'Yes... we don\'t need their bones, but we do need their crystals.',37988),(35041,396,0,0,0,0,0,0,0,'It is good that you still have your wits about you. You do... have your wits about you?',37988),(35102,1,0,0,0,0,0,0,0,'We have a lot of basic arms here but I\'ll get them improved in no time.$b$bThanks for giving me this chance.',37988),(35128,0,0,0,0,0,0,0,0,'Most people cannot handle ogron in single combat.',37988),(35129,396,0,0,0,0,0,0,0,'We have the notes. Let us see what they reveal about our enemy\'s strategy.',37988),(35136,0,0,0,0,0,0,0,0,'Good work, $n. We can use this artifact against the Iron Horde when the time is right.',37988),(35137,0,0,0,0,0,0,0,0,'Now that we have the trainers, we can start training your forces to do something other than chop lumber. Heh heh.',38556),(35139,0,0,0,0,0,0,0,0,'Good. We know where we must go to acquire the artifact.',37988),(35152,11,0,0,0,0,0,0,0,'Kash\'drakor is coming here?! Ha! I once saw him cut through a dozen Laughing Skulls because they had his son.$b$bHe is the purist expression of destruction.',37988),(35202,396,0,0,0,0,0,0,0,'Ahh, yes. Xuk is one step closer to performing a miracle.',37988),(35210,0,0,0,0,0,0,0,0,'Those goren tunnels have proven useful.',37988),(35247,0,0,0,0,0,0,0,0,'The spirits of my ancestors have betrayed me! Their skulls are surely laughing.',37988),(35248,0,0,0,0,0,0,0,0,'I like killing things. And bones.',37988),(35664,0,0,0,0,0,0,0,0,'The ancients should not be a problem for your outpost for some time.',37988),(35665,0,0,0,0,0,0,0,0,'Thank you, friend. I am in your debt.$b$bThis arrogant Iron Horde has made a dangerous enemy today.',37988),(35686,0,0,0,0,0,0,0,0,'These creatures are relentless in their assault against one another.',37988),(35693,0,0,0,0,0,0,0,0,'You have a true talent for combat.',37988),(35702,0,0,0,0,0,0,0,0,'Yes... Think of the orcs that will fall before us with this power...',38556),(35730,0,0,0,0,0,0,0,0,'Thank you. Her wounds have closed.',37988),(35819,4,0,0,0,0,0,0,0,'The Laughing Skull have always steered clear of that area because Khargax was very quick for such a huge beast. They will be pleased to know their eaten dead have been avenged.',37988),(35870,0,0,0,0,0,0,0,0,'<Nisha downs the meat in one gulp.>',37988),(35880,0,0,0,0,0,0,0,0,'I can see the future of my enemies in the bones. They\'re gonna die!',37988),(35882,11,0,0,0,0,0,0,0,'Now THAT is how you break out of a gladiator pit!$b$bYou are fun. Your weapons are covered in a rainbow of blood types.$b$bI am going to follow you now.',37988),(35883,66,0,0,0,0,0,0,0,'For years the ogres would make me fight, kill, and salute. My soul bled with each salute.$b$bBut because of you, I will never again have to salute an ogre.$b$bYou have helped me win my freedom, so I choose to use that freedom to serve your banner.$b$bToday, I salute you, commander.',37988),(35925,396,0,0,0,0,0,0,0,'This is grim news, $n.',37988),(35934,396,0,0,0,0,0,0,0,'Thank you, $n. Nisha is nearly returned to health.',37988),(35948,0,0,0,0,0,0,0,0,'We are impressed with your ability to slay the goren. They are relentless and voracious and can overwhelm those are not prepared.',37988),(36078,0,0,0,0,0,0,0,0,'A gladiator saw you tear this off the back of a gronnling, which I am sure did not part with it easily. It is more like a stone than a true scale though as these brutes are part stone it seems. Not an easy trophy to collect!',38556),(36080,0,0,0,0,0,0,0,0,'A gladiator saw you tear this off the back of a gronnling, which I am sure did not part with it easily. It is more like a stone than a true scale though as these brutes are part stone it seems. Not an easy trophy to collect!',37988),(36081,0,0,0,0,0,0,0,0,'A gronn\'s eye is not something they part with alive. Your gladiator described a fight hard won and this trophy is a testament to your abilities.  Well done!',38556),(36208,0,0,0,0,0,0,0,0,'Goren crystals are used by some as weapons. The acid left behind can be deadly though, even to the wielder.',37988),(36209,0,0,0,0,0,0,0,0,'Your search brought rewards?',37988),(36210,0,0,0,0,0,0,0,0,'Ah, yes, these shells will work perfectly.',37988),(36223,0,0,0,0,0,0,0,0,'We have the notes. Let us see what they reveal about our enemy\'s strategy.',37988),(36438,0,0,0,0,0,0,0,0,'You have strong friends $p. We must make haste before the plants realize the way is open.',38556),(36508,0,0,0,0,0,0,0,0,'Thank you for vouching for me, commander.',37988),(36832,1,0,0,0,0,0,0,0,'If my spirits aren\'t with Xuk, Xuk isn\'t with them. You though, Xuk likes you.',37988),(37326,396,0,0,0,0,0,0,0,'Ah, so you are the one your people spoke of so highly. We may discuss an alliance, but first...',38134),(37328,396,0,0,0,0,0,0,0,'Excellent. We have more immediate concerns to deal with until he visits.$B$BDark Ranger Velonara requires your immediate attention, $Gsir:maam;.',38134),(39262,5,0,0,0,0,0,0,0,'I KNEW that I\'d sensed something foul!',52129),(40643,1,0,0,0,0,0,0,0,'$n, I\'m pleased you came on such short notice.$b$bWe have a great undertaking here in the Moonglade that is about to begin, one in which you will play a key role.',44908),(40644,1,0,0,0,0,0,0,0,'Well done, $n!$b$bNow that the path is open we can begin our journey to Val\'sharah.',44908),(40645,1,0,0,0,0,0,0,0,'You did well to navigate through the Emerald Dream to get to this place. Still, there are times when you might wish to return here a bit more quickly. This spell will guide you.$b$bTraveling the Dreamway is no small feat in itself, but it pales to the tasks ahead.',44908),(40840,1,0,0,0,0,0,0,0,'Well chosen.',41079),(40950,1,0,0,0,0,0,0,0,'It seems you struck a nerve.',41079),(40996,1,0,0,0,0,0,0,0,'I don\'t know nothin\' about nobody.$B$BOh, who I am I kiddin\'? I know everything about everybody! How\'s it goin\', Shadow $n?',41079),(40997,273,0,0,0,0,0,0,0,'Great choice! We have tons of intel on that place.',41079),(41106,1,0,0,0,0,0,0,0,'Good, soon the ritual will be ready to begin.',44908),(42501,0,0,0,0,0,0,0,0,'<The coded message you found is sure to contain a lead on the cult\'s activities. You need only a way to decipher its contents.>',41079),(42502,0,0,0,0,0,0,0,0,'<The cipher you found will allow you to intercept the cult\'s communications, bringing you one step closer to Garona.>',41079),(42503,0,0,0,0,0,0,0,0,'<This does not bode well for the citizens of Darkshire.>',41079),(42539,0,0,0,0,0,0,0,0,'<Your next destination is clear: Stormwind. But where is Garona?>',41079),(42568,396,0,0,0,0,0,0,0,'If you\'re with me, drench your blades with poison now. This is going to get bloody.',41079),(42627,396,0,0,0,0,0,0,0,'Every second I held those blades again was torture. They\'re all yours.',41079),(45383,0,0,0,0,0,0,0,0,'The power these fragments hold will allow me to call the talisman to us. Well done!',38134),(46930,1,0,0,0,0,0,0,0,'Your deeds had reached my ears before your feet ever set foot in my land. It is time we spoke.',45745),(46931,1,1,0,0,0,0,0,0,'My father believes he is indulging me. He has ruled for two hundred years, many lifetimes of trolls. In his mind, de threats dat face our kingdom are minor.\n\nI have seen too much to believe dat.\n\nSo since my father and his advisors would not help, I turned to someone who would.\n\nYour warchief needs our fleet, and I need her champions. I have a battle plan here on what to do.\n\nChoose your first move. If de Horde helps my people, den I will help de Horde.',45745),(46957,0,0,0,0,0,0,0,0,'Dat is far enough, Horde scum.',45745),(47148,0,0,0,0,0,0,0,0,'Even I didn\'t see that coming.',38556),(47727,0,0,0,0,0,0,0,0,'With the remnants of this seal, we can dispel the wards and enter my sanctum.',38556),(48962,1,0,0,0,0,0,0,0,'And so ends the tale of how the void elves joined the Alliance. \n\nTheir control over the void swung the odds in our favor in several battles.\n\nSome fear their use of the void, but I believe Umbric and Alleria have a unique perspective on things.\n\nThey are both aware of forces attempting to control and manipulate us. It\'s an important lesson for us all to remember. Are the decisions we make our own, or are they being twisted by an unseen hand?',38134),(49135,1,1,0,0,0,0,0,0,'With these sigils, the Vindicaar can bypass the Burning Throne\'s defenses.$b$bThe time has come to press our advantage and end this war.',45114),(49266,1,0,0,0,0,0,0,0,'T\'paartos is... enthusiastic. He means well, and he has a fire within him that few even among the Lightforged possess. Thank you for keeping him safe, $r.',38134),(49615,0,0,0,0,0,0,0,0,'Very prompt. Now, I have need of your hands.',38134),(49698,1,0,0,0,0,0,0,0,'Welcome, $n. You are about to bear witness to a ritual none but members of the Army of the Light have seen.',38134),(49773,6,0,0,0,0,0,0,0,'Are you the new one? I\'m supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>',46340),(49787,1,0,0,0,0,0,0,0,'Umbric\'s methods are a bit cavalier, but he seems competent. We must get to him before things become too dangerous.',38134),(49933,6,0,0,0,0,0,0,0,'Are you the new one? I\'m supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>',40906),(50071,1,0,0,0,0,0,0,0,'I love the tale of the Lightforged draenei. Dedicated to the Light and eradicating all evil!\n\nIt is important to remember they are no strangers to weakness. T\'paartos faced his weakness in order to ascend. \n\nWe must remember that we all have our flaws, but together we can overcome them.',38134),(50335,0,0,0,0,0,0,0,0,'The uprising quelled, the elements calmed, and Hogger slain... I cannot thank you enough, $n. My people have been avenged.\n\nThank you.',41079),(50336,0,0,0,0,0,0,0,0,'I\'d love for you to come aboard as a full G-Team Commando, but our bylaws specifically prohibit Horde team members; however, I CAN enroll you in the G-Team Fan Club!$B$BHere\'s something for your trouble.',39335),(50337,0,0,0,0,0,0,0,0,'Took you long enough. Get behind the pillar before you blow our cover!',39335),(50338,0,0,0,0,0,0,0,0,'The mission is far from over!',39335),(50599,0,0,0,0,0,0,0,0,'Good work!',38134),(50769,0,0,0,0,0,0,0,0,'Well, here we are. Zuldazar. We had better stick with Talanji and Zul for now. The Warchief will be interested to know what happens next.',45745),(51072,66,0,0,0,0,0,0,0,'You faced down those Thumpknuckles? Dat is worth a lot to us. Thank you.',38556),(51421,1,0,0,0,0,0,0,0,'Welcome ta Tiragarde, boss-mon. Ya ready to be parleyin\'?',45745),(51443,0,0,0,0,0,0,0,0,'The Dark Lady has placed her trust in us. We will not fail her, $n.',45745),(51485,6,0,0,0,0,0,0,0,'Are you the new one? I\'m supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>',40725),(51796,1,1,0,0,0,0,0,0,'Our war has only begun.',38134),(51803,1,0,0,0,0,0,0,0,'You have the Queen\'s trust. For now.',45745),(52749,273,0,0,0,0,0,0,0,'You\'re here.',45745),(53052,1,0,0,0,0,0,0,0,'Welcome back, $n. Let\'s get to work.',38134),(53115,1,1,0,0,0,0,0,0,'<Jani sniffs the air, smelling your wet garbage.>\n\nYa brought ol\' Jani a present! What ya got there? Let me see it.\n\n<Jani begins rooting through the pile of trash you have brought.>\n\nOh, yes, and some of this, mmm, mmmhm, yes, oh that\'s sticky...\n\n<Jani seems pleased with your offering, and is paying no attention to you any longer.>',40725),(53372,1,1,0,0,0,0,0,0,'The Alliance moves against the Undercity, seeking retribution for the burning of Teldrassil.\n\nWe will not allow them to take what is ours, $c.',38134),(53502,1,0,0,0,0,0,0,0,'Lots of new things to cut around here, if you know what I mean. I mean I like to cut things.\n\nDo you like to cut things? Maybe we can cut things together one day.',40725),(53711,5,1,0,0,0,3000,0,0,'Everyone in Boralus cheered when we saw the explosions up on that airship! The Horde will think twice before assaulting Boralus again.',38134),(55137,6,0,0,0,0,0,0,0,'Are you the new one? I\'m supposed to welcome you. Here, take this letter.\n\n<Blackguard lets out an exasperated sigh.>',44908),(55509,66,0,0,0,0,0,0,0,'It is a truly great thing you have accomplished this day. Be recognized for your sacrifice!',39229),(55511,66,0,0,0,0,0,0,0,'Lok\'tar! Victory for the Horde!',38556),(56031,1,0,0,0,0,0,0,0,'You\'re just in time, $n. \nSpymaster Shaw was just informing me of some new intelligence we\'ve recently learned about the Horde fleet.',38134),(56042,0,0,0,0,0,0,0,0,'OUTPUT: Please accept this GIFT. \n\nADMINISTER GIFT DISTRIBUTION PROTOCOL.',39229),(56470,0,0,0,0,0,0,0,0,'Wonderful! This will make something tasty!',37176),(56829,1,0,0,0,0,0,0,0,'Ah good. No one got ate.\n\nCarriage is ready to go when you are.',36734),(56942,1,0,0,0,0,0,0,0,'We are not getting the carriage through that.',36734),(56955,1,0,0,0,0,0,0,0,'Your talents in combat show promise. Perhaps with a few more centuries and a little humility we might make something of you.',36734),(56978,1,0,0,0,0,0,0,0,'It may not look like it, but this rebellion is on its last leg. Those who stand against the Master are fools who will know a new form of pain and suffering.',36734),(57007,1,0,0,0,0,0,0,0,'Oh good, still not dead yet?\n\nYou see where the Lord Chamberlain or Cudgelface landed?',36734),(57025,1,0,0,0,0,0,0,0,'Sorry for the state of things. Usually a venthyr would be here to greet you. Been a while since we seen anyone come through that gate.\n\nAll good, though, as I know the welcome speech better than a good mornin\' whipping.',36734),(57026,1,0,0,0,0,0,0,0,'Hopefully these wretched creatures did not bore you with their inane babble.',36734),(57037,669,0,0,0,0,0,0,0,'I can hear their song once more. It is a boon on my mind, but the loudest voice remains. We must silence it before it destroys all that we hold dear.',36710),(57098,1,0,0,0,0,0,0,0,'Welcome to the Grove of Terror.\n\nHere you will see the beginning of the process for the anima you seek.',36734),(57131,1,0,0,0,0,0,0,0,'Well done. Perhaps in death you will make a fine hunter.\n\nI can practically taste the fear we will inflict.',36734),(57136,1,0,0,0,0,0,0,0,'Well done. The fear we struck allowed us to extract ample anima for Revendreth.\n\nOnto our final target.',36734),(57159,1,0,0,0,0,0,0,0,'We barely made it. Denathrius will surely be on our trail soon.',36734),(57161,1,0,0,0,0,0,0,0,'<Echelon grunts.> You\'re late.',36734),(57164,1,0,0,0,0,0,0,0,'Once you master fear, all crumble before you.',36734),(57173,1,0,0,0,0,0,0,0,'Is that truly the best you have to offer?',36734),(57174,1,0,0,0,0,0,0,0,'This is all that remains of our tithe? The Tithelord is not one for excuses. We may need to gather a second tithe quickly or he will condemn us all to the Ember Ward.',36734),(57175,1,0,0,0,0,0,0,0,'<As Echelon holds the sinstone fragments, anima binds draw the pieces into one another, reforming into a completed sinstone.>\n\nWe are ready to proceed.',36734),(57176,1,0,0,0,0,0,0,0,'This is, in fact, one of the larger sinstones I have seen.\n\nThis will be easy to exploit.',36734),(57178,1,0,0,0,0,0,0,0,'Wait! Please, Maw Walker, allow me to announce you to the Master.',36734),(57179,1,0,0,0,0,0,0,0,'Now, Maw Walker, arise as a weapon of ordained power within my dominion.',36734),(57180,1,0,0,0,0,0,0,0,'<Lord Chamberlain smiles wryly.>\n\nThe Halls of Atonement are under my control.',36734),(57182,1,0,0,0,0,0,0,0,'<Sire Denathrius smiles as you hand him the medallion.>\n\nI am pleased to see that you can be trusted with great power.',36734),(57189,1,0,0,0,0,0,0,0,'Sounds like it worked better than expected. \n\nPerfect. The Fearstalker stands no chance.',36734),(57190,1,0,0,0,0,0,0,0,'The devourers will rip them to shreds.',36734),(57240,0,0,0,0,0,0,0,0,'You no go here. Here for bad buds!',36734),(57245,0,0,0,0,0,0,0,0,'These reanimated troops will be put to good use.',36949),(57249,1,273,0,0,0,0,0,0,'Welcome! It\'s that special time of year when the bronze dragonflight celebrates all that has happened over the years and you, $n, are the guest of honor!\nCome celebrate at the grand feast, get down at the \"Disco of Time\", or accept a quest to fend off some of Azeroth\'s greatest threats.',41031),(57263,1,0,0,0,0,0,0,0,'<Sika pokes the squishy substance.>\n\nIt glows. This means anima. Forgelite will be pleased.',36710),(57264,669,0,0,0,0,0,0,0,'Your service is noted. Thank you.',36710),(57265,1,0,0,0,0,0,0,0,'That is... somehow more and less than I expected. It will have to do.',36710),(57266,669,669,0,0,0,0,0,0,'This is a moment worthy of celebration, $n.\n\n<Kleia smiles broadly at you.>\n\nYou have done it. They have come.',36710),(57267,1,0,0,0,0,0,0,0,'Oh. They smell nice! And they glow lots.\n\nThis is good. Yes.',36710),(57269,669,669,0,0,0,0,0,0,'That you should join us now, on the precipice of this treachery, is curious.\n\n<The Paragon of Purity studies you with a piercing gaze.>\n\nYou have done well. The Archon will know of your contributions this day.',36710),(57270,669,0,0,0,0,0,0,0,'Thank you for volunteering.',36710),(57278,1,0,0,0,0,0,0,0,'I have asked many others to collect heads as well! So even if none of these are the traitor\'s head, we shall find it eventually!',38556),(57288,669,0,0,0,0,0,0,0,'Impressive. I see I have little enough to teach you.',36710),(57291,669,0,0,0,0,0,0,0,'Gather yourself. This is how you will find your way before the Archon. I am certain of it.',36710),(57301,0,0,0,0,0,0,0,0,'You may continue to add as many ingredients as you wish. The more we add, the more we create!',38556),(57316,1,603,0,0,0,0,0,0,'Well fought, $Gbrother:sister;! You\'ve begun your rise to the top!\n\nBut keep up with your training and stay ready. In Maldraxxus, there is always a challenger waiting to take your place.',38556),(57380,1,0,0,0,0,0,0,0,'This bad paper look very bad...',36734),(57381,1,1,0,0,0,0,0,0,'That was FUN! I have not felt so alive in centuries. Everything about you is just... different, and invigorating.\n\nI can continue to assist you until you are ready to leave the Endmire but then we will need to part ways for a time. I have some unfinished business regarding someone who put me in a cage.',36734),(57386,1,0,0,0,0,0,0,0,'Well? Why aren\'t you out there fighting?',36710),(57390,0,0,0,0,0,0,0,0,'You survived? Really...\n\nI admit, that was unexpected.',36710),(57405,1,0,0,0,0,0,0,0,'Well, aren\'t you an unexpected windfall?\n\nI\'m afraid I\'ve no tea to offer you at the present. Forgive my poor manners.',36734),(57425,1,0,0,0,0,0,0,0,'In ages past, the Primus founded that tournament to showcase the might of Maldraxxus. \n\nToday, it has sparked an all-out war.',36710),(57426,1,0,0,0,0,0,0,0,'<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nJustice... for parasols... everywhere...',36734),(57427,1,0,0,0,0,0,0,0,'<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nMy... sincerest apologies...',36734),(57428,1,0,0,0,0,0,0,0,'<Exposure to the Light is clearly causing Theotar to lose control of himself.>\n\nGubbins... Where are you?',36734),(57442,1,0,0,0,0,0,0,0,'<Gubbins and Tubbins speak in unison.>\n\nDis not good.',36734),(57444,669,0,0,0,0,0,0,0,'I saw them perish. It is more than they deserved.',36710),(57446,669,0,0,0,0,0,0,0,'Our fight is not yet over, $n.',36710),(57447,669,0,0,0,0,0,0,0,'We will see not a moment\'s rest today, will we?\n\n<Kleia eyes the fragment warily.>',36710),(57454,1,0,0,0,0,0,0,0,'Finally, a friendly face! Are you with the Hunt? You don\'t look like you\'re from around here....',37474),(57455,1,0,0,0,0,0,0,0,'Their bodies will nourish the growth and restoration of the fae rings. It is a worthy end for them.',37474),(57458,1,0,0,0,0,0,0,0,'Together we are strong.',37474),(57459,1,0,0,0,0,0,0,0,'<About time you showed up! Good thing I took care of all those young ones, eh?>',37474),(57460,1,0,0,0,0,0,0,0,'Tea ready! Tubbins give to Theotar!',36734),(57461,1,0,0,0,0,0,0,0,'<Theotar takes a slow sip from his tea cup.>\n\nWhat a delightful stroll!',36734),(57463,1,0,0,0,0,0,0,0,'Hah! I haven\'t felt that young in ages!',37474),(57470,0,0,0,0,0,0,0,0,'Gharmal\'s gluttony knew no bounds.',37176),(57471,1,0,0,0,0,0,0,0,'I can smell it from here. Thanks for that, $n.',36949),(57473,0,0,0,0,0,0,0,0,'The Mantle of the Primus... \n\nFate favors us today.',37176),(57474,1,0,0,0,0,0,0,0,'Got a bit of devourer gunk on it, but it will have to do.',36949),(57475,0,0,0,0,0,0,0,0,'I\'ll send scouts to continue the search, but this... this is a huge boon for us.',37176),(57477,1,0,0,0,0,0,0,0,'Bootus ready.',36949),(57481,1,0,0,0,0,0,0,0,'Nice work, $n. \n\nBigguns can be... a bit much sometimes.',36949),(57511,0,0,0,0,0,0,0,0,'And now we test them.',36710),(57512,1,0,0,0,0,0,0,0,'Everything in this land is dangerous. There is no room for weakness.',36710),(57514,1,0,0,0,0,0,0,0,'Mark my words, recruit. We will crush the other houses for their acts of treason.',36710),(57515,1,0,0,0,0,0,0,0,'The Chosen are all that remains of what the Primus stood for.\n\nWe are the last hope of this realm.',36710),(57516,1,0,0,0,0,0,0,0,'This blade was inside the stone all this time... \n\nMargrave Krexus was right about your potential.',36710),(57529,6,0,0,0,0,0,0,0,'Oh, you\'re here to lend a hand? Wonderful!',36710),(57530,0,0,0,0,0,0,0,0,'That is definitely something. Let\'s open it and find out.',37176),(57532,1,0,0,0,0,0,0,0,'This must be some sort of mistake!',43206),(57533,1,0,0,0,0,0,0,0,'You freed them, yes? Let us hope they found some small sliver of respite, where the Light cannot reach.',43206),(57534,1,0,0,0,0,0,0,0,'I thought I knew our sire, but anyone who would do this to his subjects is not worth following.',43206),(57535,1,0,0,0,0,0,0,0,'<Laurent carefully examines the fragments before speaking.>\n\nYes, these should work. I\'m almost certain.',43206),(57536,1,0,0,0,0,0,0,0,'Simone is right. We don\'t have time for idle chatter. Not here, at least.\n\nThe mirror we\'ve repaired will take you to safety.',43206),(57538,1,0,0,0,0,0,0,0,'We can now better fulfill our duties here. I look forward to resuming my meditations. Thank you.',36710),(57545,1,0,0,0,0,0,0,0,'Kala! Look! $n brought back your favorite things!',36710),(57547,1,0,0,0,0,0,0,0,'I told you she can be quite the troublemaker. Ugh, Kala!',36710),(57568,1,0,0,0,0,0,0,0,'With the crook and Korinna\'s guidance, I can begin to bring this place and its creatures back to their former state of respite. Thank you, $n.',36710),(57571,1,0,0,0,0,0,0,0,'Denathrius may not have set the mirrors, but it\'s his fault I am here.\n\nThose that rouse his suspicion are sent here to suffer, even once loyal servants like myself.',43206),(57583,1,0,0,0,0,0,0,0,'Ahh, it\'s nice to stretch out again. I\'ve missed this place, you know.\n\n<Marasmius pauses for a moment.>\n\nDon\'t tell anyone here I said that, all right?',37474),(57636,0,0,0,0,0,0,0,0,'We must find the source of Gharmal\'s stockpiled anima. But for now, let us enjoy our victory.',37176),(57644,1,0,0,0,0,0,0,0,'Thank you for returning me to my sister.',37176),(57646,1,0,0,0,0,0,0,0,'A Maldraxxus archlich manipulating our Harvesters... This cannot go unanswered.\n\nI am pleased that Baroness Draka is equally eager to strike at Kel\'Thuzad directly.\n\nGeneral Draven will ready our armies while Laurent repairs the mirror. Be ready and take these as we prepare. We will ensure vengeance is met alongside our new allies.',43206),(57648,0,0,0,0,0,0,0,0,'You\'ve done well, Maw Walker.',37176),(57649,1,0,0,0,0,0,0,0,'The baroness inspires great dedication. I trust in her plans.',37176),(57651,1,0,0,0,0,0,0,0,'Ah, the Lady sent you? Well, I have some bad news.',40593),(57652,5,0,0,0,0,0,0,0,'It really is a remarkable substance. We use it in practically everything! Construction, mending, crafts, and it can even be added to rations.',40593),(57653,1,0,0,0,0,0,0,0,'Thank you for rescuing them.',40593),(57655,1,0,0,0,0,0,0,0,'I\'m glad you found my note. Husks such as these need to soak in running water for several days before they can be shaped without breaking.$b$bAt least you were able to salvage something.',40593),(57656,1,0,0,0,0,0,0,0,'Good. This should do it!',40593),(57657,1,0,0,0,0,0,0,0,'Fluttercatch always was a clever one. Well done.',40593),(57661,30,30,0,0,0,0,0,0,'Of course silk shipments have stopped!\n\nThe entire glade has been attacked by changelings and spriggans! Our poor silkstriders are so stressed out, we can\'t get any silk from them!\n\nCan you help us?',39427),(57676,669,0,0,0,0,0,0,0,'The things that bind us can be violent. The insight we gain is no reason to let them run rampant.',36710),(57677,669,0,0,0,0,0,0,0,'I owe you a great debt, $n.',36710),(57689,1,0,0,0,0,0,0,0,'So this is the Maw. I can feel it leeching my essence. Be on your guard.',36734),(57690,1,0,0,0,0,0,0,0,'I recognize you. Azeroth has been very busy lately, and her champions have been very much at the forefront of events. We must talk as soon as time allows.',36734),(57691,1,0,0,0,0,0,0,0,'Well, you are quite resourceful. Give me twenty five of your kind and some proper gear and we could defeat the Master.',36734),(57693,1,0,0,0,0,0,0,0,'It is only a matter of time before the Master detects my presence. We must be swift and violent of action if we are to stop Sire Denathrius.',36734),(57694,1,0,0,0,0,0,0,0,'So few left, but we will make do.',36734),(57709,669,0,0,0,0,0,0,0,'<The Forgelite studies you for a moment, then nods.>\n\nWelcome. You are not what we expected, but we are glad to have you nonetheless.',36710),(57710,669,0,0,0,0,0,0,0,'I confess... I was hoping for a small spectacle to lift the spirits of the aspirants in my care.\n\nI was not expecting to have my own lifted, as well. Thank you for that.',36710),(57711,1,0,0,0,0,0,0,0,'Hello again! This one is glad to see you!',36710),(57712,1,0,0,0,0,0,0,0,'I will see that they are returned to their proper places for everyone to enjoy.\n\nI appreciate your help in retrieving them, and I hope they were informative.',36734),(57713,1,0,0,0,0,0,0,0,'I hope you like it. It is far from my finest work, but it will serve you well while you are here.',36710),(57714,669,0,0,0,0,0,0,0,'This is always a painful lesson. We do not think less of you for it.',36710),(57716,669,0,0,0,0,0,0,0,'Thank you for bringing him to me, $n. He is in a worse state than any of us might have guessed.',36710),(57717,669,0,0,0,0,0,0,0,'<Eridia grips her hammer with pale knuckles.>\n\nHow... how are they so numerous?',36710),(57719,669,0,0,0,0,0,0,0,'These words... this voice...\n\nHow do I know this voice?',36710),(57724,1,0,0,0,0,0,0,0,'Now that we have cleared out the Master\'s forces, let us continue the search for Prince Renathal!',36734),(57727,1,0,0,0,0,0,0,0,'Thank you for your quick arrival, $n.',43206),(57729,1,0,0,0,0,0,0,0,'Let us finish what we started.',43206),(57771,1,0,0,0,0,0,0,0,'Stone to rubble. \n\nGreat work.',43206),(57772,1,0,0,0,0,0,0,0,'More hands for the rebellion. They can taste the truth.',43206),(57778,0,0,0,0,0,0,0,0,'We are pleased to see your return.',37176),(57787,0,0,0,0,0,0,0,0,'Featherlight says you\'ve kept up your end of our deal. That\'s great to hear!\n\nI have some news to share about getting you an audience with the Queen.',36734),(57816,1,273,0,0,0,200,0,0,'You\'re new, aren\'t you? Not a fae, not a soul, nor are you bound for a wildseed.\n\nAnd the droman sent you here to help me? Well, this just got very interesting.',36734),(57865,1,0,0,0,0,0,0,0,'Good! I am glad you found them alive. Of course, we will be unable to put them to work until the threat is dealt with and they are able to continue their crafts in peace. I\'m sure Sorcha will understand.',40593),(57866,1,0,0,0,0,0,0,0,'Good. It is the way of nature for the stronger to prevail.',40443),(57867,1,0,0,0,0,0,0,0,'Cursed tools? And you brought them back? Un-cursed!? I must say, I was not entirely expecting you to be quite so successful.',40443),(57868,1,0,0,0,0,0,0,0,'Oh, you found it! How lucky, do you see?',40443),(57869,1,0,0,0,0,0,0,0,'Much power courses through. We need only the smallest dustings. Your labors please me.',40443),(57870,1,0,0,0,0,0,0,0,'Very interesting. This will be quite useful.',40443),(57871,1,0,0,0,0,0,0,0,'Ah, the hero of the hour returns! Thank you for liberating my supplies. Our grove desperately needs them in these trying times.',40443),(57876,1,0,0,0,0,0,0,0,'We have sensed something horrific has happened. Quickly, tell me everything.',36734),(57877,1,0,0,0,0,0,0,0,'You have done well. See that you continue to do so.',36734),(57878,1,0,0,0,0,0,0,0,'All is as expected. Trust always in the Arbiter\'s plan.',40120),(57880,1,0,0,0,1500,0,0,0,'<Bogdan reads the words quickly, his eyes welling with tears as a smile spreads across his face.>\n\nThe Duke lives? What splendid news!',43206),(57881,1,0,0,0,0,0,0,0,'Ah, this is it! We should have no trouble accessing the manor now.',43206),(57882,1,0,0,0,0,0,0,0,'Don\'t worry about Florin. He\'ll come around.',43206),(57884,6,0,0,0,0,0,0,0,'Why would our lady choose such a lout as her paramour? Regardless, Thornhill Manor is ours once again.',43206),(57885,1,0,0,0,0,0,0,0,'How nice it is to finally come face to face with the revered Maw Walker.',43206),(57886,6,0,0,0,0,0,0,0,'So, we have a deal then?',43206),(57887,1,1,0,0,0,4000,0,0,'<The Countess maintains a stoic expression as she carefully scans the missive, her grip tightening the longer she reads.>\n\nThis letter was penned by Andrei of House Iremoore. I\'d know that scrawl anywhere. And it would appear he\'s plotting to overthrow me.',43206),(57888,1,0,0,0,0,0,0,0,'No one will be able to turn down an invite to one of my infamous soirees.',43206),(57889,6,0,0,0,0,0,0,0,'You\'re quite thorough, aren\'t you? I can see the flames from here. While you were out I took the liberty of having some proper leg wear altered to fit you. I am sure I have you sized up properly.',43206),(57890,1,0,0,0,0,0,0,0,'<The Countess inspects the mushrooms with a wry smile.>\n\nA rich color means the spores will be potent.',43206),(57891,6,0,0,0,0,0,0,0,'Have you identified the traitorous house?',43206),(57892,1,0,0,0,0,0,0,0,'Justice has been served, and an uprising quelled.',43206),(57893,1,0,0,0,0,0,0,0,'The Countess gave it up without a fight? We might have an ally in her yet...',43206),(57908,669,0,0,0,0,0,0,0,'The Forgelite\'s gratitude goes deeper than you know.\n\nNow. You must turn your attention back to our purpose here.',36710),(57909,1,0,0,0,0,0,0,0,'To fight so many, in so short a time, is truly a feat of stamina.\n\nI am tired just looking at you.\n\n<Pelagos laughs.>',36710),(57912,1,0,0,0,0,0,0,0,'I expect much of you, mortal. Help lead our frontal assault on the construct forces!',36710),(57918,1,0,0,0,0,0,0,0,'It is worse than I feared.',36949),(57919,1,0,0,0,0,0,0,0,'That soul is now lost forever. Such wasted potential...\n\nThe Lord Chamberlain will answer for this offense.',38134),(57920,1,0,0,0,0,0,0,0,'Every lost soul must be tended to.',38134),(57921,1,0,0,0,0,0,0,0,'Good. You are ready for the ritual.',38134),(57922,1,0,0,0,0,0,0,0,'His just reward would be the Maw, but this will have to do.',38134),(57923,1,0,0,0,0,0,0,0,'Absolution does not come easy. Nor should it.',38134),(57924,1,6,0,0,0,0,0,0,'I sacrificed more than you realize to save this soul.\n\nI would do it again, because it is right. Do you understand yet?',38134),(57925,1,0,0,0,0,0,0,0,'Some very angry judges recently passed through here.\n\n<Archivist Fane grins.>\n\nTell me everything you did to antagonize them. Don\'t skip a single detail!',38134),(57926,1,0,0,0,0,0,0,0,'<Archivist Fane\'s eyes light up when you hand him the archives.>\n\nThis is a lot of potential leverage...',38134),(57927,1,0,0,0,0,0,0,0,'<Cryptkeeper Kassir inspects the pieces of Temel you brought him.>\n\nThey bashed you real good, didn\'t they, Temel? Nothing I cannot fix...',38134),(57928,1,0,0,0,0,0,0,0,'The atonement crypts are meant to be used as storage for souls who require additional... processing before their next ritual.\n\nThe Lord Chamberlain\'s idiots are using them like prison cells and treasure rooms. You are doing us all a favor by opening them whenever you find a key.',38134),(57929,1,0,0,0,0,0,0,0,'Decorous and deserved.\n\nI hope this will be the first of many corrupt inquisitors we fell together.',38134),(57931,669,669,0,0,0,300,0,0,'This unit seems to be malfunctioning. We will have to perform some repairs.',39229),(57932,1,1,0,0,0,300,0,0,'This is enough to repair Gatamatos, and then some!',39229),(57933,1,1,0,0,0,300,0,0,'He may appear to be returned to perfect shape, but he must be re-tested and trained.',39229),(57934,1,1,0,0,0,300,0,0,'Excellent. His combat routines are acceptable.',39229),(57935,1,1,0,0,0,300,0,0,'I would like to see a larion track that accurately!',39229),(57936,1,1,0,0,0,300,0,0,'Can be at peace, no wild larion to eat me. Hoo...',39229),(57937,1,1,0,0,0,300,0,0,'And with that, I believe that Gatamatos is once again functioning at standard.\n\nThank you for your aid.',39229),(57947,0,0,0,0,0,0,0,0,'What\'s this? What\'s this?\n\nThe Tall Tree has sent you to help us? Help us!',36734),(57948,0,0,0,0,0,0,0,0,'You found them! You found my friends! They have their forms!\n\nNow we have one last thing to do. One last thing!',36734),(57949,0,0,0,0,0,0,0,0,'Stolen! They stole the anima! They ran like crazy and...\n\nWait that\'s normal. They\'re always that bad. Stupid spriggans!',36734),(57950,0,0,0,0,0,0,0,0,'Gone! The bad spriggan is gone! Spirit Glen will be ours again.\n\nNow to leave. We have to leave.',36734),(57951,0,0,0,0,0,0,0,0,'From acorns grow forests, from souls comes vital anima. Small though they be, on them our fates depend.\n\nThe forest sighs in gratitude.',36734),(57964,1,0,0,0,0,0,0,0,'You can kill more of them if you want.',36949),(57976,1,0,0,0,0,0,0,0,'That should strike fear into their stolen hearts.',36710),(57977,669,0,0,0,0,0,0,0,'You have proven yourself adept at this task. You have my gratitude.',36710),(57979,0,0,0,0,0,0,0,0,'Your leadership is inspiring. These troops would follow you anywhere!',36710),(57982,0,0,0,0,0,0,0,0,'It seems these kyrian are more stalwart than I expected. Let us avenge their fallen kin.',36710),(57983,6,0,0,0,0,0,0,0,'Only four survivors... I know I should be grateful that there were any at all, but...\n\nWhat sort of monsters would do this to anyone, let alone to their own people?',36710),(57984,1,0,0,0,0,0,0,0,'It seems one of the house\'s barons is overseeing this operation... and he is unaware that we are free. \n\nWe have a chance to strike him down!',36710),(57985,1,0,0,0,0,0,0,0,'Slowing the production of new constructs should earn our soldiers some reprieve, however brief.',36710),(57986,6,0,0,0,0,0,0,0,'Thank you, $p. Though they are lost, at least their remains will not be defiled.',36710),(57987,1,0,0,0,0,0,0,0,'Complacency is every soldier\'s worst enemy. No one is safe in times of war, not even within the walls of their own fortress.',36710),(57993,1,0,0,0,0,0,0,0,'I sense something within this construct... something familiar...',36710),(57994,0,0,0,0,0,0,0,0,'We escaped!\n\nWe will recuperate here for now. At least until we find a way to return to Bastion.\n\nThank you for showing me what courage is, my friend.',36710),(58007,1,5,0,0,0,0,0,0,'Our foes will regret opposing us.',37176),(58011,5,0,0,0,0,0,0,0,'You found my venom sacs! What a helpful apprentice you are!',36710),(58016,21,0,0,0,0,0,0,0,'Such marvelous spores, my apprentice!',36710),(58027,5,0,0,0,0,0,0,0,'What a precious slime!',36710),(58031,6,0,0,0,0,0,0,0,'Oh--and what are these?',36710),(58036,5,0,0,0,0,0,0,0,'You and your slime are bonding!',36710),(58037,1,0,0,0,0,0,0,0,'My pride is generally wary of newcomers, but they seem to accept your presence.',39229),(58038,1,0,0,0,0,0,0,0,'The larions will be ecstatic to have more antlers to chew on!',39229),(58039,1,0,0,0,0,0,0,0,'Incredible! It seems Andira has taken a liking to you. Perhaps you would be interested in bonding with her further?',39229),(58040,669,0,0,0,0,0,0,0,'It is such a satisfying experience to see your larion take wing to help take down your prey.',39229),(58041,669,0,0,0,0,0,0,0,'Providing for the pride is an important step on your path to earning your loyalty here.',39229),(58042,1,0,0,0,0,0,0,0,'The feeling of soaring through the air, the gentle flap of your larion\'s wings...\n\nEven though I have my own wings, there\'s no feeling quite like it.',39229),(58045,21,0,0,0,0,0,0,0,'Our slimes will be safe, my dear apprentice!',36710),(58068,0,0,0,0,0,0,0,0,'We would be so lost without your help. Truly.',38556),(58086,1,0,0,0,0,0,0,0,'What has he done?',36734),(58088,5,0,0,0,0,0,0,0,'I know Scrapper Minoire sent you. She always enhances herself to win the fight.',38556),(58090,5,0,0,0,0,0,0,0,'Scrapper Minoire will have to forfeit her spot in the contest.',38556),(58092,1,0,0,0,0,0,0,0,'A large step in our journey to reclaim the honor of these halls... but not the last.\n\nI shall send word to the Accuser immediately.',38134),(58093,1,0,0,0,0,0,0,0,'I am already working to undo the Lord Chamberlain\'s mistakes.\n\nYes, you may assist me.',36753),(58095,273,0,0,0,0,0,0,0,'A spectacular show, Maw Walker.',36753),(58104,1,0,0,0,0,0,0,0,'Oh good! You\'re here! No time to rehearse, but that shouldn\'t be too much of a problem.',37474),(58122,6,0,0,0,0,0,0,0,'Are you the new one? I\'m supposed to welcome you.\n\n<Blackguard lets out an exasperated sigh.>',38134),(58127,1,0,0,0,0,0,0,0,'A strong Maw Walker like yourself should have no problem taking down an inquisitor.\n\nHappy hunting.',36949),(58128,1,0,0,0,0,0,0,0,'High Inquisitors are powerful enemies. Bring a friend or two if you plan on challenging one directly.\n\nHappy hunting.',36949),(58157,1,0,0,0,0,0,0,0,'Not bad! Not great, but not bad. Quickly now, we\'ll need to help set the stage for the next act!',37474),(58158,1,0,0,0,0,0,0,0,'I can honestly say I have never seen a performance quite like this.\n\nNow... On to our grand finale! A battle for your world that is certain to make the court sit up and take notice!',37474),(58159,1,0,0,0,0,0,0,0,'A fair enough performance! \n\nI think everyone\'s more acquainted with your world and the role you\'ve played within it.\n\nNext time, the set design will be a bit more... prepared. But for now...\n\n<Moonberry nods at Ysera.>\n\nI think your friend wishes to have a word. Don\'t take too long. We still have to hold the final induction ceremony at the Heart of the Forest.',37474),(58160,1,0,0,0,0,0,0,0,'Your actions here will echo beyond the veil. Aid the forest, and all mortal worlds may yet be saved.',37474),(58161,1,0,0,0,0,0,0,0,'No, no... what is happening!?',38556),(58162,1,0,0,0,0,0,0,0,'These masks must provide some clue to what\'s causing the possessions.',38556),(58163,1,0,0,0,0,0,0,0,'<Partik quickly reads over the last few pages. His face turns pale.>',38556),(58164,1,0,0,0,0,0,0,0,'So few.... But each one is one more friend we can bring to bear against this madness!',38556),(58174,669,0,0,0,0,0,0,0,'<Kleia smiles warmly at you.>\n\nDoes this mean you intend to stay?',36710),(58211,1,0,0,0,0,0,0,0,'You love to see it!',37142),(58260,1,0,0,0,0,0,0,0,'Now to put these to a useful purpose.',36949),(58264,1,0,0,0,0,0,0,0,'You saved my friends!$b$b<Primrose gives you a small grin.>$b$bWe... we make a pretty good team, huh?',36753),(58265,1,0,0,0,0,0,0,0,'Grim work, but necessary. May they be reborn into useful vassals of Ardenweald once more.',36753),(58266,1,0,0,0,0,0,0,0,'We did it! All the altars are destroyed!',36753),(58267,1,0,0,0,0,0,0,0,'I see. This is terrible news.',36753),(58268,0,0,0,0,0,0,0,0,'With that ridge clear, we\'ll be safe to advance.',36710),(58272,1,0,0,0,0,0,0,0,'Ugh, vile things. Give them to me and I will see them properly disposed of.\n\nHere, for your troubles. Perhaps this reward will help wipe the filth of these documents from your fingertips.',36949),(58325,1,0,0,0,0,0,0,0,'That wasn\'t the first assassin I\'ve had to deal with so far. And it won\'t be the last.\n\nThe Curator must have sent you. Someone has turned our allies at Archivam against us... \n\nI have the mirror shard she entrusted to me. We must move quickly, friend.',43206),(58326,1,0,0,0,0,0,0,0,'Thank you. Do me a favor and don\'t tell the Curator? She won\'t be pleased with the state of things.',43206),(58337,1,0,0,0,0,0,0,0,'Thank you, $n. The souls are filled with vanity, rage, and sadness.\n\nSome more confinement will help them confront their past.',43206),(58351,1,0,0,0,0,0,0,0,'If they cannot properly evade detection, then they do not deserve to survive.',36710),(58372,1,0,0,0,0,0,0,0,'Thank you for bringing him here safely, $n. I am glad he is alive.\n\nWith his mirror shard in hand, we now have the unfortunate task of obtaining Mateo\'s mirror shard.\n\nI cannot believe he betrayed us. Many venthyr have reverted to their sinful ways it seems...',43206),(58376,0,0,0,0,0,0,0,0,'This ingredient can help construct a very powerful abomination. You should save it incase we find a use for it.',36949),(58382,1,0,0,0,0,0,0,0,'It shall not be easy to redeem Kael\'thas Sunstrider, and the outcome is far from guaranteed.\n\nBut we must attempt it nonetheless.',43206),(58383,1,0,0,0,0,0,0,0,'To be clear: We did not absolve Kael\'thas Sunstrider of any of these sins.\n\nHe might never be absolved of them. It must ultimately be his choice to change.\n\nBut we did stabilize his soul, which means he will at least have the opportunity to make that choice.',43206),(58384,1,0,0,0,0,0,0,0,'I must admit, I did not expect the dredgers to be quite so eager to fight for their own freedom.\n\nThe Prince inspires all of us, I suppose.',43206),(58385,1,0,0,0,0,0,0,0,'Kael\'thas Sunstrider may be ready for the ritual of absolution now.',43206),(58386,1,0,0,0,0,0,0,0,'I do not expect Kael\'thas to agree or even understand the value of mercy immediately.\n\nAbsolution is a long, slow process. This was only the first step.',43206),(58387,1,0,0,0,0,0,0,0,'I cannot comfortably call this a success, but it is likely the best outcome we could have hoped for. Carrying one\'s sins is no small feat, yet it can be liberating.\n\nTake this chain, if you wish, to display your commitment to owning your own sins. Kael\'thas needs it no longer.',43206),(58388,1,0,0,0,0,0,0,0,'Did any of the Blackbale venthyr show signs of regret?\n\nWe had hoped to recruit some to our cause eventually.',43206),(58389,1,0,0,0,0,0,0,0,'The Blackbale venthyr are wielding the weapons of the Maldraxxi army?\n\nThat would mean...',43206),(58391,1,0,0,0,0,0,0,0,'A lich? So close?\n\nCan you feel its presence? I once could...',43206),(58392,1,0,0,0,0,0,0,0,'Traitors and cowards. I have time for neither!',43206),(58393,1,0,0,0,0,0,0,0,'The bigger they are... the bigger the explosion at the end. Ha!',43206),(58394,1,0,0,0,0,0,0,0,'It was unlikely that she\'d tell us anything useful, but I had to try.',43206),(58395,1,0,0,0,0,0,0,0,'Maldraxxus is sworn to defend Revendreth from outside invaders, not siphon off our anima.\n\nAccept this gift for your role in bringing this conspiracy to light, $p.\n\nWe will need time to calculate our next move, but I am certain that you will be a key part of it.',43206),(58406,1,0,0,0,0,0,0,0,'This mirror is my greatest achievement. It links directly to the necropolis that floats above the bone fields of Maldraxxus.',43206),(58407,1,0,0,0,0,0,0,0,'Revendreth can now begin the return to its true purpose. May we walk into brighter futures together.\n\n<Prince Renathal smiles.>\n\nI could not help but notice that Vrednic, my loyal gargon, has taken an affinity to you, as I have.\n\nIf you would have him, I am certain he would enjoy accompanying you. Together, you shall instill fear into our enemies as he bears you into our next battle.',43206),(58421,1,0,0,0,0,0,0,0,'<Nourman carefully inspects the fangs.>\n\nChecks out. Strange that you got so many. \n\nSay, you don\'t look like a venthyr. \n\n<Nourman shrugs.>\n\nDon\'t matter to me. You got the fangs, you go inside. Them\'s the rules.',43206),(58424,1,0,0,0,0,0,0,0,'Yes! The rest of those rats will think twice about working with Denathrius.',43206),(58426,1,0,0,0,0,0,0,0,'I\'m pleased you came. Let\'s begin.',43206),(58428,1,0,0,0,0,0,0,0,'Excellent. Now we can enter the mirror safely.',43206),(58431,0,0,0,0,0,0,0,0,'We shall all share in this fabulous brew you have created!',38556),(58432,0,0,0,0,0,0,0,0,'These are valuable resources. Thank you, Maw Walker.',36949),(58433,1,0,0,0,0,0,0,0,'Well done, mortal. Stoneborn require anima to exist. Without it, they return to their stone form. This supply hurt them more than destroying thirty of their rebels.',36734),(58440,1,0,0,0,0,0,0,0,'You found the medallion! I wish you had found it under better circumstances. I do miss celebrating.\n\nBut I should reward you. Yes, a reward! You must take these. May they serve you well!',43206),(58443,1,0,0,0,0,0,0,0,'We\'re ready to begin our next lesson.',43206),(58444,1,0,0,0,0,0,0,0,'Excellent work, $n.\n\nWith the Curator\'s medallion in hand, we are one step closer to victory.',43206),(58445,1,0,0,0,0,0,0,0,'Thiernax suggests a bold plan. Locating the other former Night Warriors will not prove easy.',37474),(58446,1,0,0,0,0,0,0,0,'Ah, yes. I know of whom you speak.',37474),(58447,1,0,0,0,0,0,0,0,'This problem just got a lot larger. We need a new plan.',39335),(58449,1,0,0,0,0,0,0,0,'<Reldorn hefts the sacs, which bulge uncomfortably.>$b$bSo many? Just how big is this thing you two are hunting, anyway?',39335),(58450,1,0,0,0,0,0,0,0,'I am amazed that this contains so much concentrated anima. You will surely lure a devourer to you with this!',39335),(58451,1,0,0,0,0,0,0,0,'The hunt is over. We have prevailed.',39335),(58452,1,0,0,0,0,0,0,0,'Even in the afterlife, the legend of Huln Highmountain continues to grow.\n\nYou have done well to secure his aid, $n. Now let our search begin.',39335),(58472,0,0,0,0,0,0,0,0,'Let this prove our sense of honor.',36949),(58473,0,0,0,0,0,0,0,0,'I never thought I would return to Tirna Noch. The place of so many memories. So many regrets...\n\nBut now is not the time for sentimentality. Now is the time for action.',36734),(58480,0,0,0,0,0,0,0,0,'The Drust have stolen more anima than I expected. To think that they have deprived us of this much in the midst of a drought...\n\nWe must take back whatever we can. Not only for the sake of the wildseed, but to also thwart whatever the Drust intend to do.',36734),(58483,0,0,0,0,0,0,0,0,'Thank you.\n\nI know these are just objects, but they mean so much. Sometimes just holding a piece of one\'s past can be a comfort.\n\nIt means not everything is lost.',36734),(58484,0,0,0,0,0,0,0,0,'This anima will help Dreamweaver complete his ritual... and perhaps save spirits who otherwise would have been lost.\n\nGood work.',36734),(58486,0,0,0,0,0,0,0,0,'We made it to the heart. Well done.\n\nIf that is what all the Drust are truly like, then Ardenweald is in a dire situation, indeed.',36734),(58488,0,0,0,0,0,0,0,0,'Now that we have the heart, we need to find a way out of this place.\n\nAnd I hear the distinct sound of approaching enemies...',36734),(58504,0,0,0,0,0,0,0,0,'The pleasure is mine.',36949),(58515,378,11,0,0,0,500,0,0,'This will be very helpful. It\'s a shame so many people aren\'t willing to share their knowledge. Hoarding it is simply foolish.',37176),(58518,1,0,0,0,0,0,0,0,'A lich?! The Tithelord is working with a lich from Maldraxxus?!\n\nHow? To what ends?\n\n<The Accuser composes herself.>\n\nDo you appreciate how troubling this is, $p?\n\nThis has never happened. This is not supposed to happen.\n\nPrince Renathal will know what to do.',43206),(58523,0,0,0,0,0,0,0,0,'We have arrived. Let us not dally.',36949),(58524,0,0,0,0,0,0,0,0,'You found and took their anima right from the heart of the grove? Impressive.\n\nDreamweaver will be most pleased. But I expect that we will soon encounter some unhappy visitors.\n\nWe must move quickly to aid the spirit in this wildseed... before we are overrun.',36734),(58525,378,11,0,0,0,500,0,0,'You found them! What wonderful insight into the minds of the venthyr.',37176),(58530,1,0,0,0,0,0,0,0,'It\'s been quite a while since I\'ve seen these plains. \n\nI am surprised the illusion lasted as long as it did. It was concealed here many years ago for operations in the Master\'s name.\n\nNo matter, let us make haste. We are not here on a simple observation mission.',43206),(58555,1,0,0,0,0,0,0,0,'Just let me do the talking. One wrong move and they will surely revoke this trust.\n\nNow is not the time for more bloodshed between realms.',43206),(58575,0,0,0,0,0,0,0,0,'These weapons will be put to good use. Hopefully, we won\'t have to collect some of them again.',38556),(58584,1,0,0,0,0,0,0,0,'The job is done. \n\nThis should allow the anima to return. \n\nYour dedication to our cause is great. I cannot think of one more fitting to wear this cloak.',43206),(58585,1,0,0,0,0,0,0,0,'My tools. At least Famos took care of them.',43206),(58586,1,0,0,0,0,0,0,0,'Metal will do. Good work.',43206),(58589,0,0,0,0,0,0,0,0,'You\'re a natural at this. Now we can bring the spirit\'s nightmares into the open and deal with them directly.\n\nIf we succeed, she will be so much more at peace.',36734),(58590,0,0,0,0,0,0,0,0,'We all start somewhere. Sometimes in unexpected places. Me, I just popped out of the ground like a flower.',36734),(58591,0,0,0,0,0,0,0,0,'This is just the beginning of their attack. But it is still a heavy blow dealt to them. Thank you.',36734),(58592,0,0,0,0,0,0,0,0,'Those Drust really are cruel to us fae! Those spirit tenders were just trying to do their job...\n\nThank you for helping them.',36734),(58593,0,0,0,0,0,0,0,0,'What a terrible end for such a majestic spirit... \n\nBut that was why she connected with you! Because you are of the same world! Azeroth!\n\nNow, I can finally feel her nightmares wane. At last, she knows some peace.\n\nThank you, my friend.',36734),(58599,0,0,0,0,0,0,0,0,'Well done.',36949),(58600,1,0,0,0,0,0,0,0,'Perfectly crafted. Just what we need.',43206),(58608,0,0,0,0,0,0,0,0,'The Banished One... The Pauldrons of Imperium...\n\nThis lich, Kel\'Thuzad, meddles with powerful forces.',36949),(58609,1,66,0,0,0,0,0,0,'Welcome back to the fight, $n.',37176),(58610,0,0,0,0,0,0,0,0,'<Qadarin watches Thiernax race off. He sighs before turning to you.>\n\nMy apologies. Thiernax may have seemed curt, but there is a reason for his reluctance to speak of the Night Warrior.\n\nIf you have a moment to help me out in the garden, I can elaborate. Then I will see what can be done to convince Thiernax to help your mother.',37474),(58616,1,0,0,0,0,0,0,0,'This is going to take a bit of work.',36710),(58617,0,0,0,0,0,0,0,0,'That should ensure we stand ready for war.',36710),(58618,0,0,0,0,0,0,0,0,'Good! I knew that beast would prove no challenge for you.',36710),(58619,1,1,0,0,0,0,0,0,'Mortal, are you ready to help me save these valuable writings?',36753),(58620,0,0,0,0,0,0,0,0,'You have done it! The door is unlocked!',36753),(58621,1,0,0,0,0,0,0,0,'Now that those guardians are dispatched, we can focus on unlocking the door.',36753),(58622,1,0,0,0,0,0,0,0,'Fine work so far.\n\nAccess to the secret archives is almost ours!',36753),(58623,1,0,0,0,0,0,0,0,'So much valuable knowledge saved, and it would not have happened without your help.',36753),(58624,0,0,0,0,0,0,0,0,'The battle has only just begun.',36949),(58630,1,0,0,0,0,0,0,0,'Perfection.',43206),(58647,0,0,0,0,0,0,0,0,'Thank you, $n. This task is much easier with help.\n\n<Qadarin sighs.>\n\nI hope you do not think too poorly of Thiernax. His history with the Night Warrior ritual is rife with misplaced guilt and remorse, but I am certain I can get him to see sense and offer his aid.',37474),(58654,1,0,0,0,0,0,0,0,'Oh, the peasants have asked for help have they? \n\nThose who are loyal would know that sacrifices are essential to the survival of Revendreth. Yes, these are dark times with anima and new souls both being in short supply. \n\nBut we must all do our part, no matter how painful.',36734),(58656,1,0,0,0,0,0,0,0,'You\'re alive. The crown started to feed off your soul.\n\nLooks like there is still work to do. Mikanikos says the Sire\'s influence remains present in the crown. \n\nHe says he has a plan.',43206),(58665,1,0,0,0,0,0,0,0,'Do not let Emeni\'s sour disposition deter you. Your aid is greatly appreciated Maw Walker!',37176),(58668,1,0,0,0,0,0,0,0,'I never imagined myself returning to this place.',37176),(58669,0,0,0,0,0,0,0,0,'Hopefully they\'ll get the message and go back from whence they came!',37474),(58670,1,0,0,0,0,0,0,0,'I feel like we\'ve made our point, $n.',37176),(58671,1,0,0,0,0,0,0,0,'We make a good team, $n.',37176),(58677,1,0,0,0,0,0,0,0,'My cold blood warms to you. You may be a suitable ally.',37176),(58680,1,0,0,0,0,0,0,0,'You should consider a constructed body, perhaps I can design you one someday.',37176),(58686,1,0,0,0,0,0,0,0,'We\'re almost done! Just one more step to complete the construction!',37176),(58704,0,0,0,0,0,0,0,0,'I should have never left! He\'s told me time and again that I should face my...\n\nNever mind. I can deal with that later.\n\nThe situation would have been much more dire if the two of you were not here.',37474),(58706,1,0,0,0,0,0,0,0,'Excellent. This confirms my suspicions.',39335),(58714,0,0,0,0,0,0,0,0,'These Drust are bold to send spies into my grove! Very bold... and very foolish.',36734),(58719,0,0,0,0,0,0,0,0,'The Wild Hunt rides to our aid... but not from the west?\n\nThat is where Hunt-Captain Korayn was tracking a dangerous foe. She and her hunting party must have been waylaid.',36734),(58720,0,0,0,0,0,0,0,0,'These Drust thought to send a force to strike us from behind. \n\n<Korayn smirks.>\n\nYour call brought my fellow huntsmen and huntresses to reinforce us. Our foes were the ones caught by surprise.',36734),(58721,0,0,0,0,0,0,0,0,'<The Winter Queen turns her gaze upon you.>\n\nHow curious to see someone like you in my forest.',36734),(58723,0,0,0,0,0,0,0,0,'The Banished One stirs and Ardenweald\'s power withers in drought.',36734),(58724,0,0,0,0,0,0,0,0,'What has transpired in Ardenweald? Tell me everything.',36734),(58726,1,0,0,0,0,0,0,0,'You work quickly, don\'t you? I could use more assistants like you.',36710),(58727,1,0,0,0,0,0,0,0,'This spot will do great for us. We can build new constructs, and a home for ourselves.',37176),(58750,1,1,0,0,0,0,0,0,'These are some good tauraluses. Thanks for the help, mortal!',36753),(58751,6,0,0,0,0,0,0,0,'Be thankful I am the one you found here.\n\nOthers in Maldraxxus may not have seen the potential in your strength.',36710),(58771,1,0,0,0,0,0,0,0,'You found it! And other interesting tomes as well. They will be properly catalogued when we are done.',36710),(58773,0,0,0,0,0,0,0,0,'The Drust locked me in this cage and dragged Kivarr away! If you release me, I can show you where they went!',37474),(58785,1,1,0,0,0,0,0,0,'I am pleased with your work!',36753),(58794,1,1,0,0,0,0,0,0,'You\'ve done fine work! Just don\'t tell Caleesy about it.',36753),(58799,1,0,0,0,0,0,0,0,'Excellent. Their anima will be put to better use.',36710),(58800,1,0,0,0,0,0,0,0,'I love the hum of anima. It has been a long time since I have heard it in such abundance.',36710),(58820,574,0,0,0,0,0,0,0,'I can feel their power. Perhaps they will give us the advantage we need.',37176),(58821,1,0,0,0,0,0,0,0,'A simple task for such a storied hero.',36710),(58833,378,11,0,0,0,500,0,0,'We were brought together by chance, but now we fight as one.\n\nOur victory today will be one for all Maldraxxi.',37176),(58842,1,0,0,0,0,0,0,0,'We must retrieve those mirror shards before Denathrius\'s lackeys do. \n\nIt is the only way to access the crypt I concealed my medallion within.',43206),(58843,1,0,0,0,0,0,0,0,'I am very pleased to meet you. The Vault has not received visitors in some time.',36710),(58869,0,0,0,0,0,0,0,0,'We have won the battle...\n\n...But I fear we may have lost Ysera.',36734),(58871,1,0,0,0,0,0,0,0,'I bet those spriggan thought this would be pretty funny. Well, we\'re not laughing!',37474),(58900,0,0,0,0,0,0,0,0,'You have traveled far for this moment.',38556),(58903,0,0,0,0,0,0,0,0,'<Choose your destiny.>',40443),(58916,1,0,0,0,0,0,0,0,'This soul is nearly ready. \n\nWe have an opportunity to finish preparing this one and take care of a problem in the process.',36734),(58931,1,0,0,0,0,0,0,0,'Good. Temel will know how to exploit this sinstone.',36734),(58932,1,0,0,0,0,0,0,0,'<Echelon eyes Temel suspiciously.>\n\nI never liked this runt.',36734),(58936,1,0,0,0,0,0,0,0,'The balance is returning. Please accept this payment on behalf of myself and the other keepers of this place.',38556),(58941,1,0,0,0,0,0,0,0,'Now that Duskterror is captured, we have a little more control over these grounds.',36734),(58947,0,0,0,0,0,0,0,0,'You\'ve proven yourself worthy! I\'ll see if we can get you into a fight soon!',38556),(58976,1,0,0,0,0,0,0,0,'<Mikanikos gestures irritably toward the Forsworn behind him.>\n\nAre you here to help fix THIS?',36710),(58977,669,0,0,0,0,0,0,0,'We did it. With any luck, her memories are within our grasp.',36710),(58978,0,0,0,0,0,0,0,0,'<Mikanikos fumes silently.>',36710),(58979,1,0,0,0,0,0,0,0,'I hope you will forgive my behavior. I was not feeling quite like myself.',36710),(58980,1,0,0,0,0,0,0,0,'Your search was fruitful. I am delighted to see you remain intact.',36710),(58992,0,0,0,0,0,0,0,0,'Well, if this isn\'t the best batch of marrow I\'ve ever seen! \n\nMama is going to cook you a feast today!',37176),(58996,1,0,0,0,0,0,0,0,'So they were defeated? And yet, you still stand.\n\nShame.',38556),(59002,0,0,0,0,0,0,0,0,'My pack and I are too weak to oppose the dark forces on this island.\n\nWe will use the last of our strength to grant you our power.\n\nUse it to rid the island of the ogres\' necromancy.\n\nFree the countless souls they have trapped here.',45745),(59004,1,0,0,0,0,0,0,0,'Victory will be ours, Maw Walker!',42010),(59008,0,0,0,0,0,0,0,0,'Capturing souls is a far more brazen act than the typical spriggan prank. I wonder what has changed...',37474),(59009,274,0,0,0,0,0,0,0,'It is good to have allies. Even ones so stubborn.',36710),(59011,0,0,0,0,0,0,0,0,'We are struggling to hold the line. We need to act fast.',36710),(59014,1,0,0,0,0,0,0,0,'Let us begin, shall we?',36734),(59020,378,11,0,0,0,500,0,0,'Kel\'Thuzad escaped into the Banished One\'s hands, but at least his evil has been driven from Maldraxxus.\n\nWell fought, $p. Now we focus on rebuilding our forces and restoring order to our realm.',37176),(59021,1,0,0,0,0,0,0,0,'The ward on the Accuser\'s sinstone is weakened by the inquisitor\'s death.\n\nBut we must kill both inquisitors before the ward will fully fall, and we can access the Accuser\'s sinstone.',36734),(59023,1,0,0,0,0,0,0,0,'Lord Chamberlain confirmed the kill. We should hurry.',36734),(59025,1,0,0,0,0,0,0,0,'Cursed lich--may his soul never be reborn.',36710),(59042,1,5,0,0,300,0,0,0,'You\'ve done it, the construct is completed. The Slaughter Daughter lives again!',37176),(59063,0,0,0,0,0,0,0,0,'I knew Dreyden would have the scroll we need. We don\'t have time to waste!',37474),(59068,1,0,0,0,0,0,0,0,'You have no idea how tempted I am to open this and read it. Let\'s hurry up and create this counter-curse!',37474),(59069,1,0,0,0,0,0,0,0,'This figurine... I have not seen it since...\n\nI gave this to her when we first became Aspects. Our duties would draw us apart for the first time in our lives. To know that she has kept it all this time...\n\n<Ysera wipes her eyes.>\n\nWe will put it to good use.',37474),(59070,1,0,0,0,0,0,0,0,'HA! That will teach those spriggans! You mess with the mistrunner, you get the magical horn!\n\nNow we have the anima we need! And, conveniently, it\'s already attuned to the bad attitude of the one who cast the curse.',37474),(59071,0,0,0,0,0,0,0,0,'Were it not for your aid, Qadarin\'s soul would have been lost forever.\n\nI... I can do no less than offer my aid in return.',37474),(59126,1,5,0,0,0,0,0,0,'Atticus will set a box aside each week with spare supplies in case you need any of them.',36949),(59130,1,0,0,0,0,0,0,0,'My apprentice! I have been searching everywhere for you!',36710),(59147,669,0,0,0,0,0,0,0,'Some stains must be scoured away.',36710),(59171,574,0,0,0,0,0,0,0,'Yes, these will do nicely.',36710),(59172,1,0,0,0,0,0,0,0,'Draka may be content to forget our master, but I will not rest until he is avenged.',36710),(59181,1,1,0,0,0,0,0,0,'I have seen bits and pieces of this dark realm in my dreams. Tyrande roams this place.\n\nWe must find her.',37474),(59185,1,0,0,0,0,0,0,0,'He will not escape this time.',36710),(59188,1,0,0,0,0,0,0,0,'Yes... They will be made to know our pain.',36710),(59189,1,1,0,0,0,0,0,0,'I cannot fault my mother\'s intent... but she will be consumed before she finds justice for our people.\n\nWe must find another way to bring her back.',37474),(59190,1,0,0,0,0,0,0,0,'Vengeance is nearly ours.',36710),(59196,1,0,0,0,0,0,0,0,'The Polemarch? He is the right hand of the Archon!\n\nShe truly believes us. We still have a chance!',36710),(59197,1,0,0,0,0,0,0,0,'Kalisthene has vouched for you by allowing usage of the beacon. For that reason, you have my attention.',36710),(59198,0,0,0,0,0,0,0,0,'The Archon\'s chambers are just above. I urge you to practice extreme deference while in her presence.',36710),(59199,1,0,0,0,0,0,0,0,'The Archon\'s grace is upon you, mortal.',36710),(59200,1,1,0,0,0,300,0,0,'It seems the Forsworn are in our very midst, even in the Spires.\n\nWe must send aid to the Temple of Courage posthaste.',36710),(59202,6,0,0,0,0,0,0,0,'I will have my soldiers honor Krexus as he deserves.',36710),(59203,1,0,0,0,0,0,0,0,'Yes, you are more valuable than I first surmised.',38556),(59206,1,0,0,0,0,0,0,0,'I am glad of your return, mortal.\n\nI pray you were successful in preventing the advent of war between Bastion and Maldraxxus.',36710),(59209,1,0,0,0,0,0,0,0,'Our numbers are bolstered. Our survival chance is only slightly less grim.',36734),(59210,273,0,0,0,0,0,0,0,'Well executed.',36710),(59223,21,0,0,0,0,0,0,0,'Come, my apprentice! Our efforts nearly bear fruit!',36710),(59231,6,0,0,0,0,0,0,0,'I see you\'ve made a new ally... of a sort. And another rune has been empowered.',36710),(59232,1,0,0,0,0,0,0,0,'I am nothing if not merciful and understanding.\n\nThe Accuser will be given every opportunity to repent her errors and learn from them.',36734),(59233,0,0,0,0,0,0,0,0,'Excellent work, $n. \n\nWith this crown, I can focus the magic of the Harvesters into an unstoppable force. Now we continue our mission to redeem Revendreth. As a token of my appreciation for all of your help, I open up our armory to you. Please pick your reward.',43206),(59242,1,0,0,0,0,0,0,0,'My heart aches for Tyrande. The might of the Night Warrior is empowering her to battle these monsters... but it will consume her if we do nothing.\n\nShandris and I will investigate a... promising whisper that I have heard. I shall call upon you when I know more.',37474),(59246,1,0,0,0,0,0,0,0,'I will trust you for now, $n.\n\nBut should you betray me, I will ensure you endure the same torments I do.',37474),(59256,1,0,0,0,0,0,0,0,'This medallion will serve us well. But we lack our leader to don it.\n\nWe must seek out more allies.',36734),(59258,1,0,0,0,0,0,0,0,'Now, let us speak of the hunt.',39335),(59265,1,0,0,0,0,0,0,0,'I see cowardice in these eyes. You have done well.',37176),(59293,5,0,0,0,0,0,0,0,'He\'s smelly again? We\'ll at least he\'s happy, even if we are not.',37176),(59319,1,0,0,0,0,0,0,0,'The mission will be a complete success, I have no doubt.',40443),(59323,1,0,0,0,0,0,0,0,'So long as the pact remains, so shall our power.',43206),(59325,1,0,0,0,0,0,0,0,'Together we are stronger.',43206),(59327,1,0,0,0,0,0,0,0,'I will sever your head from your body should you...\n\nWait...\n\nYou are still alive? That means you are... the Maw Walker?',36734),(59343,1,0,0,0,0,0,0,0,'My heart swells, knowing that our souls are bound for all eternity.',43206),(59426,1,0,0,0,0,0,0,0,'Whenever you need assistance, your steward will be available to provide many services.',36710),(59427,1,0,0,0,0,0,0,0,'Yes, this will do.',43206),(59430,1,0,0,0,0,0,0,0,'Working together will benefit both of us greatly!',38556),(59520,1,0,0,0,0,0,0,0,'Working together will benefit both of us greatly!',36753),(59555,1,0,0,0,0,0,0,0,'The enemy is licking their wounds! Our troops will hold the line for now, but we should be prepared for more assaults.',36753),(59556,1,0,0,0,0,0,0,0,'This is our war to win, Maw Walker. It is now yours, as well.',37176),(59596,1,0,0,0,0,0,0,0,'I\'m so pleased to see you again, my apprentice!',36734),(59597,1,0,0,0,0,0,0,0,'Our shared knowledge will benefit all of Maldraxxus.',37176),(59603,1,0,0,0,0,0,0,0,'And so, it is as if you had led the battle personally! Impressive work, if I do say so myself.',37474),(59609,1,0,0,0,0,0,0,0,'I hope you\'re settled--there\'s no rest for the weary in Maldraxxus.',37176),(59615,1,0,0,0,0,0,0,0,'I know this soul, she is strong and very loyal. We would be well aided by building this most unusual construct.',37176),(59616,6,0,0,0,0,0,0,0,'Your voice... you are not one of the Maldraxxi?',36710),(59621,1,0,0,0,0,0,0,0,'This should hopefully curtail their numbers. Thank you for your help.',40593),(59622,1,0,0,0,0,0,0,0,'The population will produce more tenders eventually. You have bought us valuable time.',40593),(59623,1,0,0,0,0,0,0,0,'Yeah, this is good gorm right here. I\'ll make you something special from it.',40593),(59625,0,0,0,0,0,0,0,0,'Your arrival is expected. We await results.',37176),(59644,0,0,0,0,0,0,0,0,'That should buy us some time and carve us a bit of a path. Now to take advantage of the situation.',36734),(59645,0,0,0,0,0,0,0,0,'Our will is done.',37176),(59648,0,0,0,0,0,0,0,0,'We have only just begun.',37176),(59650,1,0,0,0,0,0,0,0,'This will begin to set things right.',37176),(59653,0,0,0,0,0,0,0,0,'This is as close as I can take you. Make it count.',37176),(59656,1,0,0,0,0,0,0,0,'Ah, that is wonderful news. Thank you for your assistance.',40593),(59659,0,0,0,0,0,0,0,0,'Now we are ready.',37176),(59660,1,0,0,0,0,0,0,0,'This court isn\'t going to throw itself. Let\'s get to work!',38134),(59661,1,0,0,0,0,0,0,0,'That went surprisingly well, all things considered. You and I have a real knack for this party-planning stuff.\n\nWe\'re ready to prepare our first real Ember Court!',38134),(59676,1,0,0,0,0,0,0,0,'Ah, the Countess. Mistress of the court. Always assume she is never alone, and always capable of great treachery.\n\nMmm... treachery...',43206),(59678,66,0,0,0,0,0,0,0,'No longer can they sustain themselves. Good work.',37176),(59698,0,0,0,0,0,0,0,0,'For Courage!',37176),(59700,0,0,0,0,0,0,0,0,'May her memory fade from this place.',37176),(59701,1,0,0,0,0,0,0,0,'They may look like simple banners, but with the right words and a few appropriate spells, they turn this place into a temporary sanctuary.',43206),(59706,1,0,0,0,0,0,0,0,'Glad you got here before \'em patrols. I ain\'t got a permit to park here.',43206),(59707,1,0,0,0,0,0,0,0,'Ready to fall with grace?',43206),(59708,1,0,0,0,0,0,0,0,'This will not be an easy day.',43206),(59709,0,0,0,0,0,0,0,0,'May our paths cross again.',37176),(59710,6,1,0,0,0,0,0,0,'Well, looks like the master just left. What timing.',38556),(59711,1,1,0,0,0,0,0,0,'The Tithelord. I believe he is the two hundred and seventy fifth Caretaker to lord over the Village Ward. \n\nHe is as dangerously ambitious as every Harvester of Envy before him, and will help only if he believes he stands to gain more power.',43206),(59712,1,0,0,0,0,0,0,0,'Appreciate you helping my friend. Keep this up and I\'ll be in your debt.',38556),(59713,6,0,0,0,0,0,0,0,'This should be enough to knock him out for long enough to take my sinstone.',38556),(59714,1,0,0,0,0,0,0,0,'Ah, that\'s perfect. He will not be able to resist this.',38556),(59715,5,0,0,0,0,0,0,0,'Ah, the Maw Walker! I have heard so much about you.',38556),(59716,5,1,0,0,0,0,0,0,'Oh, well done! I had a moment there when you drank the poison that I feared for you. But you\'re a hearty sort.',38556),(59719,1,0,0,0,0,0,0,0,'Well, that could have gone better. I did not expect them to come around right away, but I had hoped at least one or two of them might.\n\nNow we must do it the hard way. We should leave before they send forces to re-capture this tower.',43206),(59720,1,0,0,0,0,0,0,0,'I remember when the first stoneborn moved with the breath of anima infused by the Stonewright. \n\nNever, ever, confuse her sympathy for her creations as a weakness. She holds the Medallion of Wrath for a reason.',43206),(59721,1,0,0,0,0,0,0,0,'You are just in time. My preparations are nearly complete.',39335),(59722,0,0,0,0,0,0,0,0,'It\'s like we were never gone.',37176),(59724,1,0,0,0,0,0,0,0,'Well, he\'s certainly chosen a scenic location for a fight.',38556),(59725,1,0,0,0,0,0,0,0,'Please tell me you are here to help with the spriggan problem!',37474),(59726,1,0,0,0,0,0,0,0,'I would have allowed an apology, but he chose treachery and has paid the price.',38556),(59731,0,0,0,0,0,0,0,0,'Ol\' Bwonsamdi knew ya gonna come see me. I got someting ya wanna hear...',37474),(59732,1,1,0,0,0,0,0,0,'While ya be here, why not help clean up some of da trash outside me Necropolis? For old time\'s sake, eh?\n\nDen we can be dealin\' wit Mueh\'zala.',39335),(59739,0,0,0,0,0,0,0,0,'Me got plans older dan you, $r. Slaying Zel\'han mean noting ta me... ya understand?\n\n<Mueh\'zala\'s gaze remains focused on the broken armor in front of him.>',39335),(59741,0,0,0,0,0,0,0,0,'Look at all dis mojo! Dis be just what me need ta make little Mueh\'zala talk.\n\nDon\'t ya be worryin\' about da other undead out dere. Ol\' Bwonsamdi got a plan for dem.',39335),(59742,1,1,0,0,0,0,0,0,'Ah good, ya got me all da livin\' souls I be needin\'.\n\nDon\'t ya be worryin\' about da ones who passed on. Ol\' Bwonsamdi not lettin\' dem go to da Maw.',39335),(59748,1,0,0,0,0,0,0,0,'Come. There is much to show you.',37176),(59749,0,0,0,0,0,0,0,0,'Dere be one loa o\' death, $n. And it be ol\' Bwonsamdi. \n\nYa best not forget dat.',39335),(59750,0,0,0,0,0,0,0,0,'Good work, you\'re getting some recognition. I hear people talking about how you killed all those bloodtusks!',38556),(59751,6,1,0,0,0,0,0,0,'Not the most ideal of arrivals, but at least we are still in one piece.\n\nI have not seen any sign of Tyrande. Either she landed elsewhere or continued on without us. We should keep an eye out.',39229),(59752,1,25,0,0,0,0,0,0,'We\'ve been in this place mere moments and already our forces are depleted. It will have to do.\n\nTake this horn. It can be used to call upon the remaining Ebon Blade forces to rally against your foes.',39229),(59753,1,0,0,0,0,0,0,0,'I am loath to leave some of our knights behind, but it is obvious we cannot stand against such foes. \n\nWe must make sure their sacrifices are not in vain.',39229),(59754,5,0,0,0,0,0,0,0,'Those images will keep our foes distracted for a time, but they will not give up their pursuit so easily.\n\nWe must make haste!',39229),(59755,1,0,0,0,0,0,0,0,'Rest here while you can, $n.\n\nI will tell you what I know.',39229),(59756,1,6,0,0,0,0,0,0,'I need time to recover after that battle. Thrall could use rest, too.\n\nWhile we rest, perhaps you and Mograine can seek answers.',39229),(59757,5,6,0,0,0,0,0,0,'Useless! These souls are far too fragmented to provide us with anything.\n\nWait... what is that?',39229),(59758,1,25,0,0,0,0,0,0,'Find enough mouths and one of them is bound to speak. \n\nLet\'s bring this thing back to the cave and find out what it knows.',39229),(59759,1,0,0,0,0,0,0,0,'I knew in my heart the Light wouldn\'t fail us.\n\nYour presence here is the proof.',39229),(59760,1,0,0,0,0,0,0,0,'I had almost forgotten the feeling of freedom.\n\nNow, let us take the fight to these fiends.',39229),(59761,1,0,0,0,0,0,0,0,'I knew I could trust you with this task. \n\nThough we face insurmountable odds, we must try to do what is right.',39229),(59762,5,0,0,0,0,0,0,0,'The Jailer has Baine!\n\nThis is worse than we feared...',39229),(59765,1,0,0,0,0,0,0,0,'We were fortunate to find the sorcerer who poisoned Baine\'s spirit.\n\nI will need your help breaking its link to the High Chieftain.',39229),(59766,1,0,0,0,0,0,0,0,'This lacks the balance and craftsmanship of a good Frostwolf axe, but it will have to do.\n\nLet\'s get moving.',39229),(59767,5,0,0,0,0,0,0,0,'We made it! \n\nIf we can activate this waystone, we just might be able to escape this place!',39229),(59770,0,0,0,0,0,0,0,0,'<The waystone appears to be waiting for something.\n\nYou reach out and touch its surface...>',39229),(59776,1,0,0,0,0,0,0,0,'I cannot say I enjoyed wielding the Helm of Domination. The magic it holds is... unsettling to the dead.\n\nI gladly return it to your care.',39229),(59781,0,0,0,0,0,0,0,0,'Too bad about the last few, but you\'re still here!',38556),(59800,0,0,0,0,0,0,0,0,'Nice work firing up the combatants. They\'ll remember you helped them... if they survive.',38556),(59805,0,0,0,0,0,0,0,0,'All me trainin\' as a shadow hunter been leadin\' ta dis moment. \n\nTrackin\' a spirit inside da Maw and savin\' dem from eternal torture...',39335),(59809,1,0,0,0,0,0,0,0,'Welcome to da Other Side!\n\nWhat ya tink, mon? Ya like what I done wit\' da place?',37474),(59811,0,0,0,0,0,0,0,0,'So Hakkar and Dambala be da ones gone missing? Hmm... we\'d better find out where dey went!',37474),(59812,0,0,0,0,0,0,0,0,'Da tracks lead into da grove up ahead. I got a feelin\' Hakkar and Dambala be somewhere nearby...',37474),(59813,0,0,0,0,0,0,0,0,'Ya did good! But dis be far from over...',37474),(59815,0,0,0,0,0,0,0,0,'It all be makin\' sense now. Mueh\'zala be draining anima outta da other wildseeds so he can be wakin\' Dambala and Hakkar before their time.\n\nDa Winter Queen gotta be told \'bout dis before it too late...',37474),(59817,1,0,0,0,0,0,0,0,'I am not eager to do any favors for Bwonsamdi, but Mueh\'zala\'s actions cannot be ignored.',37474),(59818,1,0,0,0,0,0,0,0,'You\'re just in time. The Wild Hunt is locked in battle with Mueh\'zala\'s forces.',37474),(59819,0,0,0,0,0,0,0,0,'The Wild Hunt can handle pushing the rest of them out of the forest. Well done, $n!',37474),(59821,0,0,0,0,0,0,0,0,'Welcome news, indeed. I will not soon forget Mueh\'zala\'s transgressions.',37474),(59822,0,0,0,0,0,0,0,0,'We ain\'t done wit\' dis place yet. Dere be loa trapped here!',39335),(59824,0,0,0,0,0,0,0,0,'Rezan be needin\' us!',39335),(59827,0,0,0,0,0,0,0,0,'Your performance has netted me a nice profit... Zo\'umlo bet poorly.',37176),(59828,0,0,0,0,0,0,0,0,'Your performance has netted me a nice profit... Zo\'umlo bet poorly.',37176),(59837,1,0,0,0,0,0,0,0,'Competing in the arena is but one way to contribute to this venture. There are many other tasks to perform, as well.',38556),(59846,1,0,0,0,0,0,0,0,'Ah. A pity none of these are mine. Still they may prove useful.',38556),(59856,0,0,0,0,0,0,0,0,'Me be feelin\' Rezan\'s essence inside of me... he be trustin\' me wit\' a great gift.\n\nNo matter what be comin\' next, me not gonna let him down.',37474),(59862,0,0,0,0,0,0,0,0,'Your presence warms the grove.\n\nNow we learn, and grow.',37988),(59866,0,0,0,0,0,0,0,0,'It fills me with joy to know that the spirits lost to the Maw are safe once more.\n\nNone can say what fate has in store for Vol\'jin. The path on which he has embarked has never before been walked by a mortal soul.\n\nYet whatever awaits him, know that your efforts are what made it possible.',39335),(59867,0,0,0,0,0,0,0,0,'Excellent work, Maw Walker. I shall dispatch Zo\'umlo to retrieve our stolen property.',36753),(59868,1,0,0,0,0,0,0,0,'You\'ve made some friends today.',38556),(59871,0,0,0,0,0,0,0,0,'Nature holds as many secrets as it does gifts.',38134),(59872,0,0,0,0,0,0,0,0,'Your skills take root, Maw Walker.',37988),(59873,0,0,0,0,0,0,0,0,'And so a god is reborn by the hand of a mortal.\n\nThey greeted you with gratitude, yes? And perhaps surprise, as well.',37988),(59874,1,0,0,0,0,0,0,0,'What news from Maldraxxus, $n?\n\n<Bolvar listens to your tale.>',36710),(59876,1,0,0,0,0,0,0,0,'This is far worse than we thought.\n\nCommander Gregor must be told of the true extent of the Scourge\'s resurgence.',36710),(59877,1,0,0,0,0,0,0,0,'You arrive just in time. Commander Gregor spoke highly of you.',36710),(59879,0,0,0,0,0,0,0,0,'You must be one of these outsiders I hear so much about.',38556),(59894,0,0,0,0,0,0,0,0,'An alliance is secured. Now we plan the attack.',37176),(59897,0,0,0,0,0,0,0,0,'<The area is quiet. There is no sign of your allies.>',36710),(59907,1,0,0,0,0,0,0,0,'Our enemy is relentless, but we will continue to drive them back.\n\nStand vigilant, $c.',39229),(59914,5,6,0,0,0,0,0,0,'Praise the Light! I... I\'d almost given up hope.\n\n<Jaina looks upon the Ebon Blade knights.> \n\nIs this... all that remains of your forces?',39229),(59915,1,0,0,0,0,0,0,0,'It seems your search was a success.\n\nEnough rest. There\'s much to be done.',39229),(59916,-1,0,0,0,0,0,0,0,'This bloodshed will not bring them back... but it may spare others from the same fate.',37176),(59917,1,1,0,0,0,0,0,0,'Nicely done. You\'ve bought us precious time.',36753),(59920,1,0,0,0,0,0,0,0,'I am deeply grateful for your help. Now I can practice my craft again!',36710),(59921,1,0,0,0,0,0,0,0,'Did this venture enlighten you?',37176),(59922,1,0,0,0,0,0,0,0,'So we have proven our honor... and gained a new ally.',37176),(59929,0,0,0,0,0,0,0,0,'Excellent work. Let\'s get the survivors back on their feet.',45114),(59930,0,0,0,0,0,0,0,0,'We\'re back on our feet. Now let\'s move. The lost expedition is somewhere on this island.',45114),(59931,0,0,0,0,0,0,0,0,'So... hungry...\n\nDey took... everyone else... I be... da last one...',45114),(59932,0,0,0,0,0,0,0,0,'<Won\'sa quickly eats the meat that you cooked.>\n\nLooks I not gonna be knockin\' on Bwonsamdi\'s door, after all.\n\nYa best hurry. Da quilboar took Shuja and da rest of da expedition!',45114),(59933,0,0,0,0,0,0,0,0,'You\'re ready to slaughter the quilboar! Let\'s speak to Won\'sa and see what she knows.',45114),(59935,0,0,0,0,0,0,0,0,'I have good news... and most unfortunate news.',45114),(59937,0,0,0,0,0,0,0,0,'Fine work. The lessons you learn from the inimitable Mithdran Dawntracker will last you a lifetime.\n\nNow, down to the business of our quilboar foes...',37474),(59938,4,11,0,0,0,0,0,0,'You sure got some guts! I respect that. I joined this expedition thinkin\' it\'d be a quick and easy way to make a little profit.\n\nBut now with all this necromancy and crazy ogres... maybe I can make a LOT of profit!',45114),(59939,66,0,0,0,0,0,0,0,'A fine job. The quilboar seem to be keeping their distance. Perhaps they learned their lesson.',45114),(59940,4,0,0,0,0,0,0,0,'All right, time to bend some rules and make a giant boar!',45114),(59941,397,0,0,0,0,0,0,0,'So the giant boar was a fool\'s errand, and you turned the device into a weapon instead?\n\nGood work. Let\'s see if you can pull this off.',45114),(59942,66,0,0,0,0,0,0,0,'Thank you, stranger. I failed the Horde... I was not strong enough to stop this threat on my own.',45114),(59943,2,0,0,0,0,0,0,0,'I have found the missing member of the expedition... but we have many problems to deal with first.',45114),(59944,4,11,0,0,0,0,0,0,'Thanks for the save! They must be desperate for sacrifices if they wanted to use someone who\'s already dead.\n\nIf anyone is going to drain my life essence to use in a forbidden ritual, it\'s going to be me!',45114),(59945,1,0,0,0,0,0,0,0,'The harpies seem to be retreating to their roost. That should give us time to stop the ogres.',45114),(59946,2,0,0,0,0,0,0,0,'The harpies grow weaker with their totems destroyed. Let us hope they realize that the Horde is a force to be reckoned with.',45114),(59947,0,0,0,0,0,0,0,0,'It is good to see you all back in one piece. You are testament to the Horde\'s strength of will!\n\nLet\'s hope Gloomburst is as powerful as he is unhinged.',45114),(59948,1,6,25,0,0,0,0,0,'A giant pit filled with necrotic energy and spiders.\n\nI used to hate spiders. Now that I\'m Forsaken, I don\'t think they\'re all that bad.\n\nThey will still definitely kill you, though.',45114),(59949,0,0,0,0,0,0,0,0,'Crenna Earth-Daughter will be vital to our cause. Her connection to nature will help us understand what the ogres have done to this island.\n\nGood work, recruit.',45114),(59950,0,0,0,0,0,0,0,0,'I hope you have what you need. \n\nThrog found this bag nearby and thought you might have use of it.',45114),(59951,4,1,0,0,0,0,0,0,'Good! I can sense the blessing of the spirits flowing through you.\n\nFocus, and you should find that you can take on a new form.',41488),(59952,1,0,0,0,0,0,0,0,'With a little work, this can become an effective trap.\n\nPart of what makes a real hunter is the resourcefulness to use what your environment provides.',37988),(59953,6,11,378,0,0,0,0,0,'I admit, I am rather ashamed I did not immediately recognize this beast.\n\nIt must be quite resilient if it was able to survive this long on its own!\n\nHere, let me teach you another trick. You\'ll want to have multiple pets to switch between if you\'re to be a hunter of any worth.',37988),(59959,1,0,0,0,0,0,0,0,'My, my. Today certainly has been full of surprises!\n\nNow, mortal, I\'m curious what has brought you back to the Maw.',36710),(59960,0,0,0,0,0,0,0,0,'<Darion is trapped within the cage. He appears unconscious.>',36710),(59962,0,0,0,0,0,0,0,0,'Keep up. We have little time.',36710),(59966,0,0,0,0,0,0,0,0,'My father... Alexandros Mograine. The Ashbringer.\n\nI... never expected to see him again.',36710),(59970,0,0,0,0,0,0,0,0,'Our bargain has been struck.\n\nCall upon me from the Void, and I will answer.\n\n<The voidwalker looks at the goblin\'s corpse.>\n\nLet us see if you are stronger than those who came before you.',45114),(59973,1,0,0,0,0,0,0,0,'I cannot thank you enough, $n.',36710),(59974,0,0,0,0,0,0,0,0,'I cannot allow this wound to fester any longer. I will burn it closed here and now!',36710),(59975,0,0,0,0,0,0,0,0,'Darkmaul Citadel looms ahead. \n\nHerbert\'s proposed plan is... unconventional.',37988),(59978,669,0,0,0,0,0,0,0,'There may just be a way that we can save Warlord Thunderwalker.',37988),(59979,1,0,0,0,0,0,0,0,'That should weaken the ogres long enough for us to put an end to their plotting.',37988),(59980,6,11,0,0,0,0,0,0,'Good work! You didn\'t happen to save any of those explosives, did you?\n\n...I didn\'t think so. Oh well! I have plenty of other ways to blow up my enemies.',37988),(59981,2,5,0,0,0,0,0,0,'Thank you for the aid, but saving me will not stop the ogres. \n\nThey already have enough life essence to complete the ritual!',37988),(59984,0,0,0,0,0,0,0,0,'Victory for the Horde! It is time we returned to Orgrimmar as heroes and conquerors.',37988),(59985,0,0,0,0,0,0,0,0,'It\'s good to be back in Orgrimmar. \n\nI must report to the warchief, but I know what you can do in the meantime...',37988),(59994,1,1,0,0,0,0,0,0,'This is it... the Volume of Victory! The single most important compendium of Maldraxxus military history ever assembled.\n\nIt must be mine! Uh, ours. I mean ours!',36753),(59999,1,0,0,0,0,0,0,0,'The forest sings in gratitude, Maw Walker. \n\nMy Queen is wise to place her faith in you.',38134),(60003,1,0,0,0,0,0,0,0,'We\'ll see to it they receive proper attention.',36710),(60005,669,0,0,0,0,0,0,0,'Not quite the army I hoped would come, but I welcome your blade by my side.',36710),(60006,669,0,0,0,0,0,0,0,'We have bought a staging ground, but much remains to be done.',36710),(60007,0,0,0,0,0,0,0,0,'That was fast! Well done, well done indeed!',36710),(60008,0,0,0,0,0,0,0,0,'You fight with the poise of a true kyrian, outsider.',36710),(60009,0,0,0,0,0,0,0,0,'You are a true ally, outsider. Thank you.',36710),(60013,669,0,0,0,0,0,0,0,'We must hurry. The Archon must know what transpired here.',36710),(60020,0,0,0,0,0,0,0,0,'Still walking on two legs? My hopes for you are rising.',36710),(60021,1,0,0,0,0,0,0,0,'Good, the crowd\'s on your side.\n\nNow there\'s just one last test.',36710),(60041,1,0,0,0,0,0,0,0,'We were successful, Chordy is whole again!',36753),(60042,1,0,0,0,0,0,0,0,'So many powerful souls, we must get to work immediately.',36753),(60043,0,0,0,0,0,0,0,0,'You have done a great service here.',37176),(60044,669,0,0,0,0,0,0,0,'This may not work... but it may also be our only chance at victory.',37176),(60048,1,0,0,0,0,0,0,0,'You have acquired all the resources we needed.',36753),(60049,1,0,0,0,0,0,0,0,'Well done. Emeni and her constructs will make for powerful allies.\n\nThey will, however, need your assistance to reach their full potential.',37176),(60050,669,0,0,0,0,0,0,0,'I am glad Kynthia found you so quickly.',37176),(60052,669,0,0,0,0,0,0,0,'The Resonator is working at full capacity and our foes are dispatched. Excellent.',36710),(60053,0,0,0,0,0,0,0,0,'Not fully charged, but close enough! May have to disable a few safety features...',36710),(60054,669,0,0,0,0,0,0,0,'Our only move now is forward, outsider.',36710),(60055,1,0,0,0,0,0,0,0,'Thanikos... is gone... isn\'t he.',36710),(60056,1,0,0,0,0,0,0,0,'I know why you have come. This kyrian has explained much.',36710),(60057,669,0,0,0,0,0,0,0,'Word has spread throughout Bastion of your actions at the Temple of Courage, $n. Xandria sent word that you were to be amply rewarded for your heroism.',40593),(60060,1,0,0,0,0,0,0,0,'Well done! The mirrors have been attuned and can be used at your leisure.',36949),(60061,30,30,0,0,0,0,0,0,'Thank you! We are so grateful for your help with slaying those cretins, and rescuing our people.',39427),(60067,669,0,0,0,0,0,0,0,'Our fallen finally know justice.',37176),(60098,0,0,0,0,0,0,0,0,'It is time.',37176),(60108,0,0,0,0,0,0,0,0,'Well done, $Ghuntsman:huntress;.\n\nYou have saved Ardenweald from the Drust, and in so doing, protected countless other realms from their darkness.',39335),(60110,1,0,0,0,0,0,0,0,'Now you can try to live up to my example.',37176),(60111,1,0,0,0,0,0,0,0,'Our shared knowledge will benefit all of Maldraxxus.',37176),(60112,0,0,0,0,0,0,0,0,'He ought to be here... but he isn\'t.',37176),(60113,0,0,0,0,0,0,0,0,'I knew you would not hesitate to answer the call, $n.\n\nI will be brief.',36710),(60116,1,1,-1,-1,0,2000,0,0,'We must find a way to rescue Anduin and the others. But in this moment, the safety of our citizens and our allies is our highest priority.\n\nAs such, I have reached out to those experienced in dealing with threats of this nature.',36710),(60117,1,0,0,0,0,0,0,0,'Ah, I was told to expect the arrival of a seasoned $c.\n\nLet\'s get to work.',36710),(60126,396,0,0,0,0,0,0,0,'Lok\'tar, $n.',46597),(60127,1,0,0,0,0,0,0,0,'<Cryptkeeper Kassir grins.>\n\nSo you finally listened to the Accuser, eh?\n\nBetter late than never.',38134),(60128,1,0,0,0,0,0,0,0,'Temel has told me quite the tale of your previous adventures together, Maw Walker.',38134),(60136,1,1,0,0,0,0,0,0,'Well, Maw Walker, what are you waiting for?',38134),(60139,1,0,0,0,0,0,0,0,'Two of Azeroth\'s architects of peace have been recovered.\n\nTwo remain captive.',36839),(60145,0,0,0,0,0,0,0,0,'Excellent. Now he is left without his key defense.',43206),(60146,1,0,0,0,0,0,0,0,'You have braved torments beyond most mortals\' understanding, $n.\n\nWell done indeed.',36949),(60147,1,0,0,0,0,0,0,0,'Well done! The mirrors have been attuned and can be used at your leisure.',36949),(60148,0,0,0,0,0,0,0,0,'Finally, the Purpose may be guiding us again.',41488),(60149,1,1,0,0,0,0,0,0,'We may find a shared cause in the Purpose. It has sent you to us.',41488),(60150,1,1,0,0,0,0,0,0,'$n! I am relieved you survived that realm of darkness.\n\nI am eager to hear the tale.',41488),(60151,0,0,0,0,0,0,0,0,'Your path and the Purpose are now entwining.',41488),(60152,1,0,0,0,0,0,0,0,'We hope you are comfortable here, $n.\n\nConsider these ancient facilities to be at your disposal.',41488),(60153,0,0,0,0,0,0,0,0,'It\'s a good thing you were there. The gorm have been very hungry lately, and I do not appreciate being nibbled on. Never been my thing!',37899),(60154,0,0,0,0,0,0,0,0,'Your path and that of the Purpose are becoming one.',42010),(60156,1,0,0,0,0,0,0,0,'Purpose be praised! Your path becomes clearer.',42010),(60158,0,0,0,0,0,0,0,0,'It seems our partnership has become rather permanent. Cartel Ve will not rest until we are both eliminated.\n\nI suppose now would be the time to share one of my most important rules with you.',37474),(60162,1,66,0,0,0,0,0,0,'I don\'t believe there is anything left to teach you, $n. \n\nNow you must go forth and find more beasts to tame and call your own.\n\nIf you ever need to store or retrieve your pets, speak with me or any other stable masters you encounter in your travels.',37988),(60169,1,0,0,0,0,0,0,0,'It appears we are making headway.',36710),(60175,0,0,0,0,0,0,0,0,'Mmmm, it smells just like how I remember it! Maybe a little stale, but you won\'t hear me complaining about a job well done!',37864),(60176,0,0,0,0,0,0,0,0,'I was not sure this task was possible. Very impressive work.',38556),(60177,0,0,0,0,0,0,0,0,'Well, isn\'t that interesting information you\'ve dug up.',38556),(60178,0,0,0,0,0,0,0,0,'Nice that it all worked out in the end. Thanks for the unintentional help.',38556),(60179,1,0,0,0,0,0,0,0,'Many strive for greatness in Maldraxxus. Few truly achieve infamy.\n\nLet us see if our names will one day be remembered.',36710),(60180,1,0,0,0,0,0,0,0,'I hope your experience was satisfactory.',36710),(60181,0,0,0,0,0,0,0,0,'A threat removed for the House of the Chosen, and new recruits that show potential.\n\nGood work.',36710),(60183,1,0,0,0,0,0,0,0,'An excellent display of the strength of Sinfall, $n. \n\nLet us continue, shall we?',43206),(60184,0,0,0,0,0,0,0,0,'You do not cease to impress.',36949),(60188,0,0,0,0,0,0,0,0,'That was real nice of you. Not too many people take care of us old folks around here.$b$bShe even gave you silk! How nice. Here, why don\'t you take it? I certainly don\'t need it.',37988),(60189,1,1,0,0,0,0,0,0,'Good. You are here.\n\nWe are now ready to end the Drust\'s invasion once and for all.',39335),(60190,5,1,6,0,0,0,0,0,'Well fought. The Wild Hunt will deal with the rest as necessary. There is one more foe for us to vanquish.\n\nAre you prepared?',39335),(60191,377,0,0,0,0,0,0,0,'Good. The Drust have been dealt a significant blow.\n\nThe spirits of those lost to Ingra Drif\'s treachery can at last be at peace.',39335),(60192,11,1,0,0,0,0,0,0,'Ha! There\'s nothing left to protect her now. Let\'s finish this!',39335),(60193,1,273,1,0,0,0,0,0,'Oh, Ara\'lon... even after all he endured, he found a way to smile again... only to...\n\n<Lady Moonberry wipes her eyes.>\n\nThere will be time for tears later. We still need to stop the Drust. For Ara\'lon... and the forest he fought to protect.',39335),(60194,1,0,0,0,0,0,0,0,'Damn the Drust! This was all a diversion!',39335),(60195,1,0,0,0,0,0,0,0,'So many powerful souls, this new additional shall bolster our forces greatly!',36753),(60215,0,0,0,0,0,0,0,0,'Thanks for taking out Doomwalker, let\'s hope that doesn\'t happen again! It will though!',41031),(60230,1,0,0,0,0,0,0,0,'So many souls, we have much work to do!',37142),(60236,1,0,0,0,0,0,0,0,'My most gracious gratitudes to you, Maw Walker!\n\n<Cryptkeeper puts the ring into his pocket and pats it comfortably.>\n\nNow I may attend the Ember Court in my finest appearance.\n\nI do hope the Accuser will be performing rituals there...',38134),(60237,1,5,0,0,0,0,0,0,'Thank you, Maw Walker. This extra anima will tremendously aid our efforts.',37176),(60238,0,0,0,0,0,0,0,0,'This present looks like it has been shaken a few times. The tag on it reads:$b$bTo a very special $r $c.',36949),(60239,0,0,0,0,0,0,0,0,'A small tag on this present reads:$b$bHappy holidays, $n!',36949),(60242,0,0,0,0,0,0,0,0,'Ah, quite a find. We rarely get a glimpse into the mechanisms by which the House of Rituals enact their dark designs. I am eager to delve into this tome, purely in the interests of knowledge, of course.\n\nYou may choose from some of our procured items as a reward.',40725),(60243,0,0,0,0,0,0,0,0,'Yes, yes this is exactly what I was speaking about. The foolish generals of Revendreth would use this medallion to orient themselves during travel in unknown areas, but their ambitions were small.\n\nFor my people, who have traveled beyond the known lands, such a thing is invaluable when attempting to chart a way to return.\n\nWe will make great use of this, it is good to see it returned. Here, a prize for you.',40120),(60244,0,0,0,0,0,0,0,0,'A tome from Revendreth? Yes, let me see.\n\nIt chronicles the alchemical formulae necessary to form the dredger pools, and various recipes for forming and utilizing the little creatures. They are quite a curiosity, as much a minion as a reagent.\n\nI will gladly take this off of your hands in exchange for a trade. Here, choose.',36949),(60246,0,0,0,0,0,0,0,0,'Oh, what is this? It is so bulbous and squirming, it must be close to the next molting. I am something of an amateur gorm-breeder myself, and will find a proper place to raise this one. \n\nYou may trust that I intend to destroy no worlds, I give you my word.\n\nNow, I must tend to him, gather something from our stocks on your way out.',37176),(60247,0,0,0,0,0,0,0,0,'Quite interesting, these coins are only granted to champions of the Maldraxxus arena after a certain amount of time in service. Purely ceremonial, they are worthless to most, but priceless to those that value ceremony. \n\nYou may take something with you in compensation.',42698),(60248,0,0,0,0,0,0,0,0,'Oh my, this is quite a find. It is a catalogue of some of Stradama\'s procured objects, hidden away within her pools of plague. We will make good use of this, to be sure. \n\nChoose something to take with you, you have earned it.',36753),(60249,0,0,0,0,0,0,0,0,'A strange bauble, likely from another world. Yet, why would the paragon have brought this with her? \n\nPerhaps when carrying the soul of a child, as a reminder of something she had thought lost within herself? I will ponder this.\n\nYou may choose a reward from our stores.',36949),(60250,0,0,0,0,0,0,0,0,'The fools, giving away an object such as this as a mere trinket to be used in battle. Do they not know of its significance? Clearly not.\n\nLet me explain.\n\nThere is much we do not understand about the workings of this world. This city, Oribos, is made of a strange ore that we have not found anywhere else. Who made this place, and why?\n\nRelics of similar make like this are all that we have to tie together the threads of mystery.\n\nWe thank you for this gift. Please, take a treasure.',36839),(60251,0,0,0,0,0,0,0,0,'I can only decipher a few words of this missive, give me a moment.\n\nIt appears to be a warning from the Margrave to another lord of Maldraxxus, or perhaps another place.\n\nI see mention of the Primus, and discussion of his fate. Or someone else\'s? It is hard to tell. It appears to point to a location, but I cannot understand the description of the location.\n\nThis may be more valuable than you know for the fate of the Shadowlands. Choose a reward, I will continue my work on this.',42698),(60252,0,0,0,0,0,0,0,0,'This memory glass is old, very old. It may be the memory of a soul that moved on many years ago, we can never be certain. What is known is that the knowledge contained within can never be replicated, and soon, will never be seen again.\n\nI will immediately get to work in preserving what of it I can. I must ask that you take your leave now, please choose a suitably rich reward for your efforts.',37899),(60253,0,0,0,0,0,0,0,0,'What sort of tome is this? May I leaf through it for a moment?\n\nWell then, this is quite a find. It represents many years cataloguing everything Nalthor knew about the origins of our world. The many curiosities of this place, from Zovaal\'s domain in the Maw, to the function of this strange city of Oribos.\n\nIt is surmised that they all tie together.\n\nI shall devour it with glee. Come, you may take one of our most prized possessions for it.',39282),(60254,0,0,0,0,0,0,0,0,'We have found only a few objects similar to this in all of our time here, that I am aware of. Whether it belonged to a race of creature or automatons that came before us, or they still exist somewhere, we do not know.\n\nThe metallic fragments of this piece appear similar in design to the walls that surround us here in Oribos, yet we have never seen something like this moving around in the city.\n\nI will add it to the cache of relics related to these mysteries. Take a suitable reward with you.',37899),(60255,0,0,0,0,0,0,0,0,'This mask is similar in features to some of the automaton parts we have found in our time here in the Shadowlands. Perhaps it belonged to an ancient civilization? The information we have is scattered and incomplete.\n\nAny further pieces you may find of this sort will help us unravel these great mysteries. There seems to be a greater design to this place than we can see, yet so much of it eludes us.\n\nI will take it off of your hands, in exchange you make take one of our most valuable pieces.',37176),(60256,0,0,0,0,0,0,0,0,'Now this is quite a find. A functional piece of the mysterious machinery that can be found around the Shadowlands.\n\nLook at how intricate the weaving of the golden orb is, how the energy seems to be contained from somewhere within, yet in a construct that is almost beyond imagining. What could have made such an object? Where are they now?\n\nWe shall begin to investigate with fervor. Do drop in if you find anything similar, and take a reward before you go.',36949),(60257,0,0,0,0,0,0,0,0,'This... is not what I expected.\n\nIt is similar in appearance to our people, yet so very different. Are there others of our kind out there? Who are they, and where do they reside? Why have they not made contact with us? Or are they hiding themselves purposefully?\n\nIs this a history we knew but have forgotten? I have so many questions.\n\nI thank you for this, it is quite meaningful to us. Please, take a relic of power from the treasury.',37176),(60265,1,0,0,0,0,0,0,0,'Well done.\n\nWe will bleed this miscreant \"Harvester\" dry.',43206),(60267,0,0,0,0,0,0,0,0,'<As you place the key into the device, it shudders for a moment and begins to unlock.>',38134),(60268,0,0,0,0,0,0,0,0,'You could be the key to my freedom. Will you help me, mortal?',38134),(60269,0,0,0,0,0,0,0,0,'It\'s been an age since I knew anything other than the contours of this hellish prison.\n\nThank you, mortal. Now to aid you.',38134),(60270,1,1,0,0,0,0,0,0,'Breaking a prisoner\'s chains? I\'m not sure I know how that could be done, unless...$b$bIt\'s dangerous, but I believe there may be a way.',38134),(60271,1,1,0,0,0,0,0,0,'Your success continues to impress, Maw Walker.\n\nThough I admit, such feats are becoming less unexpected as I come to know you more.',38134),(60272,0,0,0,0,0,0,0,0,'Freedom. Of a sort. Yes... this is good. You have my thanks.\n\nWhat was it you wanted? Ah, power. Yes. Very well, then.',38134),(60274,0,0,0,0,0,0,0,0,'Ah, you must have been sent by Ta\'rela. We have need of your services.\n\nTrust me, we will make it more than worth your while.',39262),(60276,1,0,0,0,0,0,0,0,'Your reward, as promised.',36949),(60277,1,0,0,0,0,0,0,0,'You did it then? Fair enough. Now we can all get back to work.',38556),(60281,1,0,0,0,0,0,0,0,'Fine work. This should keep the both of us safe from the Mawsworn. \n\nI will hold onto the sphere that you found for the purpose of study.\n\nDon\'t you have other matters to attend to?',36949),(60283,1,0,0,0,0,0,0,0,'Thank you, $p. Your contribution has been logged in our records for posterity to appreciate!',37142),(60284,6,0,0,0,0,0,0,0,'The Beastwarrens, you say... I wonder what they are plotting...\n\nSuch an embarrassment that they were discovered and captured in the first place. It seems Cartel Ve has become quite careless in my absence.\n\nYou have my gratitude for your assistance, as always. I will inform you when I have need of your services again.',36753),(60285,0,0,0,0,0,0,0,0,'Interesting... runes that can detect brokers by using our extracted essence.\n\nLet us hope you were able to stop any further production. I will keep these for study.\n\nAt some point, you will certainly need to walk the nightmarish plains of the Beastwarrens again. My cypher will continue to allow you to do so.',36753),(60287,1,0,0,0,0,0,0,0,'You seem to have a knack for drawing the Jailer\'s attention.\n\nThis changes the terms of our arrangement.',36949),(60289,6,0,0,0,0,0,0,0,'One of your associates was taken into Torghast? \n\nIt sounds as if he put up quite the fight. Perhaps he could also prove useful... if he were to be rescued.',36949),(60291,1,0,0,0,0,0,0,0,'<Rathan gives Flytrap an apprehensive look.>\n\nThat\'s... that\'s great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>',37176),(60296,669,0,0,0,0,0,0,0,'It is done.',39229),(60313,1,0,0,0,0,0,0,0,'I am glad you made it here alive.\n\nGeneral Draven has informed me of a plan that might just work.',36734),(60315,5,0,0,0,0,0,0,0,'Our harvest is saved! Oh thank you, brave adventurer, our tribute may be saved yet!',39229),(60316,5,0,0,0,0,0,0,0,'Oh! Broke praetor is gone? Sad. So sad. But thank you-hoo!',36710),(60338,1,0,0,0,0,0,0,0,'We haven\'t seen anyone come through the gateway in a very long time! Certainly not someone like you.\n\nWhat brings you to Ardenweald?',36734),(60341,1,0,0,0,0,0,0,0,'If you can handle the spriggans, then perhaps I can give you some of the more interesting items on Lady Moonberry\'s agenda. Excellent!',36734),(60342,1,5,0,0,0,0,0,0,'Good work, both of you! \n\nGuillotine\'s efforts have not gone unnoticed. I\'ve seen the others redouble their efforts to follow her example.\n\nThank you both, again.',37176),(60366,1,0,0,0,0,0,0,0,'You have my gratitude for restoring balance to these fascinating creatures. We all have our part to play.',39262),(60381,0,0,0,0,0,0,0,0,'Our bonds are stronger, our roots grow deeper, due to your actions this day. We will hold strong against the onset of foes that plague us, as groves weave together in defense, thanks to you.',37474),(60382,0,0,0,0,0,0,0,0,'As we aid our allies, we all remember the bonds that forge us together in our world. Together, we will overcome, and only together, will the Shadowlands function once more.',37474),(60384,0,0,0,0,0,0,0,0,'Even in dark times, we cannot allow others to be alone with their troubles. It is only when we stand together that the Shadowlands can become whole again.',40120),(60385,0,0,0,0,0,0,0,0,'I smell a group of successful hunters, good. Each successful hunt brings us one step closer to a trained hunting pack.',38134),(60388,0,0,0,0,0,0,0,0,'You have done well, we will allow them to rest a moment. Today they have learned that even in the calmest meadow, there is always danger.',40120),(60389,0,0,0,0,0,0,0,0,'Ain\'t never been a friend to no Night Fae, but maybe it\'s about time we went lookin\' for more allies. Gotta start somewhere, I suppose.',38134),(60390,0,0,0,0,0,0,0,0,'Stability in Ardenweald will serve us as we move against the enemy. This was a solid strategic choice, Maw Walker.',36949),(60393,0,0,0,0,0,0,0,0,'We are one step closer to returning our supply of souls to a functioning form, Maw Walker. This is an important advancement in the war for Maldraxxus.',36949),(60394,0,0,0,0,0,0,0,0,'Always wanted to eat a steward, never got the chance to. Really wonder what they taste like. \n\nWas a good thing you did for them, anyway. Just got some idle musings I do.',40593),(60396,0,0,0,0,0,0,0,0,'Our rival houses will think twice before stepping foot outside of their strongholds again. Blood and glory to you, Maw Walker.',37176),(60397,0,0,0,0,0,0,0,0,'Maybe things get a bit more stable down there in Maldraxxus, now. Would do us all a lot o\' good.',38134),(60398,0,0,0,0,0,0,0,0,'With your aid, we have once again been able to perform our sacred duties in defense of the Shadowlands. Little by little, we right the wrongs that have sent us awry, that the cycle can begin anew.',37176),(60399,0,0,0,0,0,0,0,0,'Ya did a good thing today, an\' we\'re safer for it. Never been one to give a compliment, me, but today I gotta say ya did a good one.',36949),(60401,0,0,0,0,0,0,0,0,'Oh, well, good job carting this one around, then. Hope they didn\'t give you any trouble.\n\nMaybe a little trouble would be acceptable.',38134),(60402,0,0,0,0,0,0,0,0,'Good, good, I can already see this one\'s learned a thing or two today. I\'ll take it from here.',36753),(60405,0,0,0,0,0,0,0,0,'Well well well, kind of surprised you managed to make it back with your trainee intact. Guess you\'re a better instructor than I gave you credit for. Going to keep that in mind.',37176),(60406,0,0,0,0,0,0,0,0,'Thank you for showing them around today. There\'s plenty to learn still, though.',40944),(60408,0,0,0,0,0,0,0,0,'By my bones, you came back and your trainee isn\'t a pile of mush. Can\'t believe my eye sockets.',36949),(60410,0,0,0,0,0,0,0,0,'Well, it looks like you drilled some good experience into this one today. Only a few broken bones!',37142),(60411,0,0,0,0,0,0,0,0,'Looks like this one\'s got a bit more in the head now, maybe they\'ll survive beyond a battle now.',37474),(60414,0,0,0,0,0,0,0,0,'Oh, this is quite a find. These will allow me to procure some rather rare ingredients and materials, and with them, we may turn the tide against our foes. Well done.',37474),(60416,0,0,0,0,0,0,0,0,'The clink of the coins is the sound of secrets being revealed. Many uses, many things I will purchase. More powerful will we become, due to this. A good find.',37176),(60418,0,0,0,0,0,0,0,0,'I\'ve gotten word from our Kyrian allies that you did them a great service! Thank you!',41079),(60419,0,0,0,0,0,0,0,0,'I\'ve heard many tales of your greatness, the Winter Queen is quite pleased! \n\nPlease take this, and keep up the fight!',39291),(60420,0,0,0,0,0,0,0,0,'The houses of Maldraxxus are once again in balance, and not a threat to us... for now at least. \n\nYou did great!',40120),(60421,0,0,0,0,0,0,0,0,'Ha, take that Denathrius. He won\'t be allowed to rule the Shadowlands if you have anything to say about it!',40120),(60422,0,0,0,0,0,0,0,0,'You have secured our alliance with the Night Fae, and in doing so, we hold a stronger position across the Shadowlands.',43345),(60423,0,0,0,0,0,0,0,0,'The cycle will continue, as we have willed it to be so. \n\nWith every foe you slay, the name of Maldraxxus is spoken with glory and purpose.',37142),(60426,0,0,0,0,0,0,0,0,'We will always rise to the defense of the Shadowlands, even if we are weakened from within. \n\nYou have shown that no foe is too far to escape the reach of Maldraxxus.',37176),(60427,0,0,0,0,0,0,0,0,'The Archon has sent word of your deeds, and agreed to support us in the battles to come. We will fix this broken cycle, with steps such as this leading the way.',38134),(60428,0,0,0,0,0,0,0,0,'The Primus was always fond of his trials. It seems you\'ve passed this one. Well done.',36710),(60429,0,0,0,0,0,0,0,0,'The stories of your power reverberate across the landscape. The bones of the fallen tremble at your name. Let us revel in your victory today!',36949),(60431,0,0,0,0,0,0,0,0,'The warriors of Maldraxxus speak your name, a great victory to have achieved this day. The balance of power will be restored one day, and our alliances will pay dividends.',40593),(60432,0,0,0,0,0,0,0,0,'We are more secure in our position due to your actions today. Revendreth will not fall to the sway of Denathrius, not as long as we hold firm.',43345),(60433,0,0,0,0,0,0,0,0,'Denathrius did not expect us to rally so quickly, to serve our great purpose in the cycle. \n\nHe underestimated our house for the last time, and has paid the price in blood.',36949),(60435,0,0,0,0,0,0,0,0,'The generals that serve our enemies in Revendreth will think twice before attempting to control the Shadowlands. \n\nWe have aided unlikely allies, and forged true bonds with Revendreth today, and it is thanks to you.',39291),(60436,0,0,0,0,0,0,0,0,'In a land of champions and war, you have proven your worth. Few can claim to have taken on the greatest defenders of the Shadowlands and survived, yet here you stand, a monument to the strength of the Night Fae. \n\nMay it never wane.',40120),(60437,0,0,0,0,0,0,0,0,'You have shown courage in the face of great doubt. There are many kinds of strength, and you have shown that you possess one that goes beyond the blade and bow.',40443),(60438,0,0,0,0,0,0,0,0,'A quiet has overtaken the glade, the leaves no longer rustle in anguish. This is your doing, and we will not forget this kindness.',40120),(60440,0,0,0,0,0,0,0,0,'It is a shame your job was completed so quickly. So many foes, so little time!\n\nYou are a good addition to our forces, I really enjoy all of this slaying.',37176),(60441,0,0,0,0,0,0,0,0,'Those that have no masters have learned a lesson today.\n\nWe are their masters, in the end.',40725),(60443,0,0,0,0,0,0,0,0,'You return victorious, atop a mountain of bloody feathers! Ha ha! Glorious!',36839),(60444,0,0,0,0,0,0,0,0,'The sins of the doubtful have been purged.',40944),(60445,0,0,0,0,0,0,0,0,'You stand alone atop a pile of bones, as a true master of combat. You have shown yourself a real Necrolord today!',36949),(60446,0,0,0,0,0,0,0,0,'Let this be a lesson to them, Revendreth will not stand by and let the balance be disturbed.',40593),(60448,0,0,0,0,0,0,0,0,'Justice has been served.',38134),(60449,0,0,0,0,0,0,0,0,'I have heard of your bloody exploits in Revendreth, and I am pleased. \n\nDid you bring me back any of their teeth? No? Well, maybe next time.',37176),(60451,1,0,0,0,0,0,0,0,'Good work. I see that our defenses have been shored up.',36710),(60452,0,0,0,0,0,0,0,0,'You did great! We learned a lot from your reports, and it sounds like you did some good down there. Good job!',37988),(60453,0,0,0,0,0,0,0,0,'You wield a fine weapon. Now you must put it to use.',36710),(60455,0,0,0,0,0,0,0,0,'He has seen you, and you are now marked. Wear this as a badge of honor. None other could have done what you did.\n\nHe is not afraid, yet, but he will be.',36753),(60457,0,0,0,0,0,0,0,0,'You have done us a great service today, Maw Walker. We shall use these to nourish what we can.',40120),(60459,0,0,0,0,0,0,0,0,'The armies of the undying will not fall today, Maw Walker. You emerge victorious once more in the face of great power, impressive.',36949),(60461,1,0,0,0,0,0,0,0,'Show me this runeblade of yours, mortal.',36710),(60466,1,0,0,0,0,0,0,0,'These are perfect! Go in service, always.',36710),(60467,6,0,0,0,0,0,0,0,'<Sabina begins to stir. >\n\nAre... are they back? Help... help me.',36949),(60468,1,0,0,0,0,0,0,0,'This looks like it could fit.',36949),(60469,6,0,0,0,0,0,0,0,'They\'ve perished? Are you sure? Who could have done something so cruel...',36949),(60470,0,0,0,0,0,0,0,0,'Sabina\'s end has found her. Ash is all that remains.',36949),(60480,1,0,0,0,0,0,0,0,'Much obliged. These torches keep the effects of the Endmire at bay. Even scares away the devourers for the moment. Only lasts so long though. \n\nI miss the good ol\' days of only having to worry about manifestations down here.',38556),(60482,1,0,0,0,0,0,0,0,'You can kill more of them if you want.',36949),(60487,1,0,0,0,0,0,0,0,'Yeah, these\'ll last me awhile.\n\nAlright, I\'ll show you the trick to making a barricade quickly...',38134),(60500,1,0,0,0,0,0,0,0,'With this, we are one step closer to realizing the revitalization of Revendreth.',43345),(60501,1,1,0,0,0,0,0,0,'Denathrius once served a noble cause. His charismatic leadership and understanding of the dark desires were instrumental in the redemption of more souls than your world has known.\n\nPerhaps in time, he could be this again. If the right lessons were to remind him of his true purpose.',42488),(60502,1,0,0,0,0,0,0,0,'This naaru shall prove an invaluable ally.',42488),(60505,1,0,0,0,0,0,0,0,'Your help is always welcome, Maw Walker.',37176),(60506,0,0,0,0,0,0,0,0,'We meet again. Under dire circumstances I fear.',36734),(60508,1,0,0,0,0,0,0,0,'Some vile force in this place intends to stop us from finding Tyrande.\n\nIf experience serves, that means we must be on the right track.',37474),(60509,1,0,0,0,0,0,0,0,'I see you decided to get your hands dirty and join us gents in the labor pool.',36949),(60510,669,0,0,0,0,0,0,0,'May our victory bring them peace.',37176),(60514,1,0,0,0,0,0,0,0,'<Constantin examines what you have brought him>\n\nWell done. You may make a fine hopebreaker yet.',38556),(60519,0,0,0,0,0,0,0,0,'Gone so soon... the forest must be in even more dire straits than I realized.\n\n<Moonberry looks crestfallen for a moment before resolutely setting her hands on her hips.>\n\nWell, then we\'ll just have to help ease the Queen\'s burden. Then she\'ll have the time to grant you an audience!',36734),(60520,0,0,0,0,0,0,0,0,'There, that seems to have calmed her. I can feel her dreams begin to ease.\n\nYou really do have a knack for this!\n\nBut I\'m worried that we\'re only buying time, and we need to do something more drastic.',36734),(60521,0,0,0,0,0,0,0,0,'Lady Moonberry said she would be sending a strong hand to help secure this grove.\n\nNow, how are you in a fight?',36734),(60522,0,0,0,0,0,0,0,0,'Oh, you have a spirit cradle! That will be quite useful, indeed.\n\nAssuming we can calm this chaos, of course. The wildseed you bonded with is having intense nightmares... and they\'re manifesting all over the grove!',36734),(60530,1,1,0,0,0,0,0,0,'Tyrande must see reason. She cannot save the kaldorei if she remains lost within this darkness.',37474),(60545,1,0,0,0,0,0,0,0,'It is good that you have arrived.\n\nWe need heroes like you in this dire hour.',39653),(60557,1,0,0,0,0,0,0,0,'Our forces stand ready to fight once more!',36710),(60563,1,6,0,0,0,0,0,0,'Fine work. We mustn\'t stop tending to the wildseeds that the Winter Queen has chosen to be saved.\n\nNow, perhaps you can lend me a hand with another matter.',36734),(60566,1,0,0,0,0,0,0,0,'<Breakfist is badly injured.>\n\nToo many... couldn\'t make it...',36734),(60567,6,274,1,0,0,0,0,0,'Normally, I wouldn\'t require help from whatever race you are.\n\nAh... my apologies. That was rude.\n\nPlease understand that Ardenweald is home to souls from across all of the mortal realm. It\'s hard for me to keep track of every race that arrives here.',36734),(60572,0,0,0,0,0,0,0,0,'You\'re ready to begin preparing for the ritual? Wonderful.\n\nI am also ready!',36734),(60575,273,6,0,0,0,0,0,0,'Great work. This should help get the Tranquil Pools back to normal.\n\nI admit, I had thought the worst when I couldn\'t find any of the tenders. I\'m glad they were only eaten by the local vegetation.',36734),(60577,273,1,0,0,0,0,0,0,'The animacones! In this time of drought, we have to scrounge for every bit of anima we can get. Thank you.',36734),(60578,0,0,0,0,0,0,0,0,'To have an old friend turn against you, in the most terrible way. How very painful. \n\nBut we are so close now, to soothing the spirit within the wildseed.',36734),(60594,1,0,0,0,0,0,0,0,'Starlight shines within Dreamweaver, radiant and serene.\n\nAnd... two rivers meet in a lush delta. A wildseed and a mortal, both new to the forest. Bonded by spirit and by fate.\n\nLong has it been since the boughs beheld such an event. The weald will be watching.',36734),(60600,0,0,0,0,0,0,0,0,'Shadows loom over Heartwood Grove. Things unseen crawl within the darkness.',36734),(60621,0,0,0,0,0,0,0,0,'This attack... It is like they are being driven!',36734),(60622,1,0,0,0,0,0,0,0,'Do you think he saw that one coming?\n\nThat was an attempt at mortal humor. You may laugh at your leisure.',36839),(60624,274,0,0,0,0,0,0,0,'We can\'t leave Heartwood Grove like this.',36734),(60628,0,0,0,0,0,0,0,0,'Only Ara\'lon and Lumera survived? The rest have fallen?\n\n<Korayn trembles with unbridled fury.> \n\nI will see to it that their bodies are retrieved. And this cannot go unpunished. We will avenge them all!',36734),(60629,0,0,0,0,0,0,0,0,'You found far more weapons than I expected.\n\nVery strange. How could they acquire so many of OUR blades?\n\n<Korayn appears troubled.>\n\nThey will be used against our enemies again, I swear it.',36734),(60630,0,0,0,0,0,0,0,0,'If it was not clear before, it is now. This is a personal hunt.\n\nWe will rid Ardenweald of this monster.',36734),(60631,0,0,0,0,0,0,0,0,'We have slain so many, and yet more remain. We must get to the heart of this evil and tear it out.\n\nIf we don\'t, then soon it could spread all across Ardenweald.',36734),(60632,0,0,0,0,0,0,0,0,'It cannot be easy for Korayn to hunt one of our own... but she is right. The forest is not safe so long as Lorkron lurks within it.\n\nWhat a terrible fate... both for those who become possessed, and those who must hunt them down.',36734),(60637,66,274,0,0,0,0,0,0,'Thank you. I tried so hard to save them... but once that mask is on, there is no return.',36734),(60638,4,273,0,0,0,0,0,0,'You found more wildseeds! They\'re so weak... I can\'t stand to see them like this.\n\nWe need to finish this and bring them to Tirna Vaal as soon as possible.',36734),(60639,18,274,0,0,0,0,0,0,'Korenth is... gone? And the heart of the grove has been taken?\n\nThen... then we have much to do.',36734),(60640,1,0,0,0,0,0,0,0,'Your efforts revitalize the grove, and with it, countless spirits in need of aid.',38556),(60641,1,0,0,0,0,0,0,0,'You have this grove\'s gratitude. Yet more spirits may now rejoin the cycle.',39427),(60642,1,0,0,0,0,0,0,0,'The conservatory, and the spirits who are tended here, are forever in your debt.\n\nThank you, Maw Walker.',39427),(60644,1,1,0,0,0,0,0,0,'Were it not for your efforts, I am certain my body and soul would be trapped in this forsaken place for eternity.\n\nI owe you my life, $n, and I will fight to my last breath to repay this debt.',39229),(60646,1,0,0,0,0,0,0,0,'Your burden is great, but today you have saved souls from damnation.',37988),(60647,274,0,0,0,0,0,0,0,'So many animacones lost... at least we were able to recover these.',36734),(60648,274,0,0,0,0,0,0,0,'Derawyn... I can\'t lose her too! We can use the animacones to save her!',36734),(60651,1,4,0,0,0,300,0,0,'FEED ME!',40443),(60661,0,0,0,0,0,0,0,0,'Well met, stranger. You arrive in... interesting times.\n\n<Herne snorts a laugh.>\n\nAnd with equally interesting company.',36734),(60671,66,0,0,0,0,0,0,0,'The heart of the grove...\n\nWe have to get it back... for all those who have fallen.',36734),(60673,378,0,0,0,0,0,0,0,'He showed so much promise in his duties.\n\nI suppose the promise of power was too much for him to resist. But now is not the time to dwell on such things, $n. Let us proceed.',43206),(60709,0,0,0,0,0,0,0,0,'We\'ve lost so much. Why would anyone do this?',36734),(60721,1,0,0,0,0,0,0,0,'Anima is flowing to a ward once more. You will want to return to the device periodically and channel more.\n\nAs you gather anima and channel it into Revendreth, the flows will grow stronger. Though they will not last for long right now, eventually you will be able to reinforce the channel, making a permanent connection.\n\nWith anima flowing into our lands once again, it is only a matter of time until we unite all of Revendreth under our banner.',36949),(60722,1,0,0,0,0,0,0,0,'Yes, yes! I feel the flow of anima. You will want to return to the device periodically and channel more.\n\nAs you gather and channel more anima to a tower, its connection to our sanctum will grow stronger. Eventually you will be able to reinforce the channel, making it permanent.\n\nWith enough anima flowing throughout Maldraxxus, our armies will be unstoppable!',36753),(60724,0,0,0,0,0,0,0,0,'Shadows loom over the weald, harbingers of tragedy to come.\n\nThe river of fate flows swiftly, its currents inexorable. Where they lead... cannot yet be seen.',36734),(60732,1,0,0,0,0,0,0,0,'Rejoice in your accomplishment, but do not forget the weight of your actions.\n\nHe is always watching.',39289),(60733,1,0,0,0,0,0,0,0,'By blood and thunder, we will crush our foes.',36710),(60737,0,0,0,0,0,0,0,0,'<The runeblade glows brighter as you approach an old stone altar.>',36710),(60738,0,0,0,0,0,0,0,0,'I\'m surprised that any wildseed could spawn such nightmares.',36734),(60762,1,0,0,0,0,0,0,0,'It is perhaps... ethically questionable to benefit from these motes, given their source. \n\nBut such knowledge may prove vital in defeating our enemies.',38134),(60763,1,0,0,0,0,0,0,0,'I hope that your arrival in Ardenweald is a sign that better times are on the horizon.',36734),(60764,0,0,0,0,0,0,0,0,'It\'s good to see you again. The Wild Hunt could use your help.',36734),(60765,1,5,0,0,0,0,0,0,'You and Roseboil have done well to help the survivors from the House of Plagues.',37176),(60766,1,0,0,0,0,0,0,0,'Thank you, $c. We will need all the strength we can muster in the coming days.',36710),(60767,1,0,0,0,0,0,0,0,'I will see to it that King Greymane and the Lord Commander receive these reports, though I fear this is only the beginning.\n\nThis courier has just brought us dire news from Icecrown.\n\nIt appears we are not the only ones under assault.',36710),(60775,1,0,0,0,0,0,0,0,'Next time, ask me how to run a stampede of mawrats off the edge of a cliff. That never fails to entertain.',38556),(60778,1,0,0,0,0,0,0,0,'That was fun to watch! You had that bird ready to build a nest and raise hatchlings!\n\nOh, how I needed that laugh...',36734),(60828,1,0,0,0,0,0,0,0,'Our scouts report increased activity among the Cult of the Damned.\n\nI believe it is time we learn exactly what our fanatical friends are planning.',36710),(60831,6,0,0,0,0,0,0,0,'Ah... apprentice? Are you there? I feel... strange.',36710),(60839,0,0,0,0,0,0,0,0,'Thank you for rescuing my fellow hunters. We\'ll have time to respect those who have returned to the cycle when this is all over.',36734),(60843,1,0,0,0,0,0,0,0,'These should suffice.',36710),(60856,0,0,0,0,0,0,0,0,'Fine work, $n. This won\'t win our war... but it will at least help us in the fight for Soryn\'s Meadow.',36734),(60857,1,0,0,0,0,0,0,0,'<Droman Krelnor sighs wearily as he reads the short list of wildseeds.>\n\nAt least a few will be relocated to Tirna Vaal.',36734),(60859,1,0,0,0,0,0,0,0,'It\'s been a while since a new soul arrived in Ardenweald, so each one already here is precious to us.\n\nI\'ll be sure to let Lady Moonberry know of your heroic rescue efforts on her behalf. She might even decide she owes you a favor!',36734),(60861,1,0,0,0,0,0,0,0,'<This news is rather unsettling.>',36710),(60867,1,0,0,0,0,0,0,0,'With their numbers momentarily reduced, now is our chance to strike.',36710),(60869,1,1,0,0,0,2000,0,0,'This is troubling news, $p. To think that Sylvanas would willingly ally with such a dark power...',36665),(60871,1,1,0,0,0,2000,0,0,'These are grim tidings, $p. It seems the Banshee has aligned herself with a darker power than we know.',36710),(60881,0,0,0,0,0,0,0,0,'It is good to see part of the Wild Hunt\'s strength restored... and also that you found the spirit cradle of use.\n\nNow let us bring the wildseed within it to Hibernal Hollow.',36734),(60886,1,0,0,0,0,0,0,0,'We cannot lose sight of the battles ahead of us. The door will have to wait.',36710),(60898,1,0,0,0,0,0,0,0,'Keep your voice down. There are masked fae are nearby...',37474),(60900,1,1,0,0,0,0,0,0,'The volumes are not here!\n\nThe Archivist\'s final words must have meant something. A clue, perhaps?',36753),(60901,0,0,0,0,0,0,0,0,'Dreamweaver has told me much about your strange wildseed. \n\nI will do what I can to help.',36734),(60904,1,0,0,0,0,0,0,0,'Down for a little espionage and intrigue?',43206),(60905,0,0,0,0,0,0,0,0,'It\'s going to be difficult, but I know of a place where there may be enough anima to help this wildseed.',36734),(60910,1,0,0,0,0,0,0,0,'Yes! We can use these masks to disguise ourselves.',37474),(60928,1,0,0,0,0,0,0,0,'Gweyir is the only survivor... but she\'s already been afflicted by the Drust\'s cursed magic. \n\nWe can\'t just leave her here. Not like this!',37474),(60932,6,1,0,0,0,2000,0,0,'It seems that eliminating the herald has slowed the Scourge\'s advance.\n\nWe will have to remain vigilant. Thank you for all you have done, $p.',36710),(60934,1,0,0,0,0,0,0,0,'So Gweyir and Ara\'lon are the only survivors... this is grave news.',37474),(60935,1,0,0,0,0,0,0,0,'The Curator is one of the few remaining true venthyr forged during the founding of Revendreth.\n\nHer memory is vast, but her time in the Maw has fragmented the order of those memories.\n\nShe will need your help.',43206),(60972,0,0,0,0,0,0,0,0,'<The amulet glows red.>',36710),(60993,0,0,0,0,0,0,0,0,'Here we are. I\'m glad we have your friends here too.\n\nWe are going to need it if we hope to reach the temple.',43206),(60994,0,0,0,0,0,0,0,0,'Excellent work. \n\nBarrier around the temple is gone. To fix the crown, we must go there.',43206),(60995,1,0,0,0,0,0,0,0,'Forsworn defeated? Good. The fewer of them there are, the happier I am.',43206),(60996,0,0,0,0,0,0,0,0,'With the echo of Denathrius defeated, Mikanikos assures me the crown is pure.\n\nThis is a key victory for Revendreth and all the Shadowlands.',43206),(61050,1,0,0,0,0,0,0,0,'After much strategizing, the Prince and I have developed a plan that requires the aid and resources of someone I once led actions against on behalf of the Master.\n\nPrepare to shield your eyes. We need to go to Bastion.',43206),(61057,1,0,0,0,0,0,0,0,'Together, we will guard Ardenweald.',37474),(61058,0,0,0,0,0,0,0,0,'I just know that together we can save Ardenweald and all the spirits who slumber here.',37474),(61061,1,0,0,0,0,0,0,0,'You have come from beyond the veil to seek my wisdom? A long journey indeed...',37474),(61075,0,0,0,0,0,0,0,0,'Well done, Maw Walker. The Jailer\'s eyes are dangerous, indeed.',37474),(61076,1,0,0,0,0,0,0,0,'I can sense Gorak Tul\'s dark power seething within this fetish. Handle it with caution, $c.',37474),(61077,1,0,0,0,0,0,0,0,'I make no presumption that all mortals from Azeroth know each other. \n\nWhen confronting a challenging soul like this, however, it helps to offer even the faintest of familiarity.',43206),(61079,1,0,0,0,0,0,0,0,'It is satisfying to know that the Jailer\'s share now belongs to us. Well done, Maw Walker.',38134),(61088,1,0,0,0,0,0,0,0,'The curious forms of torment the Mawsworn invent will never cease to amaze me.',37988),(61095,1,66,0,0,0,0,0,0,'The Undying Army would like to thank you for your efforts in aiding Maldraxxus.\n\nPlease accept a gift in recognition of your service to our cause and our forces.',41079),(61096,1,0,0,0,0,0,0,0,'This slot shall suffice.',36710),(61098,1,66,0,0,0,0,0,0,'The Wild Hunt thanks you for your efforts in aiding Ardenweald.\n\nTake these gifts as recognition for your aid. May they help you in whatever trials may come.',42979),(61099,1,1,0,0,0,0,0,0,'Finding Baine was no easy feat. But you braved the horrors of that tower and succeeded.\n\nWell done.\n\nBut I fear your work is only just beginning.',38134),(61100,1,66,0,0,0,0,0,0,'Your assistance to our cause has not gone unnoticed. More and more venthyr across the realm bind themselves to the Court of Harvesters instead of the Master. \n\nPlease accept these token of gratitude.',45114),(61102,1,0,0,0,0,0,0,0,'Kivarr... yes, I have heard of someone by that name. Ara\'lon may know where to find her.',37474),(61104,0,0,0,0,0,0,0,0,'The end of Grathalax will deal a great blow to the Jailer\'s infrastructure. Well done.',36949),(61107,0,0,0,0,0,0,0,0,'The way is open. The eternal battlefields of Maldraxxus await you.',36710),(61113,1,0,0,0,0,0,0,0,'This is the place, but Kivarr is nowhere to be found...',37474),(61114,1,0,0,0,0,0,0,0,'This... This is from one of our own... from within the city walls.\n\nI will send word to our patrols. Remain alert, $n.\n\nShould the Scourge rise from within our own ranks, find me at once!',36710),(61143,0,0,0,0,0,0,0,0,'It feels good to be out of that cage and back home in my den.',37474),(61145,669,0,0,0,0,0,0,0,'Victory will be ours.',37176),(61171,0,0,0,0,0,0,0,0,'If the Thornspeakers have no way to break the curse, then perhaps there truly is no hope for the possessed. These are tidings most dire.',37474),(61180,669,0,0,0,0,0,0,0,'Well done. I will see that these are destroyed personally.',37176),(61190,1,0,0,0,0,0,0,0,'Now to get you and your... associates out of here.',36710),(61217,1,4,0,0,0,300,0,0,'I remember it all! No more shall I be trapped in this place.\n\nAllow me to assist you in your endeavors Maw Walker.',43345),(61218,1,4,0,0,0,300,0,0,'You\'ve done me a solid, so I\'ll do you one and help ya out.\n\nMe an\' me shovel are at your disposal.',36949),(61222,1,4,0,0,0,300,0,0,'Thank you for freeing me, Maw Walker.\n\nAllow me to repay your kindness by assisting you.',38134),(61223,1,4,0,0,0,300,0,0,'More! \n\nLet me drink from your enemies! \n\nUnleash me upon them!',36949),(61226,0,0,0,0,0,0,0,0,'We have suffered so terribly. I must preserve what I still have.',37176),(61227,0,0,0,0,0,0,0,0,'So you need a mechanic? Well, you\'re in luck!',37176),(61230,0,0,0,0,0,0,0,0,'I appreciate your punctuality.',37176),(61246,669,0,0,0,0,0,0,0,'Such power! Gharmal will have no choice but to face us now.',37176),(61252,0,0,0,0,0,0,0,0,'My baroness\'s trust in you is well warranted.',37176),(61323,0,0,0,0,0,0,0,0,'I shall execute Akarek\'s will once more.',37176),(61333,0,0,0,0,0,0,0,0,'Excellent Maw Walker. Our armies here will grow stronger with each soul you return.',37176),(61334,0,0,0,0,0,0,0,0,'A very good collection of souls. Not too broken, not too drained, and not too innocent.\n\nNever fear. Their fate is better in our hands than the Jailer\'s.',38134),(61335,1,0,0,0,0,0,0,0,'Thanks for the rescue! I owe you one.',37176),(61355,1,0,0,0,0,0,0,0,'That should be enough to hide us from the Jailer\'s sight.\n\nI need you alive. For the time being, at least.\n\nNow, back to business.',36949),(61359,25,0,0,0,0,0,0,0,'You are a Necrolord, $n. We stand strong.',37176),(61388,0,0,0,0,0,0,0,0,'May we prove worthy allies for the battles to come.',37176),(61396,669,0,0,0,0,0,0,0,'Allow me to read this for a moment.',37176),(61397,6,0,0,0,0,0,0,0,'With your unique abilities, we have an opportunity we\'ve never had before.',36734),(61404,0,0,0,0,0,0,0,0,'Mmm, water taste clean...\n\nLike me! I\'m cleanest!',38134),(61407,0,0,0,0,0,0,0,0,'Thank you, $n. The Accuser and I will personally lead the rituals during the Ember Court.\n\nWe will remind everyone of Revendreth\'s true purpose.',38134),(61412,669,0,0,0,0,0,0,0,'Every abomination denied is one less foe to contend with when we face Gharmal.',37176),(61421,1,4,0,0,0,300,0,0,'You have rescued both Enothia and myself. Allow me to repay your kindness and join you on your quest.',38134),(61422,1,4,0,0,0,300,0,0,'Finally revenge is served. Or is that justice? Something has been served for me, and maybe now I can serve you.',39289),(61423,1,4,0,0,0,300,0,0,'My memories have been restored and now I need a new path. I shall join you along yours for a time if you wish.',41079),(61424,1,4,0,0,0,300,0,0,'Allow me and my saber to thrash your enemies once more!',37899),(61425,1,4,0,0,0,300,0,0,'Thank you for the help, I made a note of it. I believe I may also be able to help you further as well.',39335),(61426,1,4,0,0,0,300,0,0,'Please take me back to Ardenweald. I can do nothing to help from here.',40944),(61475,0,0,0,0,0,0,0,0,'This is going to be such fun!',40000),(61479,1,0,0,0,0,0,0,0,'May this boon aid you in the trials ahead, $p.\n\nBefore our Queen grants you our power and we accept you formally into our midst, there are certain... traditions which we must uphold.',40000),(61485,0,0,0,0,0,0,0,0,'Let us put our plan into motion.',37176),(61492,1,0,0,0,0,0,0,0,'Well fought. That will not hold them for long, but it should buy Renathal the time he needs.\n\nThank you, mortal, for the infusion. I shall put this precious anima to good use while it lasts.',43206),(61509,0,0,0,0,0,0,0,0,'Interesting, these are in better condition than most of Chordy\'s finds.\n\nThese will serve us well. Thank you, Maw Walker.',37142),(61510,0,0,0,0,0,0,0,0,'Where did you find these? They\'re positively covered in filth!\n\nUgh, that smell! Here, take this and go clean yourself up.',36839),(61511,0,0,0,0,0,0,0,0,'Interesting finds. These will be quite useful.\n\nThank you, Maw Walker.',37176),(61518,0,0,0,0,0,0,0,0,'It seems we\'ve been discovered. Times like these demand flexibility.',37176),(61522,1,0,0,0,0,0,0,0,'<Rathan gives Flytrap an apprehensive look.>\n\nThat\'s... that\'s great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>',36949),(61523,1,0,0,0,0,0,0,0,'<Rathan gives Flytrap an apprehensive look.>\n\nThat\'s... that\'s great!\n\nThank you both for bringing back these resources!\n\n<Rathan flashes you a nervous smile.>',37142),(61541,1,0,0,0,0,0,0,0,'Oh, wow! I love guiding soulbinding! It\'s my favorite duty!',37474),(61542,1,0,0,0,0,0,0,0,'You... have lived a very interesting life.',40000),(61548,0,0,0,0,0,0,0,0,'Expertly navigated. Perhaps you should pilot the necropolis.',37176),(61550,1,0,0,0,0,0,0,0,'Together, we can do anything.',40000),(61551,113,0,0,0,0,0,0,0,'Your strength never fails to impress me.',37176),(61552,1,0,0,0,0,0,0,0,'We have much to do.',37474),(61553,1,0,0,0,0,0,0,0,'They will succeed in their mission, I have no doubt.',37474),(61557,0,0,0,0,0,0,0,0,'<Bolvar grimaces in pain.>',39427),(61567,669,0,0,0,0,0,0,0,'Gharmal\'s influence runs deep in this place, but it will fade more quickly thanks to your efforts.',37176),(61569,396,0,0,0,0,0,0,0,'Come, $p. Would you not witness your success firsthand?',37176),(61586,0,0,0,0,0,0,0,0,'Well done, Maw Walker. Our forces are prepared to strike.',37176),(61594,0,0,0,0,0,0,0,0,'It is time to depart.',37176),(61635,1,0,0,0,0,0,0,0,'So many souls, we have much work to do!',37176),(61701,1,0,0,0,0,0,0,0,'Ulfar sent you to find me? Free me from this cage, and I will do what I can to aid you.',37474),(61702,1,0,0,0,0,0,0,0,'Not a moment too soon! I appreciate your punctuality.\n\nMy den is not far away. We should hurry before more Drust arrive.',37474),(61703,0,0,0,0,0,0,0,0,'Good, you were able to find enough nox root for the ritual. Unfortunately, we have another problem...',37474),(61704,1,0,0,0,0,0,0,0,'The prince is wise to hold court. A timeless tradition of influence and prestige in this realm.',38134),(61705,1,0,0,0,0,0,0,0,'You smart! Tubbins tea is best tea!',38134),(61706,1,0,0,0,0,0,0,0,'A new court in Revendreth? The Accuser must be pleased that you chose to include rituals of atonement in the festivities.',38134),(61709,0,0,0,0,0,0,0,0,'This contains everything we need. Give me a moment and I will prepare the reagents for our ritual.',37474),(61710,0,0,0,0,0,0,0,0,'Though this bodes ill, I am not ready to give up hope that Ara\'lon survived. He may still be out there.\n\nI will assemble a search party. We will find him and bring him home... no matter what fate has befallen him. Thank you.',37474),(61711,0,0,0,0,0,0,0,0,'You performed the ritual admirably, but the Gorak Zhar\'s power was too strong for Gweyir to withstand. There is nothing more we can do, I am afraid.\n\nIt seems the masked fae are lost to us after all...',37474),(61715,1,0,0,0,0,0,0,0,'<Even through his scarred, molten visage, the emotion on Bolvar\'s face is plain.>\n\nMy daughter... here. I never thought...',36710),(61716,1,0,0,0,0,0,0,0,'A troubling vision indeed. But we must not give up hope.',36710),(61729,0,0,0,0,0,0,0,0,'Rahel has arrived from Darkhaven to assist us with, and I quote, \"killing anybody.\" She is quite eager to enter the fray.\n\nShe seemed rather upbeat at the prospect of working with you again, $p.',36949),(61730,1,1,0,0,0,0,0,0,'Anduin may appear unharmed, but his soul is imperiled.\n\nSylvanas Windrunner cannot be allowed to carry out her plan.',37474),(61739,0,0,0,0,0,0,0,0,'<Balmedar\'s voice resonates from the floating eye.>\n\nYou didn\'t really think I would risk meeting you here in person, did you?\n\nCome, we have much work to do.',36949),(61740,0,0,0,0,0,0,0,0,'I must say it was satisfying watching you wipe the smug look off of Nelesis\'s face. She always thought she was so superior.\n\nBut enough revelry. We have work to do.',36949),(61741,0,0,0,0,0,0,0,0,'This should be sufficient.\n\nLet us prepare for the ritual.',36949),(61742,1,0,0,0,0,0,0,0,'An impressive resemblance. You may just be able to pull this off.\n\nWell, what are you waiting for?',36949),(61743,1,0,0,0,0,0,0,0,'Ah, you\'ve returned. I take it the ritual went well?\n\nCome, we have much to accomplish.',36949),(61744,1,0,0,0,0,0,0,0,'There are but a few tasks remaining before we can complete our ritual.\n\nYou must begin immediately.',36949),(61745,1,0,0,0,0,0,0,0,'Kel\'Thuzad always seems to have the most studious of pets, doesn\'t he?\n\nWhat is it the baron wishes of me, acolyte?',36949),(61746,1,0,0,0,0,0,0,0,'Wonderful. Kel\'Thuzad\'s pets are nothing if not reliable.\n\nWe are done here.',36949),(61747,1,0,0,0,0,0,0,0,'Much better!\n\nI simply cannot abide a disorganized Grimoirium.',36949),(61748,1,0,0,0,0,0,0,0,'Ah yes, these will do.\n\nIt will take some time to study these tomes. In the meantime, I have more need of you.',36949),(61749,1,0,0,0,0,0,0,0,'You are Kel\'Thuzad\'s acolyte, are you not?',36949),(61750,1,0,0,0,0,0,0,0,'This specimen should work nicely for the baron\'s ritual.\n\nI will add it to his parcel.',36949),(61751,1,0,0,0,0,0,0,0,'This should do.\n\nI will assemble the reagents together to return to your master posthaste.',36949),(61752,1,0,0,0,0,0,0,0,'Let me hold onto these for now.\n\nI will need you to get your hands on that shipment!',36949),(61753,0,0,0,0,0,0,0,0,'Well done.\n\nNow we must work quickly, before we are discovered.',36949),(61754,1,0,0,0,0,0,0,0,'The runes on this blade... they are a hallmark of domination magic!\n\nThis is not good, $c.',36949),(61755,1,0,0,0,0,0,0,0,'The guards have been dealt with? Good.\n\nWe have more pressing matters, now.',36949),(61756,1,0,0,0,0,0,0,0,'I see you managed to procure the reagents from Jor\'dan, and... wait, what\'s this?\n\nI am impressed that you managed to procure the shipment from the brokers when my sorcerers could not!  \n\nYou are quite the resourceful one, acolyte!',36949),(61757,0,0,0,0,0,0,0,0,'<Balmedar\'s voice comes from the adjacent cell.>\n\nThat did not go as planned.\n\nWe need to find a way out of here. The margrave must be warned!',36949),(61758,0,0,0,0,0,0,0,0,'You are more resourceful than I thought, $c!\n\nJust a quick incantation, and we\'re on our way to freedom!',36949),(61759,1,0,0,0,0,0,0,0,'We have no time to lose!',36949),(61760,0,0,0,0,0,0,0,0,'I didn\'t think we would make it out of that encounter intact.\n\nYou are truly a skilled $c, $n.',36949),(61761,6,5,0,0,0,0,0,0,'The margrave has been captured? So Kel\'Thuzad has seized control of the house!\n\nThis changes things.',36949),(61765,1,0,0,0,0,0,0,0,'I trust you did not let your eyes wander while wearing the soulcloak? It can reveal some truly terrible things...',37988),(61786,0,0,0,0,0,0,0,0,'Your \"good bud\" Stonehead insists on fighting for the cause, $p.\n\nI\'m sure we can find a use for his skills. Nothing too complicated, of course.',36949),(61788,0,0,0,0,0,0,0,0,'Your actions on behalf of Revendreth are garnering quite a lot of attention, $p.\n\nSimone has offered to lend her expertise with the mirrors of the Ember Ward to the cause.',36949),(61852,0,0,0,0,0,0,0,0,'Hello again, $p. It is good to see you taking such an active interest in the affairs of Ardenweald.\n\nThe honorable Guardian Kota has agreed to work with us, as part of her duties to protect the grove of Tirna Vaal.\n\nTogether, you will ensure the forest\'s continued security.',37474),(61853,0,0,0,0,0,0,0,0,'The forest is ever in need, $p.\n\nTe\'zan is as spirited as ever, and perhaps a healthy dose of responsibility will lend him some direction and meaning to his afterlife.\n\nWhere should we send him first?',37474),(61854,0,0,0,0,0,0,0,0,'The forest blesses us today, $p.\n\nMaster Sha\'lor says he has sufficiently recovered from his ordeal with the gorm, and would like to be of assistance however he can. He seems especially eager to learn new things.\n\nI guess a little taste of adventure goes a long way.',37474),(61855,0,0,0,0,0,0,0,0,'Good to see you again, $p.\n\nYour continued dedication to the well-being of Ardenweald has not gone unnoticed.\n\nQadarin has expressed interest in taking a more active role. Let\'s put his skills to use, shall we?',37474),(61856,0,0,0,0,0,0,0,0,'I have a particularly special boon for you, o\' champion of Ardenweald. Are you ready?\n\nThe individual joining our Hunt today is... me!\n\n<Vesperbloom rubs her hands together, grinning.>\n\nIt will be nice to get in some field work!',37474),(61857,0,0,0,0,0,0,0,0,'$p, your devotion to Ardenweald, and to the Queen, is unquestionable.\n\nSomething you\'ve done seems to have satisfied Groonoomcrooek. I\'m not sure exactly what it was, though.\n\nIt took them a while just to tell me they would be joining us here.',37474),(61869,0,0,0,0,0,0,0,0,'These belonged to the Primus!',37176),(61874,1,0,0,0,0,0,0,0,'It is good that you have arrived.\n\nWe need heroes like you in this dire hour.',39229),(61880,1,0,0,0,0,0,0,0,'If Kassir is coming, we had better ensure this is a formal affair.',38134),(61882,1,0,0,0,0,0,0,0,'Ancient rituals? This is my kind of party!',38134),(61884,1,0,0,0,0,0,0,0,'Tubbins had better bring Gubbins along. He\'s the fun one!',38134),(61958,1,4,0,0,0,300,0,0,'New master now!',36753),(61959,1,4,0,0,0,300,0,0,'I shall pay my debt to my Maw Walker.\n\nDirect my power against your enemies.',36839),(61960,1,4,0,0,0,300,0,0,'Do you happen to have a spare leg lying around? Surely you don\'t need two. I\'ll put it to good use, kicking your enemies!\n\nNo? I can probably still help anyway.',37142),(61961,1,4,0,0,0,300,0,0,'I am prepared for combat!\n\nPut me in the front line, I will be your shield.',37474),(61962,1,4,0,0,0,300,0,0,'I shall wield my blade with purpose once more!\n\nDeath to your enemies!',36949),(61981,1,1,1,0,0,0,0,0,'Now that\'s a right grey professional job that is. This anima will get us makin\' some fancy stuff in no time.',43345),(61983,0,0,0,0,0,0,0,0,'Your contributions fuel our conquests on the battlefield. The final victory will be ours!',37474),(61984,0,0,0,0,0,0,0,0,'The anima you have provided will nourish our precious groves. We thank you.',40944),(61996,0,0,0,0,0,0,0,0,'You have helped strengthen our forces, Maw Walker.',37176),(62000,1,0,0,0,0,0,0,0,'All is as expected. Trust always in the Arbiter\'s wisdom.',45745),(62041,1,5,0,0,0,0,0,0,'Suffering is commonplace among those in Revendreth, but you and Roseboil were able to help a few of them nonetheless. \n\nWell done.',37142),(62054,0,0,0,0,0,0,0,0,'With these I\'m certain we\'ll catch the attention of Sire Denathrius.',38134),(62055,0,0,0,0,0,0,0,0,'With these I\'m certain we\'ll catch the attention of Sire Denathrius.',37176),(62085,1,0,0,0,0,0,0,0,'I\'ve been wondering where my canteen went. Where did you find this, $n? Did you take a drink before returning here?\n\nNo matter, I suppose.',36753),(62157,1,0,0,0,0,0,0,0,'They must be planning something. Though what, I cannot say.\n\nI will instruct our scouts to observe and report.',36710),(62161,0,0,0,0,0,0,0,0,'You\'re just in time. I\'ve received a missive.',36949),(62163,1,0,0,0,0,0,0,0,'I am glad for your return, $n.',36665),(62169,0,0,0,0,0,0,0,0,'You\'ve done well, Maw Walker. The Eyes place their trust in you.',37176),(62170,1,0,0,0,0,0,0,0,'Ah, these wise words are certainly Eurgon\'s. I\'m happy to report he made it home.',36710),(62183,1,0,0,0,0,0,0,0,'Oooh, is that my package of flesh eating ooze! I hope you did not get any on your hands, oh a glove, specification of this specific ooze should mean you have only a 25% chance of an adverse effect. The glove should be burned but I will leave that to your discretion. I will inform the locals of your assistance in delivery, even if it was delayed.',36753),(62185,1,0,0,0,0,0,0,0,'You have my gratitude.\n\nI assure you this will not be forgotten.',36710),(62187,1,0,0,0,0,0,0,0,'A whole sackful?! Wonderful! I\'ll be sure to put this to good use.',37176),(62189,1,0,0,0,0,0,0,0,'Oh, wow, this is a real find you have. Here, a heap of Infused Rubies for the bundle, the best you will see here in the ward. And if you see one of my goods you might like, let me know.',38134),(62194,0,0,0,0,0,0,0,0,'You have helped strengthen our forces, Maw Walker.',37176),(62195,0,0,0,0,0,0,0,0,'You have helped strengthen our forces, Maw Walker.',37142),(62213,1,5,0,0,0,0,0,0,'I knew the Maw Walker would deliver.',37176),(62214,1,0,0,0,0,0,0,0,'A small victory, Maw Walker. Many more will be required.',38134),(62216,1,5,0,0,0,0,0,0,'You two make quite the team. It\'s good to have dependable comrades in arms.',36949),(62217,1,5,0,0,0,0,0,0,'You and Marz work well together. He\'ll take the hit whenever you need him to.',37176),(62225,1,0,0,0,0,0,0,0,'Thank the Light, you have returned unharmed!\n\nWere you able to learn anything about what the cult is doing?',36710),(62232,1,5,0,0,0,0,0,0,'I see you and Marz have been busy. Job well done, both of you.',37142),(62234,1,0,0,0,0,0,0,0,'The souls trapped within the power core may yet be saved. Leave me to my research, Maw Walker.',38134),(62239,1,0,0,0,0,0,0,0,'Serves them right for leaving this unattended.\n\nI am sure we can find other uses for it.',37474),(62244,1,5,0,0,0,0,0,0,'Thank you for the supplies. I\'ll see about setting some aside for you at regular intervals.',37142),(62256,1,5,0,0,0,0,0,0,'Ah, now this is exquisite. Your reconstructed companion said you would be able to come through and you\'ve done so magnificently!\n\nLet him know I\'ll count this toward the repayment of his debts.',37142),(62261,1,5,0,0,0,0,0,0,'I see Guillotine\'s \"negotiations\" were successful.\n\nThank you, Maw Walker. These sharpening stones will be useful.',37176),(62263,0,0,0,0,0,0,0,0,'Must be nice to have the leisure to just sit and think all the time. \n\nI\'ve barely got time myself, with all the work I have keeping this place together!\n\nStill, that was nice of you to help out the old turtle.',38134),(62275,0,0,0,0,0,0,0,0,'Bastion is in dire need of your aid.',39229),(62277,0,0,0,0,0,0,0,0,'Ardenweald would be most appreciative of your help.',43971),(62278,0,0,0,0,0,0,0,0,'The armies loyal to the Primus need your aid.',37176),(62279,0,0,0,0,0,0,0,0,'Revendreth would be most grateful for your aid.',37988),(62285,1,1,0,0,0,0,0,0,'A most enlightening conflict. The Observer will be pleased.',38556),(62286,1,1,0,0,0,0,0,0,'Fascinating. Fascinating indeed. The Observer will be pleased.',37474),(62287,1,1,0,0,0,0,0,0,'I do so enjoy the completion of a successful arrangement! The Observer will be pleased.',37474),(62288,1,1,0,0,0,0,0,0,'Our arrangement allowed me to gather some very useful information. The Observer will be pleased.',37474),(62294,1,11,0,0,0,0,0,0,'This is simply marvelous! This will provide some excellent insight into the history of Margrave Sin\'dane... and possibly something we can use to our own benefit later on.',37142),(62296,0,0,0,0,0,0,0,0,'That was close. Those pests can quickly blast away whole chunks of Ardenweald if we aren\'t careful. We\'ve got enough problems on our hands as it is!',37899),(62297,1,0,0,0,0,0,0,0,'Well done, acolyte. The rest should dissipate with time.\n\nTake this, it was left behind by the feckless adept that created this mess. I hope you will put it to better use.',36949),(62308,1,0,0,0,0,0,0,0,'You have proven yourself worthy to don the mantle, acolyte.\n\nWear it with honor and pride.',36949),(62309,0,0,0,0,0,0,0,0,'$n, it is good to see you again!\n\nFollowing your success against the House of Constructs, Secutor Mevix is eager for more action on the battlefield.\n\nDon\'t leave an eager soldier to wallow here. Give him purpose!',36753),(62312,0,0,0,0,0,0,0,0,'We\'ve got an exciting development today, $n!\n\nYou must have made quite an impression. Gunn Gorgebone, one of the champions of the Theater of Pain, is demanding to join our ranks here. Demanding it!',36949),(62313,0,0,0,0,0,0,0,0,'$n! Step closer, come, come!\n\nI\'ve just received word that none other than Rencissa the Dynamo is on her way here to fight for you. Rencissa! The Dynamo!\n\nWho should we have her kill first?',36949),(62314,0,0,0,0,0,0,0,0,'Listen up, $n. We need more eyes out there on the battlefield.\n\nThere\'s too many threats, and not enough information flowing our way.\n\nSee if Khaliiq is up to the task. You heard me right, I said more Eyes!',37474),(62315,0,0,0,0,0,0,0,0,'We\'ve got a strange one today, $n.\n\nMarileth stopped by to say that his slime Plaguey is feeling more blue than usual, and asked if we could keep him entertained.\n\nWhat does this look like, a kennel? Plaguey can earn his keep like the rest of us! Get him out there, soldier!',38134),(62317,0,0,0,0,0,0,0,0,'<Sorcerer Vutral has been silenced, and with him the suspicions of your ruse.>',36949),(62320,1,0,0,0,0,0,0,0,'It brings me great relief that your pallid vestments will no longer offend my vision.\n\nDo try keep them in better repair henceforth.',36949),(62362,1,0,0,0,0,0,0,0,'A respectable amount. We will make good use of this.',36949),(62363,1,0,0,0,0,0,0,0,'I must thank you. We are no match for the Chosen when it comes to brute strength.',36949),(62364,1,0,0,0,0,0,0,0,'Good. The House of Rituals will learn not to make enemies of the House of Eyes.',37142),(62371,1,0,0,0,0,0,0,0,'Word of your aid has been sung through the roots. Thank you, friend of the forest.',40120),(62382,0,0,0,0,0,0,0,0,'She seemed nice. The Mushroom Kingdom, was it? Hmph, never heard of it. Things kids get up to these days....',37893),(62388,0,0,0,0,0,0,0,0,'It seems we may have our way into the House of Rituals.\n\nDo not mistake this lich for an ally. He pursues only his own agenda. But for now, our goals align... and we can use that to our advantage.',36949),(62390,1,0,0,0,0,0,0,0,'I will give these to the fleshcrafters. If we don\'t have enough soldiers, we will just have to build some.',36949),(62391,0,0,0,0,0,0,0,0,'Our forces stand ready.\n\nLet us end this.',37176),(62400,0,0,0,0,0,0,0,0,'I remember those guys. Bad news. \n\nThey should stick to their own realm of existence!\n\nNice job cleaning house.',37988),(62403,1,0,0,0,0,0,0,0,'A fine amount. There will surely be something useful in this collection.',37176),(62406,574,0,0,0,0,0,0,0,'I sense power. Power and ease.',37176),(62407,5,1,0,0,0,0,0,0,'How is it possible for him to smell even worse than before? \n\nUgh. At least he gets results.',37176),(62414,0,0,0,0,0,0,0,0,'You left none behind to raise alarm? Good.\n\nWe can proceed with the plan.',36949),(62417,0,0,0,0,0,0,0,0,'Nothing wrong with picking flowers for a living. It\'s good, honest work.\n\nAnd giving those blasted spriggans a kick in the rear is worthwhile too. Nice job.',38556),(62421,1,0,0,0,0,0,0,0,'The shape of the Gulper is now yours to call upon and use.',38556),(62422,1,0,0,0,0,0,0,0,'Ah, the moth. Such beautiful creatures. Their shape is now yours to call upon.',37474),(62423,1,0,0,0,0,0,0,0,'Ah. The heart of the bear! A fine shape. It is now yours, should you choose to use it.',37474),(62425,1,0,0,0,0,0,0,0,'You have shown rare bravery, $n. For this the forest recognizes you. Let all know your ferocity in defending our borders, and the love you have for our charges.',37474),(62428,1,0,0,0,0,0,0,0,'A majestic shape, for certain. It is now yours, should you choose to use it.',37474),(62435,1,0,0,0,0,0,0,0,'Ah, the stag. This shape is now yours to call upon.',41488),(62436,1,0,0,0,0,0,0,0,'The shape of the veil shrieker is now yours to use if you choose.',40120),(62441,0,0,0,0,0,0,0,0,'You continue to serve the conservatory well. For this you have my thanks.\n\nNow you may choose from the spirits I have collected myself for restoration.',39653),(62442,0,0,0,0,0,0,0,0,'I find it helpful to have you do these things for me.',38134),(62443,0,0,0,0,0,0,0,0,'I find it helpful to have you do these things for me.',39427),(62447,1,0,0,0,0,0,0,0,'You did it! I cannot quite explain why that worked. Dreams can be strange, huh?',38134),(62448,66,0,0,0,0,0,0,0,'Your actions have attracted the attention of the other houses--and those who question their orders.',36753),(62453,0,0,0,0,0,0,0,0,'You know I appreciate hard work, but it\'s important to take care of yourself from time to time. Hope you had fun, blew off some steam, and are ready to get back at it!',37864),(62454,0,0,0,0,0,0,0,0,'Perhaps a new purpose awaits me.\n\nYou have rekindled my curiosity, at least.',39427),(62456,0,0,0,0,0,0,0,0,'Now dat da ol\' boss be a captive audience, he and I goin\' ta be makin\' some new arrangements. Ya best be goin\' now, but don\'t worry... I be seein\' ya soon!',40120),(62457,1,1,0,0,0,0,0,0,'So, you succeeded where others, myself included, have failed.\n\nFrom what I hear, that\'s the second time a relic of the First Ones responded to your presence.\n\nI must admit, I haven\'t the slightest idea how you managed it. Interesting. Very interesting indeed.',40120),(62459,0,0,0,0,0,0,0,0,'Those are special moths! They really liven up the place, don\'t they?\n\nYou know moths work just as hard as anyone else, and they\'re under-appreciated. \n\nThanks for savin\' em.',38134),(62461,0,0,0,0,0,0,0,0,'I suspect this will not be your last foray into the Warrens.',36753),(62462,1,1,11,0,0,0,0,0,'Ah, very good! And a million eyes appeared, you say? How frightening! \n\nGlad she\'s gone and the key\'s in my hands now! She used it to break into many a locked door, you know? A very powerful item! Very profitable too.\n\nAnd now it\'s mine!',36753),(62465,0,0,0,0,0,0,0,0,'Always nice to lend a hand to someone who\'s just tryin\' to do their job. A metaphorical hand, obviously... although in your case, it\'s literal.\n\nI know what metaphorical means!\n\nAnyway, good work out there.',38134),(62467,0,0,0,0,0,0,0,0,'The branches of your expertise reach for the heavens and blossom. This is good.',38134),(62484,11,0,0,0,0,0,0,0,'I was not expecting that!',36710),(62536,0,0,0,0,0,0,0,0,'Thank you, Maw Walker.\n\nYou have brought back a little bit of the light from the darkness.\n\nWe will make this right, no matter how long it takes.',37474),(62544,0,0,0,0,0,0,0,0,'I thank you once again, Maw Walker.\n\nThese souls are finally free of the torment and pain.\n\nThere are still so many more, but I am optimistic that we may yet save them.',37474),(62546,0,0,0,0,0,0,0,0,'It brings me joy to see more souls freed from that dark place.\n\nThank you Maw Walker, for continuing to help us.',37474),(62549,0,0,0,0,0,0,0,0,'It brings me joy to see more souls freed from that dark place.\n\nThank you Maw Walker, for continuing to help us.',37988),(62560,1,0,0,0,0,0,0,0,'We\'re on the right track, $n! Keep doing what you\'re doing and it will be back to its full, glorious, starryness in no time!',40120),(62561,1,0,0,0,0,0,0,0,'We\'re so grateful for all your help, $n. Seeing the Heart of the Forest like this again, full of power? My heart is filled with hope.',37474),(62563,0,0,0,0,0,0,0,0,'You made that look easy. Let\'s hope she learned his lesson this time.',37142),(62567,1,0,0,0,0,0,0,0,'I\'m glad you made it, $n! Something tells me that your future is waiting for you in the past!',46597),(62568,1,0,0,0,0,0,0,0,'I\'m glad you made it, $n! Something tells me that your future is waiting for you in the past!',39804),(62603,1,0,0,0,0,0,0,0,'Another dream vision fulfilled. This is remarkable!',39427),(62606,0,0,0,0,0,0,0,0,'Ooh, that\'s the stuff all right. It\'s bitter, sure, but wonderfully complex and subtle undertones. Mm! You\'ll have to try some sometime.',37893),(62607,0,0,0,0,0,0,0,0,'Look at it sparkle and shine! I\'m getting the tingles just looking at it. I feel ages younger already!',37474),(62608,0,0,0,0,0,0,0,0,'Feel how luxurious the soil is! I\'m going to savor this for a while. Thank you.',37899),(62610,0,0,0,0,0,0,0,0,'Hmph, serves them right. Think they can go stomping around my grove? I am the only one who gets to do any stomping! I am the one who stomps!',37474),(62611,0,0,0,0,0,0,0,0,'There, it\'s done. They should be driven back, if only for a while. I appreciate the help.',37899),(62614,0,0,0,0,0,0,0,0,'Good work. They\'re still holed up in Darkreach, but that\'s the best we can do for now. Keep \'em contained, and then we\'ll burn them out.',37988),(62615,0,0,0,0,0,0,0,0,'The little misses should be safe for now. Their purpose is vital to Ardenweald, and I won\'t have any more of them dying on my watch!',37899),(62623,1,0,0,0,0,0,0,0,'You found one of my books!\n\nOh. That one.\n\n<Dreyden sighs.>\n\nI suppose I will take it back. Thanks, I guess.',39427),(62624,1,0,0,0,0,0,0,0,'I am so happy to see you have started to help restore the Queen\'s Conservatory to its former glory.',37988),(62625,1,0,0,0,0,0,0,0,'Another dream vision fulfilled. This is remarkable!',39653),(62631,0,0,0,0,0,0,0,0,'Well done, $n.',37474),(62636,1,0,0,0,0,0,0,0,'Ah, $n, you have returned. An otherworldly air hangs heavy about you.',42979),(62637,0,0,0,0,0,0,0,0,'I trust your battles went well. And that\'s not just a turn of phrase. I know they did. I knew they would.',38556),(62638,0,0,0,0,0,0,0,0,'Well done, $n. I knew you could do it.',45745),(62653,1,0,0,0,0,0,0,0,'<Archivist Janeera does not look up from her scroll as she responds to you.>\n\nNoted and logged.',36949),(62654,1,0,0,0,0,0,0,0,'You return in one piece. And with not just Darion, but his father as well. You continue to succeed, Maw Walker.',36710),(62691,1,0,0,0,0,0,0,0,'Ya did a good thing today, an\' we\'re safer for it. Never been one to give a compliment, me, but today I gotta say ya did a good one.',40443),(62694,0,0,0,0,0,0,0,0,'Our rival houses will think twice before stepping foot outside of their strongholds again. Blood and glory to you, Maw Walker.',36734),(62695,1,0,0,0,0,0,0,0,'It\'s right good of you to step up and take on this here challenge, it is. We\'ve got a lot of work to do, here in Revendreth, so\'s I hope you\'re ready to get a bit dirty.',40443),(62700,0,0,0,0,0,0,0,0,'Yes, this should be enough to engrave the runes. Upon lesser equipment, that is. \n\nPotent items will require more... more... Soul Ash. Yes, Soul Ash.\n\nAnd you should hold onto it. I will ask for it when the time comes.',40000),(62704,1,0,0,0,0,0,0,0,'Your choice is made. The Purpose will guide you forward.',45745),(62714,1,0,0,0,0,0,0,0,'What is this?\n\n<She opens the parcel. A soft smile spreads over her face.>\n\nThis is wonderful. Thank you.',36710),(62716,0,0,0,0,0,0,0,0,'Ah, $n. I was wondering when you were going to appear. Your aid is needed.',43971),(62719,0,0,0,0,0,0,0,0,'You\'ve collected all the necessary pieces. Now all that\'s left is to combine them.\n\nSpeak with me again when you are ready, and I will create the prize you seek.',40000),(62723,669,0,0,0,0,0,0,0,'Word has spread across Bastion of your deeds since your arrival here.\n\nYou have proven yourself a worthy ally of the kyrian. Take this gift in thanks, and go in service.\n\nMay we cross paths again soon.',40593),(62729,1,0,0,0,0,0,0,0,'You have fulfilled your purpose. Well done.',40593),(62730,1,0,0,0,0,0,0,0,'Yes, this very sweet and ripe. Must use quickly, before it spoils!',36753),(62733,1,0,0,0,0,0,0,0,'I hope you liked your surprise! \n\nYou find more silver strongboxes, give Ripe Purian tribute!\n\nOh-ho! You want key to my Golden Chest? Ask me about Steward of the Day!',36753),(62739,1,0,0,0,0,0,0,0,'Welcome! What brings you to the Heart of the Forest?',36949),(62748,113,0,0,0,0,0,0,0,'All who have reported back to me have said the same--you have brought victory upon victory to the House of the Chosen!\n\nOn behalf of all who serve the Primus, you have my eternal gratitude.',38134),(62761,1,0,0,0,0,0,0,0,'You have done well in Maldraxxus. Their path forward is clear.',38134),(62763,0,0,0,0,0,0,0,0,'You have done a great service to not only Ardenweald, but the countless nature spirits we protect.\n\nThank you. Today you are a hero of Ardenweald!',40120),(62776,1,0,0,0,0,0,0,0,'Your efforts in Ardenweald have not gone unnoticed, Maw Walker.',38134),(62778,1,0,0,0,0,0,0,0,'You have my sincere gratitude for aiding our cause. Together we will see Denathrius\'s hold on our realm broken, and with it win the freedom of my people.\n\nI cannot offer as much as I would like, but I hope it will suffice until our victory is achieved.',38134),(62779,1,0,0,0,0,0,0,0,'Revendreth stands stronger for your efforts. The Purpose is clear.',38134),(62785,1,0,0,0,0,0,0,0,'Oh, Anzio sent you? Hah, and here I was thinking you were just another nosy fan.\n\nYeah, you look like just the $c I need!',38556),(62807,0,0,0,0,0,0,0,0,'Many cries call in the night. Many creatures seek shelter.\n\nThis is a refreshing breeze.',36734),(62833,1,0,0,0,0,0,0,0,'For the sake of the souls we defend, we must never falter.',36734),(62834,1,0,0,0,0,0,0,0,'Surrender is the ultimate failure.',36734),(62835,1,0,0,0,0,0,0,0,'There is much to be done, Maw Walker.',36734),(62836,1,1,0,0,0,0,0,0,'Three sure signs of Anduin\'s presence, yet no sign of him.\n\nThis is dire news indeed.',37142),(62837,1,0,0,0,0,0,0,0,'$n! The darkness of the Maw lingers upon you. What news do you bring?',36949),(62839,66,0,0,0,0,0,0,0,'You walk with the stride of victory, Maw Walker. Do you bring anima?',36734),(62843,6,0,0,0,0,0,0,0,'Back again so soon, Maw Walker?',36734),(62844,1,0,0,0,0,0,0,0,'You have returned, Maw Walker. \n\nGood. We have much to do.',36734),(62845,1,0,0,0,0,0,0,0,'I could feel the presence of those souls as soon as you brought them here. Their potential will increase our power!',36734),(62846,1,0,0,0,0,0,0,0,'When it comes to matters like these, patience is as important as strength. In time, our power will grow vast and unmatched.',36734),(62848,0,0,0,0,0,0,0,0,'Our bond will grow in strength over time, but for now your training is complete.',37176),(62856,1,0,0,0,0,0,0,0,'Work with me and your legend will haunt the waking dreams of every venthyr in Revendreth.',40443),(62857,1,0,0,0,0,0,0,0,'As you can see, some have already begun to take notice of you.',40443),(62858,0,0,0,0,0,0,0,0,'Oh, wonderful news!\n\nI will make sure these souls are well taken care of here in Ardenweald.',40120),(62859,0,0,0,0,0,0,0,0,'Oh, wonderful news!\n\nI will make sure these souls are well taken care of here in Ardenweald.',37474),(62860,0,0,0,0,0,0,0,0,'Oh, wonderful news!\n\nI will make sure these souls are well taken care of here in Ardenweald.',40966),(62864,0,0,0,0,0,0,0,0,'Excellent Maw Walker. Our armies here will grow stronger with each soul you return.',36949),(62865,0,0,0,0,0,0,0,0,'Excellent Maw Walker. Our armies here will grow stronger with each soul you return.',37474),(62866,0,0,0,0,0,0,0,0,'Excellent Maw Walker. Our armies here will grow stronger with each soul you return.',37474),(62867,0,0,0,0,0,0,0,0,'A very good collection of souls. Not too broken, not too drained, and not too innocent.\n\nNever fear, their fate is better in our hands than the Jailer\'s.',36949),(62869,0,0,0,0,0,0,0,0,'A very good collection of souls. Not too broken, not too drained, and not too innocent.\n\nNever fear. Their fate is better in our hands than the Jailer\'s.',40944),(62870,1,0,0,0,0,0,0,0,'Ah, so you were successful. As I knew you would be.\n\nNow, let us put these souls to use.',36949),(62882,1,0,0,0,0,0,0,0,'Take care of that Soulkeeper. I have no desire to go through the effort of procuring another.\n\nNow, let us get to business.',36949),(62899,1,0,0,0,0,0,0,0,'Welcome to the Court of Night, $n. I just know we\'re going to save Ardenweald! Oh, and the rest of the Shadowlands, too!\n\nAnd if we can\'t, and the forest withers away, and the Jailer breaks free from the Maw and plunges all of the realms eternal into crushing despair from which there is no return... \n\nThen at least we can say we had fun trying!',40000),(62900,1,0,0,0,0,0,0,0,'You and Niya will grow together in time. But for now, your training is complete.',40000),(62902,4,1,0,0,0,0,0,0,'Boss returns the victor! You got any anima on \'and?',40443),(62903,0,0,0,0,0,0,0,0,'There we go, the anima is safe and secure now.',40443),(62904,378,0,0,0,0,0,0,0,'I\'m pleased to speak with you once again, Maw Walker.',40443),(62905,6,0,0,0,0,0,0,0,'Back again so soon, Maw Walker?',36949),(62914,1,273,0,0,0,0,0,0,'Oi! Wut\'s \'at, then? New souls, is it? \n\nRight, they \'ave a bit of potential, they do. Many fings I can do \'round \'ere wif their \'elp.',36949),(62915,1,273,0,0,0,0,0,0,'Good choice. \n\nIt\'ll take some time for the construction work to finish, but good fings take time don\'t they?',40443),(62918,1,0,0,0,0,0,0,0,'You have lived an... interesting life, thus far. I will endeavor to make it even more so.',43206),(62919,1,0,0,0,0,0,0,0,'We will accomplish much together.',43206),(62920,1,273,0,0,0,0,0,0,'Your soulbind will strengthen over time, but for now your training is complete.',43206),(62921,1,0,0,0,0,0,0,0,'I hope you\'ve found everything to your liking.',43206),(62932,1,1,0,0,0,0,0,0,'<Bolvar studies the object intently.>\n\nI sense a familiar essence. The holder of this key may have been involved in the capture of Jaina Proudmoore.\n\nI require time for further research. I will contact you once I determine our next course.',38134),(62935,1,1,0,0,0,0,0,0,'It is good that you saved those tortured souls, $n. A pity none could help our cause. \n\nI must ponder our path forward. You will hear from me again when I know how to best proceed.',38134),(62938,1,1,0,0,0,0,0,0,'It seems the greed of the brokers has proved useful.\n\nYou may have acquired exactly what we need.',38134),(62966,1,1,0,0,0,0,0,0,'I am heartened to know that Thrall yet lives. By the Light, we will find him.\n\nI fear for Anduin. Darkness hungers for his soul.\n\nWe must make ready. You will hear from me when it is time to proceed.',36949),(62969,1,0,0,0,0,0,0,0,'<Bolvar studies the totem.>\n\nYes, this could point us to Thrall\'s location.',36949),(62999,1,4,0,0,0,300,0,0,'Even if it doesn\'t bleed, we can still kill it.',40120),(63003,1,0,0,0,0,0,0,0,'I\'m so pleased to see you again, my apprentice!',37176),(63006,1,0,0,0,0,0,0,0,'Your actions here will echo beyond the veil. Aid the forest, and all mortal worlds may yet be saved.',40000),(63008,1,0,0,0,0,0,0,0,'Oh, wow! I love guiding soulbinding! It\'s my favorite duty!',40000),(63022,0,0,0,0,0,0,0,0,'Not a moment too soon! Those fiends were just about to put the sword to me. \n\nHere, as we agreed, is your payment in stygia. \n\nThough truth be told, I owe you a great deal more than this. I have nothing left to offer... except for wisdom and warnings.',36753),(63030,1,0,0,0,0,0,0,0,'I have dire news, $n.',40000),(63031,0,0,0,0,0,0,0,0,'Ah yes, the dormant stygia throughout the Maw will sometimes coalesce into forms such as this.\n\nYou were wise to bring this to me, $c.',38134),(63032,1,0,0,0,0,0,0,0,'I have dire news, $n.',37176),(63033,1,0,0,0,0,0,0,0,'I have dire news, $n.',38134),(63034,669,0,0,0,0,0,0,0,'Why have you come to our realm, mortal?',39229),(63035,669,0,0,0,0,0,0,0,'Ah, another blade on our side! And you aren\'t even dead yet!',37176),(63036,1,0,0,0,0,0,0,0,'Welcome! What brings you to the Heart of the Forest?',40000),(63037,669,0,0,0,0,0,0,0,'And to what do I owe the pleasure of a mortal visiting Revendreth at such an...inopportune time?',37988),(63038,0,0,0,0,0,0,0,0,'Excellent, $p. I wondered what had become of that particular associate. \n\nIt pleases me to know that their demise was not a complete loss.',38134),(63039,0,0,0,0,0,0,0,0,'<The Ebon Blade monument radiates with energy from the fallen knights\' runeblades.\n\nIt is a small tribute to their sacrifice, but it will have to do.>',38134),(63040,0,0,0,0,0,0,0,0,'Excellent, $p. I wondered what had become of that particular associate. \n\nIt pleases me to know that their demise was not a complete loss.',38134),(63043,0,0,0,0,0,0,0,0,'<With the rending traps disabled, the souls here should stand a better chance of escaping their captors.\n\nThough they may never escape the Maw, at least they have a chance of escaping the grim fate of becoming a mindless shade.>',38134),(63045,0,0,0,0,0,0,0,0,'Quite the tale, $n. Few motivations are as potent as revenge.',38134),(63046,0,0,0,0,0,0,0,0,'Welcome. Together we shall thrive!',37988),(63047,0,0,0,0,0,0,0,0,'Chains? Not exactly hard to find around here... wait, those runes...\n\nYou have a keen eye, indeed. The magic here is worth further study.',38556),(63050,0,0,0,0,0,0,0,0,'Intriguing. I had often wondered what differentiated the Cauldron\'s protectors from the rest of the Mawsworn.\n\nI hope these weren\'t too difficult for you to procure.',38134),(63051,1,0,0,0,0,0,0,0,'Cartel Ve was asking you questions about me?\n\nI\'m flattered. Make sure you never tell them anything.\n\nEver.\n\nCome. There\'s work to do.',40000),(63054,2,0,0,0,0,0,0,0,'Well met, $n. Together, we will see our soldiers rule the battlefield.',37176),(63055,1,0,0,0,0,0,0,0,'It has been many eons since these portals have been active. It\'s most exciting!',37474),(63056,1,0,0,0,0,0,0,0,'A network of mirrors to translocate throughout the realm will prove invaluable.\n\nRumor suggests of the former mirror maker of the Master was lost in the Ember Ward rather recently. \n\nYou have proven to have a talent for convincing people to join our side.',36949),(63057,1,0,0,0,0,0,0,0,'Long have I waited to weave anima across Maldraxxus once more.',36753),(63058,669,669,0,0,0,0,0,0,'You fixed the stitching table? That\'s great! Soon we\'ll be able to build our own constructs!',36753),(63059,1,0,0,0,0,0,0,0,'With more work, we can establish portals to other necropoli around the Shadowlands.',36753),(63062,0,0,0,0,0,0,0,0,'You\'ve found my siphoner. You are just full of surprises, Maw Walker.\n\nThe unique way that pain and suffering manifests physically in the Maw is a mystery... one which this energy you\'ve collected may help unravel. \n\nWell done.',38556),(63064,1,0,0,0,0,0,0,0,'We have much to accomplish, and as resourceful as you are, you are not able to be in all places at once.',40443),(63065,1,0,0,0,0,0,0,0,'Come, come, my friend!\n\nIt is time... for a PARTY!',38134),(63066,1,0,0,0,0,0,0,0,'It is time to begin restoring anima to the Shadowlands.',36949),(63067,1,0,0,0,0,0,0,0,'We regrow with hope.',37474),(63069,0,0,0,0,0,0,0,0,'It would seem that Cartel Ve has not given up their pursuit of the Maw.\n\nYou did well to bring me this pathfinder\'s journal. Whatever the cartel has learned about this place will surely serve us better than it would a corpse.',38556),(63072,0,0,0,0,0,0,0,0,'Fascinating, the metal here seems to be fabricated entirely of stygia!\n\nThere is much I can do with this. Take this reward, with my thanks.',38556),(63073,1,0,0,0,0,0,0,0,'Hmmmmmmmmmmmmmmmmm. Normally we\'d been seeing some mushrooms sprouting by now.',37474),(63100,0,0,0,0,0,0,0,0,'<The hope of releasing these poor souls from their anguish washes over you.>',38134),(63132,1,0,0,0,0,0,0,0,'<Ve\'nari examines the writ.>\n\nQuite an interesting way to record one\'s secrets. This may prove a challenge to decipher.\n\nThank you for bringing this to me.',40593),(63133,1,0,0,0,0,0,0,0,'Ah, I have not seen these runes used in quite some time. An ancient broker method of encryption.\n\nThis will be useful should I ever intercept cartel communications.',40120),(63134,1,0,0,0,0,0,0,0,'Valuable information, indeed. This will help me avoid detection whenever I must leave the safety of the refuge.\n\nI trust you\'ve already committed the patrols to memory, Maw Walker.',36753),(63135,1,0,0,0,0,0,0,0,'This will help mitigate the Mawsworn\'s aerial advantage. Caution must still be exercised, of course.\n\nDo try to avoid their notice whenever possible. I would hate for one of them to follow you here.',42698),(63136,1,0,0,0,0,0,0,0,'Ah, yes. These were clearly written by someone in the grip of madness.\n\nThat is not to say that they are nonsense, however. Sometimes, only the insane can see the truth.',40593),(63137,1,0,0,0,0,0,0,0,'<Ve\'nari laughs as she appraises the cryptogram.>\n\nThis... is a children\'s toy. Brokers use them to teach their cartel\'s encryption methods.\n\nNot to say that this is worthless. Quite the contrary. In a place such of this, even a glimmer of mirth is valuable beyond measure.',40725),(63140,1,0,0,0,0,0,0,0,'<Ve\'nari glances over the manuscript.>\n\nThis is truly an ancient document. A pity it is in such poor condition. The secrets it holds must be priceless.',40120),(63145,1,0,0,0,0,0,0,0,'Quite the find, Maw Walker. Firsthand information from within Torghast is rare and valuable. None who set foot in the tower return to tell the tale.\n\nPresent company excluded, of course.',40725),(63152,1,0,0,0,0,0,0,0,'<Ve\'nari glances over the scroll, rotating it in various directions.>\n\nIt has been some time since I\'ve seen a method of encryption so intricate. But I suppose the venthyr are nothing if not ostentatious.\n\nWhatever the contents of this message might be, it is clear that its author wanted to keep it clandestine.',36949),(63153,1,0,0,0,0,0,0,0,'Ah, a rare bit of insight into the minds of the Maw\'s eternal tormentors.\n\nQuite fascinating... if a bit frightening.',36753),(63154,1,0,0,0,0,0,0,0,'An interesting artifact indeed, Maw Walker.\n\n<Ve\'nari gently taps the armor.>\n\nYou can almost hear the screams of the souls who were consumed to forge it.',37474),(63155,1,0,0,0,0,0,0,0,'<Ve\'nari raises the map, inspecting it closely.>\n\nAnd these stains--you said they were here when you found it?',36753),(63156,1,0,0,0,0,0,0,0,'<Ve\'nari snatches the shackles from your hands.>\n\nRather dangerous for a mortal such as yourself to be carrying these around.\n\n<Ve\'nari lifts and lowers the shackles slowly, as if to determine the weight.>\n\nThough I must admit... these could prove useful.',40443),(63157,1,0,0,0,0,0,0,0,'How soothing.\n\n<Ve\'nari takes a closer look at the item in her hands.>\n\nI wonder...\n\n<Ve\'nari presses a diamond shaped etching on the side of the box. It clicks into place, then opens to reveal a secret compartment containing a small piece of rolled up parchment.>\n\nNothing is what it seems, Maw Walker.',36753),(63158,1,0,0,0,0,0,0,0,'An intriguing piece of currency.\n\nI would be most interested to learn how it was minted...',36949),(63160,1,0,0,0,0,0,0,0,'I believe I have seen the creatures described in these pages before. \n\nFrom afar, of course. Always from afar.',36753),(63161,1,0,0,0,0,0,0,0,'Ah, yes. This will make for a fascinating study.',36753),(63162,1,0,0,0,0,0,0,0,'Despite how long I have been here, there is still much about the creatures of the Maw that remains unknown to me.\n\nSometimes I have to wonder if it is better that way.',36753),(63163,1,0,0,0,0,0,0,0,'Quite the vivid description.\n\nI suggest you consider this a reminder of what will happen should you fail in your efforts against the Jailer.',36753),(63164,1,0,0,0,0,0,0,0,'Well done, Maw Walker. These will allow us to better anticipate the enemy\'s actions.',36753),(63166,0,0,0,0,0,0,0,0,'You have... saved these souls from a terrible fate.\n\nEven a... true end... cannot be worse than this torment...',38134),(63179,0,0,0,0,0,0,0,0,'We are in your debt, Maw Walker.\n\nI don\'t know if we will ever escape this place, but you have at least bought us a chance to strike back at our foes.',38134),(63206,1,0,0,0,0,0,0,0,'Satisfying, is it not?\n\nThe fewer Mawsworn to rise into the Jailer\'s ranks, the better for our continued existence.',39289),(63208,1,0,0,0,0,0,0,0,'A wise decision. See to it that they receive your aid swiftly.',36949),(63212,669,0,0,0,0,0,0,0,'I knew you would return.',40120),(63340,1,0,0,0,0,0,0,0,'Ah, $n. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo\'dash is authorized to further upgrade your armor and weapons.',38134),(63341,1,0,0,0,0,0,0,0,'I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo\'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.',38134),(63342,1,0,0,0,0,0,0,0,'Ah, $n. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo\'dash is authorized to further upgrade your armor and weapons.',36839),(63343,1,0,0,0,0,0,0,0,'I see your skills in combat have improved even further. I trust you have made good use of our previous offer? \n\nZo\'dash is now instructed to offer the full suite of his services to you. I look forward to seeing their impact on your performance.',37176),(63455,1,0,0,0,0,0,0,0,'Excellent, $p. Your efforts have bolstered our forces!',41031),(63545,1,0,0,0,0,0,0,0,'These parts are more than enough to build a new Centurion!',40593),(63576,0,0,0,0,0,0,0,0,'Anduin... now the Jailer\'s pawn...\n\nWe must take immediate action, $n. It is time for the covenants to convene.',43340),(63578,0,0,0,0,0,0,0,0,'We just barely survived that! I definitely didn\'t expect THAT to happen.\n\nBut it\'s not over. We can\'t let our guard down!',43340),(63594,0,0,0,0,0,0,0,0,'The defenses are broken! Most excellent, Maw Walker.',40593),(63603,1,0,0,0,0,0,0,0,'Ah, the yak. This shape is now yours to call upon.',42979),(63610,1,0,0,0,0,0,0,0,'Ah, the mammoth. This shape is now yours to call upon.',41079),(63621,669,0,0,0,0,0,0,0,'I knew we could count upon you, $n.',41079),(63625,669,0,0,0,0,0,0,0,'Victory will be ours, Maw Walker!',41031),(63638,0,0,0,0,0,0,0,0,'Ardenweald depends on the cycle. Without these spirits, what purpose would there be?\n\nI could not let the Jailer\'s forces destroy what we have fought so hard to protect.',43340),(63639,0,0,0,0,0,0,0,0,'The Jailer has begun his attack on Oribos.\n\nWhat I have feared the most has come to pass.',43340),(63660,0,0,0,0,0,0,0,0,'I do not do this lightly, Maw Walker, but we have no choice.\n\nWe must open a gateway to the Maw.',43340),(63661,1,0,0,0,0,0,0,0,'Normally, I would consider your request bothersome and insulting.\n\nBut recent events have led me to believe that your proposal may prove beneficial to both of us.',43340),(63662,1,1,0,0,0,0,0,0,'The Jailer desperately wants something here, yet his precious Eye cannot breach its defenses.\n\nOh well. Shall we?',43340),(63663,0,0,0,0,0,0,0,0,'I must find out more about you, Maw Walker.',43340),(63664,669,0,0,0,0,0,0,0,'Victory will be ours, Maw Walker!',42010),(63665,1,0,0,0,0,0,0,0,'Well done, $n. I am eager to learn of this realm pulled into the Maw.\n\nIt is time to begin our assault on the Jailer\'s forces.',43340),(63669,1,0,0,0,0,0,0,0,'Victory will be ours, Maw Walker!',41031),(63703,1,0,0,0,0,0,0,0,'We have our smith. Now we must move forward with the plan.',39335),(63704,1,0,0,0,0,0,0,0,'Vengeance will not bring back the fallen, but it gives those of us who survived a measure of satisfaction.',39335),(63705,1,0,0,0,0,0,0,0,'I am relieved to see more of my people freed from the Jailer\'s grasp.\n\nNow we must determine what he\'s looking for.',39335),(63706,1,0,0,0,0,0,0,0,'After the drought the Shadowlands suffered, I\'ll never take flowing anima for granted again.',39335),(63709,1,0,0,0,0,0,0,0,'We know what the Jailer wants.\n\nNow we must reach the vault before his forces acquire it.',39335),(63710,5,0,0,0,0,0,0,0,'A chasm!\n\nWe will need a way to get across to the next anima conduit.',39335),(63711,1,0,0,0,0,0,0,0,'Yes, this will do. Think I\'ll save one to show the other smiths back home.',39335),(63712,1,0,0,0,0,0,0,0,'Excellent. I should be able to extract the Primus\'s message from these records.',39335),(63713,1,0,0,0,0,0,0,0,'What a ride! Keep that hookshot.\n\nJust be careful using it. That thing will chew through any normal grapple points.',39335),(63714,1,0,0,0,0,0,0,0,'Tal-Galan informed me of the situation.\n\nWe must get you into that vault.',39335),(63717,669,0,0,0,0,0,0,0,'Good work fighting those Mawsworn.\n\nWe\'ll take it from here, $n.',39335),(63722,1,0,0,0,0,0,0,0,'A pity all three keepers did not survive. Good work tracking down the two that did.',39335),(63725,1,0,0,0,0,0,0,0,'The Primus\'s sigil! Hmm... I sense a familiar magic upon it.\n\nYes. All those things I saw through your eyes from Torghast...',39335),(63726,669,0,0,0,0,0,0,0,'We are free. There is still hope to fight back against Zovaal.',39335),(63727,0,0,0,0,0,0,0,0,'We can dwell on our past mistakes when this is over. For now, we must move forward.\n\nYou aided me during my imprisonment as the Runecarver. Take this as a token of my gratitude.',39335),(63731,0,0,0,0,0,0,0,0,'Relics? Research? We have much more urgent matters at hand!',39229),(63732,1,0,0,0,0,0,0,0,'What did we do to deserve such cruelty?',39229),(63733,1,0,0,0,0,0,0,0,'You bought us the moment we needed to make our escape.',39229),(63734,1,0,0,0,0,0,0,0,'I cannot fully describe the relief I feel now that we have the Lodestaff.',39229),(63736,1,0,0,0,0,0,0,0,'The Lodestaff is humming with vibrant energy! The anima worked better than I could have hoped.',39229),(63737,1,0,0,0,0,0,0,0,'So much has been taken from us. And yet, due to Roh-Senara\'s sacrifice, there is hope.',39229),(63738,1,0,0,0,0,0,0,0,'It is hard to imagine how I will continue without the Archivist.',39229),(63739,1,0,0,0,0,0,0,0,'I was beginning to worry that you had given up on our cause.',39229),(63740,1,0,0,0,0,0,0,0,'I trust you and Scholar Roh-Suir learned from the Archivists.',39229),(63753,1,0,0,0,0,0,0,0,'Quite extraordinary work Maw Walker!',41031),(63754,0,0,0,0,0,0,0,0,'I will tell the tale of your noble deeds, $n. Your actions this day will be remembered.',43345),(63755,6,1,0,0,0,3000,0,0,'You are searching for the Fatescribe too? I must find him. I cannot fail.',39229),(63756,378,274,0,0,0,7000,0,0,'I struggle to believe that not a single attendant has any information on where the Fatescribe might be.',39229),(63757,5,378,0,0,0,0,0,0,'Now this is special. This implement is used by the Fatescribe in his work.',39229),(63758,378,274,5,0,0,2000,4000,0,'Mad ramblings and incense. Weak clues, but they\'re all we have.\n\nWe need to search the Sanctuary of Guidance.',39229),(63759,412,378,0,0,0,4000,0,0,'$p! At last! \n\nYou know that I cannot do this without you.',39229),(63760,378,11,0,0,0,5000,0,0,'Using an illusion to hide.\n\nCan you imagine anything so clever?',39229),(63761,0,0,0,0,0,0,0,0,'<You have completed the protector\'s task.>',39229),(63762,0,0,0,0,0,0,0,0,'<The Fatescribe has been taken.>',39229),(63763,5,378,0,0,0,1000,0,0,'News of the nathrezim infiltrating Korthia is deeply troubling.\n\nHow long have they been here? What is their goal?',39229),(63764,1,0,0,0,0,0,0,0,'Welcome to Skyhold, $n.',43345),(63771,1,1,0,0,0,0,0,0,'You return, mortal.\n\nDo you wish to change your fate?',43971),(63772,669,0,0,0,0,0,0,0,'Your presence here gives us renewed hope.',41031),(63773,669,0,0,0,0,0,0,0,'Victory will be ours, Maw Walker!',41079),(63774,1,0,0,0,0,0,0,0,'The work of a Maldraxxian soldier is never complete!',42010),(63775,0,0,0,0,0,0,0,0,'I am deeply grateful for your service in keeping our secrets from the Jailer.',39335),(63778,0,0,0,0,0,0,0,0,'Thank you, my friend.\n\nEvery bit of anima we collect gives me hope that we can heal the Shadowlands. One day, we will be whole again.',41079),(63779,0,0,0,0,0,0,0,0,'How wonderful. We will return these to the attendants so they may once again participate in their rituals. It\'s important to do activities that bring us peace.',39653),(63780,0,0,0,0,0,0,0,0,'So many emblems! That makes me so happy.\n\nEverything will be better when we\'ve gotten the Jailer himself, but this will do nicely for now.\n\nThank you!',41079),(63781,11,0,0,0,0,0,0,0,'Again, you survive. You remind me of me. I will review these plans and inform our companions.',42010),(63782,0,0,0,0,0,0,0,0,'The information contained in these is dangerous and vile. But knowing what our enemy can do helps us protect against it.',41079),(63783,0,0,0,0,0,0,0,0,'You can trust me with this anima. I will see it is turned against the Jailer and his forces.',41079),(63784,0,0,0,0,0,0,0,0,'Look at \'em! Drab little buns. They jus\' blend in ta the wood work. That\'s stinkin\' useful innit?',41488),(63787,0,0,0,0,0,0,0,0,'The tactical advantage we now hold is a huge win against the Jailer\'s Forces. Well done, $p.',41079),(63788,0,0,0,0,0,0,0,0,'Thank you, Maw Walker. I am sure the attendants will feel great relief and joy at being able to return to their holy place.',39497),(63789,0,0,0,0,0,0,0,0,'You have performed admirably in this task, Maw Walker. We thank you for your aid.',41488),(63790,0,0,0,0,0,0,0,0,'Thanks to you, Lord Azzorak will no longer hinder Cartel Xy here in Korthia. \n\nYou have my personal thanks as well, Maw Walker. I see many great things in our future.\n\nPlease accept this reward as a token of our gratitude.',41359),(63791,0,0,0,0,0,0,0,0,'Thanks to you, Valdinar the Curseborn will no longer hinder Cartel Xy here in Korthia. \n\nYou have my personal thanks as well, Maw Walker. I see many great things in our future.\n\nPlease accept this reward as a token of our gratitude.',41079),(63793,0,0,0,0,0,0,0,0,'Thanks to you, Ensydius the Defiler will no longer hinder Cartel Xy here in Korthia. \n\nYou have my personal thanks as well, Maw Walker. I see many great things in our future.\n\nPlease accept this reward as a token of our gratitude.',39653),(63794,0,0,0,0,0,0,0,0,'<Ta\'nasi holds the sample up to the sky.>\n\nAn excellent specimen. This will do nicely.\n\nAs promised, here is your reward in trade.',41793),(63810,1,0,0,0,0,0,0,0,'My heart rejoices to see a noble face in this realm of nightmare.',39229),(63811,0,0,0,0,0,0,0,0,'Helya has gone too far!',43345),(63827,669,0,0,0,0,0,0,0,'You have done much to help our forces. Thank you,$n.',40725),(63828,5,0,0,0,0,0,0,0,'The Jailer\'s forces are unending and our numbers few, but with your help we shall succeed!',40725),(63829,669,0,0,0,0,0,0,0,'Your actions show the purity of your soul. Artemede and I would fight along side you any day, Maw Walker.',39653),(63831,0,0,0,0,0,0,0,0,'This is well made, $n.\n\nOf course, every great horn has a name. It is our tradition!',43345),(63833,1,0,0,0,0,0,0,0,'We may not see an end to the Jailer\'s forces now, but all things must eventually end.\n\nEven evil.',41079),(63834,0,0,0,0,0,0,0,0,'Few weapons are intrinsically good or evil. That burden lies with those who wield them.',41488),(63835,0,0,0,0,0,0,0,0,'Ha! I presume the Jailer had never considering planning for a party herald\'s attack.',41079),(63836,0,0,0,0,0,0,0,0,'You also joined Fangcrack\'s fan club? So did Lady Moonberry.\n\n<Prince Renathal thinks for a moment.>\n\nPerhaps I should reconsider my earlier rejection of Rendle\'s invitation to join...',41488),(63837,0,0,0,0,0,0,0,0,'Tubbins promised to save me a cup for our victory celebration at the Ember Court!',41488),(63838,0,0,0,0,0,0,0,0,'Nadjia single-handedly held off an entire platoon of Mawsworn while the dredgers established our base.\n\nEven General Draven was impressed.',40725),(63839,1,0,0,0,0,0,0,0,'Even in the depths of the Maw, the Accuser remains focused on saving any soul she can...\n\nHer devotion to Revendreth\'s true purpose continues to inspire me.',41079),(63840,0,0,0,0,0,0,0,0,'I will keep the gorm restrained here until they are needed.',39289),(63841,0,0,0,0,0,0,0,0,'Thank you, $p. Our biggun dredgers are critical to troop movement in the area.',41079),(63842,0,0,0,0,0,0,0,0,'Let it not be said that it was ever boring while Lady Moonberry was present.',41488),(63843,669,0,0,0,0,0,0,0,'There is great sorrow in this victory, but it had to be done.',40593),(63844,0,0,0,0,0,0,0,0,'Well fought. Kolfinna, Dryfinna, and Aeskir have risen to the challenge and await you in Odyn\'s hall.',43345),(63845,0,0,0,0,0,0,0,0,'It is done. Danica and her sisters are infused with my power and wield my wrath.',43345),(63846,1,0,0,0,0,0,0,0,'Charred shards! These will make some very fine mirrors.',40725),(63848,1,0,0,0,0,0,0,0,'A thank-you is polite.\n\nA favor is better.',39229),(63849,1,0,0,0,0,0,0,0,'Perfect. Their secrets will soon be mine.\n\nPardon me. I meant to say \"ours.\"',39229),(63853,0,0,0,0,0,0,0,0,'A sweet reprieve from that creature\'s dreadful glare.',39653),(63855,1,0,0,0,0,0,0,0,'A worthwhile trip that has opened so many possibilities.\n\n<Ve\'nari digs through the heavy bag and pulls out a few unusual objects.>',39229),(63856,0,0,0,0,0,0,0,0,'<Bolvar stares in wonder at the sight before him.>',43340),(63857,0,0,0,0,0,0,0,0,'The Winter Queen must be the Jailer\'s next target.\n\nWe must do all we can to protect her.\n\nAnd I have a few ideas how we can do that...',43340),(63858,669,0,0,0,0,0,0,0,'You display the greatest of courage.',40593),(63859,669,0,0,0,0,0,0,0,'The sounds of those bells strengthens our hearts and gives us the might to win this battle.',41031),(63860,1,0,0,0,0,0,0,0,'Where... where did you find this?\n\n<The Archivist brings the talisman closer for inspection.>\n\n I haven\'t seen this in eons. I thought it had been lost.',39229),(63861,1,0,0,0,0,0,0,0,'Yes, yes. This is it. Magnificent, don\'t you agree?\n\n<The damp codex catches The Archivist by surprise. He gently runs his hand along the binding, muttering an incantation in a soft, enigmatic tone.>\n\nThat should help preserve it for now, but the incantation won\'t last. We must get to work.',39229),(63863,669,0,0,0,0,0,0,0,'You display the greatest of courage.',39653),(63864,0,0,0,0,0,0,0,0,'Please tell me you did not drink any of that dreadful brew. We deserve only the finest blends for all our efforts here.',40593),(63867,1,0,0,0,0,0,0,0,'The instrument\'s voice will not be pleasing to most ears, but I believe it will serve its purpose.',43345),(63892,1,1,1,-1,0,500,1000,0,'You have acquired a complete set of Diviner\'s Rune Chits!\n\nThis was one of the first relics that I studied as an acolyte scholar. If you cast the chits, the resulting scatter and orientation will answer any question you ask of them, though it takes experience and a good deal of intuition to interpret their meaning.\n\nI never expected to see a complete set again.',39282),(63895,0,0,0,0,0,0,0,0,'This projector is certainly useful. A safe landing, I perceive.',39229),(63896,1,0,0,0,0,0,0,0,'The magnitude of the grief you have collected will bind the instrument to the Maw.',43345),(63899,1,1,1,-1,0,500,1000,0,'Scholars at the Seeker\'s Quorum were researching this tome.\n\nIt appears as though it was a fellow scholar, not mawsworn or wildlife, that tore it apart. This is troubling. \n\nFor our safety, I will stitch all but one missing page back into the binding before I add this to the archive. Until we know more about this relic, we cannot risk restoring it entirely.',39229),(63901,1,0,0,0,0,0,0,0,'Songs will immortalize the deeds of this day, $n.',43345),(63902,1,0,0,0,0,0,0,0,'The Eye defeated? Good news indeed.',43345),(63903,1,1,0,0,0,0,0,0,'The Jailer has what he wanted... along with Anduin at his side.\n\nOur only victory--if you can call it that--is that we have Sylvanas in custody.\n\nI pray she possesses knowledge that can give us an edge to stop whatever the Jailer is planning next.',41079),(63904,0,0,0,0,0,0,0,0,'Our best efforts were still in vain.\n\nOur enemy\'s plan edges closer to fruition.',43340),(63909,1,1,1,-1,0,500,1000,0,'Now this is quite a find!\n\nThe Guise of the Changeling has the power to convincingly modify the appearance of its bearer, but it has a mind of its own. The wearer cannot control the illusion, and the mask is wont to place them into embarrassing or dangerous situations.',39229),(63910,1,1,1,-1,0,500,1000,0,'When we scholars consider relics that are important to keep secured, the Netherstar is precisely the type of relic that we have in mind. Can you imagine how much damage could be done were this to fall into the hands of an... opportunist?',39229),(63911,1,1,1,-1,0,500,1000,0,'In all of my years as a researcher, I never would have expected this.',39229),(63912,1,1,1,-1,0,500,1000,0,'Aha! You have recovered the Celestial Shadowlands Chart.\n\nWith the chart and the data you collected, it can be restored to its fully functional form. It will take some time to analyze and interpret the results, which I can get started on now that the relic has been returned to the Archive.\n\nAllow me a moment to find a good spot for it...',39229),(63914,1,1,1,-1,0,500,1000,0,'My stars! To comprehend any of these languages would allow one the insight to translate all of them. We must look into this further.',41079),(63915,1,1,1,-1,0,500,1000,0,'I could hear you approaching with this drum before I saw you. And strangely, I though someone else might be with you.',39229),(63916,1,1,1,-1,0,500,1000,0,'This soil can grow any type of plant, anywhere.\n\nNot the most dangerous relic missing from the archive, and yet it could be the most useful. With enough time, one could restore the verdant beauty of Korthia.',39229),(63917,1,1,1,-1,0,500,1000,0,'I trust you did not listen to anything that this little monster told you.\n\nIt is absolutely incapable of uttering the truth.',39229),(63918,1,1,1,-1,0,500,1000,0,'We must be cautious around this obelisk.\n\nMore than one attendant was driven mad while researching the relic.',39229),(63919,1,1,1,-1,0,500,1000,0,'This appears to be a companion tome to the crimson book that was under the care of scholars in the Seeker\'s Quorum.\n\nKnowing that this book binding was separated from its pages intentionally, I will stitch all but one azure page back into it before returning it to the archive.',39229),(63920,1,1,1,-1,0,500,1000,0,'Though I have only a passing understanding of its operation, this relic can strip the complexity of communication into a form that is free from subtlety, guile, or metaphor. Pure logic.',41079),(63921,1,1,1,-1,0,500,1000,0,'I am curious to learn how this strange ring functions.',39229),(63924,1,1,1,-1,0,500,1000,0,'Some mote of Gorak Tul yet lives within this fetish. His corruption is barely contained.',39229),(63934,0,0,0,0,0,0,0,0,'These are the messages that were stolen! I commend you on recovering them.\n\nOh, there appears to be at least one extra...',41359),(63935,0,0,0,0,0,0,0,0,'Precious anima that will be shared. A sacrifice, honored.',41359),(63936,0,0,0,0,0,0,0,0,'Thank you! Wow... you can\'t tell this was inside devourer!\n\nSika will get anima to those most in need.',41359),(63944,1,0,0,0,0,0,0,0,'Ah, yes. Your anima is rather familiar.\n\nWe were wondering when you would arrive.',40725),(63945,1,0,0,0,0,0,0,0,'<Bonesmith Heirmir takes her runeblade back from you and examines it carefully.>\n\nNot bad, $p. Always room for improvement... but not bad.',40944),(63949,1,0,0,0,0,0,0,0,'The threads of fate weave through you, Maw Walker.\n\nJust as the prophecies foretold.',42698),(63950,0,0,0,0,0,0,0,0,'These talons are in excellent shape. And they look like they could take out an eye! <Herne chuckles ironically.>\n\nI expect they will get a lot of attention from our Wild Hunt recruits.\n\nThank you, Maw Walker.',39497),(63951,1,0,0,0,0,0,0,0,'Excellent work Maw Walker.',41359),(63952,1,0,0,0,0,0,0,0,'<Margrave Sin\'dane looks impressed... or annoyed... or disgusted... or concerned?>\n\nHm. I suppose with enough hands, anything IS possible...',42010),(63954,0,0,0,0,0,0,0,0,'Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.',39335),(63955,0,0,0,0,0,0,0,0,'Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.',39497),(63956,0,0,0,0,0,0,0,0,'Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.',41488),(63957,0,0,0,0,0,0,0,0,'The name \"Seeker\'s Quorum\" has puzzled me greatly since I learned of it. What are they seeking? What constitutes a Quorum? What did they do there?\n\nThese mysteries may be beyond us, or they may yet be revealed. And here is your reward, as promised.',41079),(63958,0,0,0,0,0,0,0,0,'The Vault is reason why the Jailer targeted Korthia with his chains. Many secrets of the Shadowlands are archived there.\n\nIf we can just get a glimpse of how it works and what it holds, that information would be most valuable indeed.\n\nAnd here is your reward, as promised.',39335),(63961,0,0,0,0,0,0,0,0,'Wonderful! You brought everything that I asked for.\n\nAgain, do not worry about the contents of these boxes. They pose no threat to you.\n\nHere is the reward I promised.',41488),(63962,0,0,0,0,0,0,0,0,'Excellent, this data will serve us well. We can begin to answer some of our questions about Korthia, and the Mauler\'s Outlook. Was it always home to such terrible creatures, or did was it something more?\n\nAnd here is your reward, as promised',39318),(63963,0,0,0,0,0,0,0,0,'<Ta\'nasi tugs at the spiked hide to test its strength.>\n\nAn excellent specimen. This will do nicely.\n\nAnd as promised, here is your reward in trade.',39427),(63964,0,0,0,0,0,0,0,0,'<Ta\'nasi knocks the sturdy beak against her palm, listening to the sound.>\n\nAn excellent specimen. This will do nicely.\n\nAnd as promised, here is your reward in trade.',42010),(63965,0,0,0,0,0,0,0,0,'Look at these wonderful eggs! I can hear their heartbeats.\n\nThis is the start of something beautiful, I just know it.',41488),(63968,1,0,0,0,0,0,0,0,'The hunt is not yet complete, but you have earned your place in the records of its victory.',41359),(63969,1,0,0,0,0,0,0,0,'We will discover the source of this darkness, and end it.',40944),(63970,1,0,0,0,0,0,0,0,'Thank you, $p. We must not forget to help one another as we stride deeper into the darkness.',40944),(63971,1,0,0,0,0,0,0,0,'<Lord Herne grins.> My record was squishing four in a single jump.\n\nOne of the many benefits of being a quadruped.',40593),(63972,1,0,0,0,0,0,0,0,'I have received many reports from hunters who were aided by Krrprripripkraak and her friends. Thank you for helping them.',42010),(63973,1,0,0,0,0,0,0,0,'No matter how strong we become, we are stronger when we hunt together.',40944),(63974,1,0,0,0,0,0,0,0,'I wish I could\'ve been there to see it myself!\n\nA fitting end for the Heralds...',42010),(63980,1,0,0,0,0,0,0,0,'You seek information?\n\nThat requires a transaction.',39335),(63982,6,0,0,0,0,0,0,0,'Need something hunted down?',39335),(63983,1,0,0,0,0,0,0,0,'Perfect! This will put us back on schedule.',39335),(63984,1,0,0,0,0,0,0,0,'Maw Walker! What can humble Ta\'meri do for you?',39335),(63985,1,0,0,0,0,0,0,0,'No worries! I have another plan.',39335),(63986,0,0,0,0,0,0,0,0,'<So\'leah has been defeated. Now, for the artifact she was using...>',42979),(63989,0,0,0,0,0,0,0,0,'How did Plaguey do? Is he as viral as we\'d hoped?',39497),(63994,0,0,0,0,0,0,0,0,'Maw Walker. We must summon the others.',43340),(64007,1,0,0,0,0,0,0,0,'The Maw...\n\nNow our true work begins.',43340),(64014,1,0,0,0,0,0,0,0,'That\'s quite an instrument you have there.\n\nIt seems the golden feathers were worth following, Maw Walker. You owe me yet again.',43345),(64016,0,0,0,0,0,0,0,0,'How did the tests go? OH! Ooz! You\'re huge! You\'re even more beautiful than normal!',39427),(64017,0,0,0,0,0,0,0,0,'How did the tests go? OH! Look at all of them! They\'re so cute!',40000),(64043,0,0,0,0,0,0,0,0,'That got them back on their feet!\n\nAny little bit helps to keep us in the fight.',41359),(64065,0,0,0,0,0,0,0,0,'This needle is so long and perfect! Well done apprentice. I can\'t wait to get started on our new tests!',39497),(64070,0,0,0,0,0,0,0,0,'Well, it\'s not the finest materials, but it will do.',41079),(64089,0,0,0,0,0,0,0,0,'Oh my! I\'ve never even seen most of these herbs. Hum, this black one looks a bit dangerous. This green one seems promising. Well done $p!',41793),(64101,0,0,0,0,0,0,0,0,'There\'s so much anima here. This will be very useful in helping the attendants rebuild. Thank you.',41359),(64104,0,0,0,0,0,0,0,0,'You were able to feed some of them? Wonderful!\n\nI\'ll start saving up more food for next time. I hope that one day we can help this place heal, too.',41488),(64106,1,0,0,0,0,0,0,0,'Do not relent, $n. This is only the first of many battles to come.',40120),(64129,0,0,0,0,0,0,0,0,'You and Aldermeigh make a great team! Thank you for taking him out and dispatching so many Mawsworn.\n\nOne day, I too will ride with the Wild Hunt, and we will right many wrongs.',41079),(64166,0,0,0,0,0,0,0,0,'Thank you, $n. I\'ll make sure these memories are taken care of. \n\nI wonder what it would have been like, being here as one of them...',39653),(64174,1,4,0,0,0,300,0,0,'Well now I need to put this platter to use. \'Ow about I serves you?',43345),(64175,1,4,0,0,0,300,0,0,'Do your colleagues require aid? I am sure I can be of some use.',43345),(64194,0,0,0,0,0,0,0,0,'Ha! Perfect victory. Atleos returns, and you do too.',41359),(64210,0,0,0,0,0,0,0,0,'Ah... a curious device. Anchoring it in this place will prove useful.',40000),(64216,0,0,0,0,0,0,0,0,'<The box hungers, reaching into your memories of Torghast for past deeds to feed upon.>',40000),(64218,669,0,0,0,0,0,0,0,'Someone inside needs our help!',43345),(64219,0,0,0,0,0,0,0,0,'We were too late... but we must not give up hope.',43345),(64223,669,0,0,0,0,0,0,0,'That was unhelpful...',43345),(64224,669,0,0,0,0,0,0,0,'The elders refuse to say anything about Firim.\n\nI hope you were able to learn something.',43345),(64225,669,0,0,0,0,0,0,0,'Those assassins are after more than just my life. They wish to steal my research! I cannot let them have it.',43345),(64226,669,0,0,0,0,0,0,0,'Good. That should shield us from notice for a while.',43345),(64227,669,0,0,0,0,0,0,0,'I suppose you have proven to be useful. Thank you.',43345),(64228,669,0,0,0,0,0,0,0,'Astounding!',43345),(64230,669,0,0,0,0,0,0,0,'Can\'t you feel the knowledge you\'ve gained coursing through you?!\n\nTo think it is you who will unlock the secrets of Zereth Mortis...\n\nI will be watching you very closely.',43345),(64267,1,66,0,0,0,0,0,0,'I\'m impressed by your sheer tenacity to survive while remaining somewhat useful, Maw Walker. You remind me of myself when I was much younger and naive. \n\nTake this and continue your work... somewhere less conspicuous.',39427),(64271,0,0,0,0,0,0,0,0,'Your form still needs work. Thank you, for taking time out of our unending campaign to duel. We must remember, even in times of great struggle, to do things that bring us joy.',42010),(64289,1,0,0,0,0,0,0,0,'These will do nicely. There is much I can do to improve them.',39229),(64290,1,0,0,0,0,0,0,0,'This should do nicely. The reliquary will improve with more research.',39229),(64292,0,0,0,0,0,0,0,0,'Take care of Maelie, Maw Walker.',42010),(64322,1,0,0,0,0,0,0,0,'Ah, $n. I have heard many stories of your prowess on the battlefield. \n\nI have interest in keeping great combatants like yourself well equipped. Zo\'dash is authorized to further upgrade your armor and weapons.',39318),(64368,0,0,0,0,0,0,0,0,'Your work in restoring the reliquary has been invaluable.\n\nI\'ve uncovered new methods to find relics. Hopefully they will help you.',39335),(64430,0,0,0,0,0,0,0,0,'Ah, you\'ve all returned safely. Wonderful!',41793),(64432,0,0,0,0,0,0,0,0,'I told you it would be fine. How did the test go? I wish I could have seen the looks on their faces when their fancy armor was suddenly the reason they were being destroyed.',41079),(64438,1,0,0,0,0,0,0,0,'This is the least we can do to help you in your efforts, Maw Walker.',39229),(64506,1,0,0,0,0,0,0,0,'These are just some of the relics that are missing.\n\nYou have the power to recover them, wherever they are within Korthia.',39229),(64511,1,0,0,0,0,0,0,0,'Please, do what you can to find these relics. We must not let this knowledge fall to ruin.',39229),(64513,1,0,0,0,0,0,0,0,'Is that what I think it is...?',39289),(64519,1,0,0,0,0,0,0,0,'Thank you for your continued aid. The reliquary will be restored, thanks to your diligent work.',39229),(64522,1,0,0,0,0,0,0,0,'<Duchess Mynx looks at you incredulously.>\n\nYou found these WHERE?!\n\nWell, how am I supposed to stop thieves I cannot even see? Cowardly shades!',39653),(64526,1,0,0,0,0,0,0,0,'Thank you for your continued aid. The reliquary will be restored, thanks to your diligent work.',39335),(64541,0,0,0,0,0,0,0,0,'With so many more interlopers in the Maw I need to secure my Stygia supply. Your efforts to keep me supplied will not go unnoticed and you always know where to find me.',39229),(64555,0,0,0,0,0,0,0,0,'Most of this information is useful. My thanks, Maw Walker.',43340),(64556,1,0,0,0,0,0,0,0,'This work brings us one step closer to ending Zovaal\'s reign over this forsaken land.',39229),(64557,1,0,0,0,0,0,0,0,'Step no closer! Reveal yourself!',40000),(64560,0,0,0,0,0,0,0,0,'You can trust me with this anima. I will see it is turned against the Jailer and his forces.',39229),(64561,0,0,0,0,0,0,0,0,'Places like the Aerie and Estuary must have been desolate, even before all the destruction. What interesting creatures congregate there.\n\nWill they all survive these changes, or will some adapt, and become even more fearsome?\n\nAnd here is your reward, as promised.',39229),(64562,0,0,0,0,0,0,0,0,'That got them back on their feet!\n\nAny little bit helps to keep us in the fight.',39229),(64579,1,0,0,0,0,0,0,0,'Excellent work, $n. These resources will bolster our efforts here.',42698),(64581,0,0,0,0,0,0,0,0,'This present looks like it has been shaken a few times. The tag on it reads:$b$bTo a very special $r $c.',41488),(64639,0,0,0,0,0,0,0,0,'A small tag on this present reads:$b$bHappy holidays, $n!',41488),(64641,1,0,0,0,0,0,0,0,'We are Circle Koh of the jiro.\n\nWe are here to fix this land.',42560),(64642,1,0,0,0,0,0,0,0,'This is a good start.',42698),(64643,1,0,0,0,0,0,0,0,'This will work.',42698),(64650,1,0,0,0,0,0,0,0,'Ah, the hyena. This shape is now yours to call upon.',39335),(64706,1,0,0,0,0,0,0,0,'Well done, mortal! Soon we shall see the results of your efforts.',44908),(64709,1,0,0,0,0,0,0,0,'Ah, $n, you have returned. An otherworldly air hangs heavy about you.',43206),(64710,1,1,273,0,0,300,300,0,'I will just put this back when it belongs. Thank you for bringing it to me, $n.',41359),(64713,1,0,0,0,0,0,0,0,'Enough to fix a small orb. This will do.',42538),(64717,1,0,0,0,0,0,0,0,'I shall make use of these immediately. These will help Saezurah and the automa resist the effects of the domination magic.',42698),(64718,1,0,0,0,0,0,0,0,'The chorus gathers. Soon, our voices will merge.',44908),(64720,1,0,0,0,0,0,0,0,'Perfectly executed, $n. The loss of those Oracles should keep the Mawsworn in the dark.',44908),(64722,1,0,0,0,0,0,0,0,'By the First Ones... I never dreamed I would see this place with my own eyes.',44908),(64723,1,0,0,0,0,0,0,0,'The covenants are certain to send aid if we ask.',44908),(64725,1,0,0,0,0,0,0,0,'The golden hour of silence. A space for creation to begin.',44908),(64726,1,0,0,0,0,0,0,0,'A breath held--anticipation. Soon, the soul will merge, and the song of creation will begin.',44908),(64727,1,0,0,0,0,0,0,0,'Our voices are muffled in the lingering dark.',44908),(64728,1,0,0,0,0,0,0,0,'Dissonance lingers. A pure tone is needed. Reset the cycle anew.',44908),(64729,1,0,0,0,0,0,0,0,'I can hardly believe all we\'ve accomplished... truly, this is a day worth remembering. We could not have achieved this without you, my friend.',44908),(64730,1,0,0,0,0,0,0,0,'I do not wish to say it but... it seems we have failed, my friend.',44908),(64731,1,0,0,0,0,0,0,0,'A new voice added to the chorus -- the cycle continues ever onward.',44908),(64733,1,0,0,0,0,0,0,0,'Between the strength of the covenant forces and the help of the automa, we should be able to reach the Crypts!',44908),(64741,669,0,0,0,0,0,0,0,'I knew it. Cartel Xy has been meddling with Haven\'s defenses!',42423),(64742,669,0,0,0,0,0,0,0,'Cartel Xy is nearby.',42423),(64743,669,0,0,0,0,0,0,0,'Oh, they thought they could hide their plans with a code? Hold on, my friend, this should take just a moment...',42423),(64744,669,0,0,0,0,0,0,0,'Their deaths are a shame, but we must protect Haven.',42423),(64758,22,0,0,0,0,0,0,0,'No! What has that fool done to the console?!',42423),(64760,669,0,0,0,0,0,0,0,'Thank you for your assistance, Maw Walker.\n\nI must return to Oribos. I will tell Cartel Al that our friends are not lost, but Enlightened.',42423),(64763,273,0,0,0,0,0,0,0,'The tasks are in motion.',42698),(64766,273,0,0,0,0,0,0,0,'The Restoration Matrix is acquired. The architect is not present. The architect is therefore lost. \n\nRestoration of the repository is mandatory, even so.',42698),(64771,669,0,0,0,0,0,0,0,'If they cannot be persuaded, they must be protected.',42423),(64773,1,0,0,0,0,0,0,0,'Fewer devourers, less likely we will be eaten.',42538),(64785,1,0,0,0,0,0,0,0,'This information will help, but I\'m afraid those ruins still remain a mystery!',42488),(64794,0,0,0,0,0,0,0,0,'You\'ve arrived.\n\nTheir movements here are strange. It almost seems as if the bulk of their forces are elsewhere.',42423),(64796,0,0,0,0,0,0,0,0,'We have discovered their immediate goal. We should return to our allies, quickly.',43345),(64797,0,0,0,0,0,0,0,0,'The enemy has not yet been able to break through our defending line, but I fear we will lose the battle without your assistance.',43345),(64798,1,0,0,0,0,0,0,0,'All the shards are now infused with the resistance we gained from our experiences with Domination.\n\nIt was not easy, for any of us. But I am proud of what we were able to accomplish, together.\n\nAs for the rest, our future is in the hands of the Primus.',44730),(64799,1,0,0,0,0,0,0,0,'The suffering he endured... \n\nThis will be difficult to overcome.',44730),(64800,1,0,0,0,0,0,0,0,'I don\'t like this as an option any more than Taelia does, but we need to wield Domination safely if we are to find a way to overcome it.\n\nOur first step is to ensure that the helm still works. On us.',44730),(64801,1,0,0,0,0,0,0,0,'What is this? You wish to know if there is anything here that can help you resist Mawsworn magic?\n\nYou are in luck, stranger. I happen to know that this place is a library. And libraries are wonderful places to find what you are looking for.',44730),(64802,669,0,0,0,0,0,0,0,'Even those who overcame Domination are not entirely immune to it now.\n\nBut there may be something buried in that history that can aid us. \n\nI will think on this.\n\nFor now, focus your efforts on the creatures of Zereth Mortis. See what makes them more resistant.',44730),(64803,0,0,0,0,0,0,0,0,'The more advanced creatures resist Domination for longer? \n\nWell of course, I could have told you that. It\'s all about the language!',44730),(64804,1,0,0,0,0,0,0,0,'This place is wondrous.\n\nI could spend all of my existence here.',44730),(64805,1,0,0,0,0,0,0,0,'You see! It took far longer for Domination to overtake the librarian\'s native purposing.\n\nOf course it did fail in the end, but I would call that a success for your particular interest.\n\nDo not worry, another automa will take that one\'s place. There must always be a librarian.',44730),(64806,1,0,0,0,0,0,0,0,'Good, you\'ve arrived.\n\nWe have assembled those who have suffered from Domination in the past. Some more recently than others. \n\nAll have come through it, not always intact, but we are still standing. That is what we must capture.',44730),(64807,1,0,0,0,0,0,0,0,'I feel... lighter. But I cannot forget what has brought me to here, and what must still be done.\n\nI hope that Taelia will remember what she saw... the man I am now. Not some lone figure locked away, but someone who does what is necessary for the good of all.',44730),(64808,1,0,0,0,0,0,0,0,'I think I understand.\n\n<Anduin steels himself.>\n\nI am ready to try again.',44730),(64809,1,0,0,0,0,0,0,0,'The enemy is formidable, but with the strength of our arms and the power of the Broken Helm, we may be able to even the odds.\n\nThough I admit, I have an extra sense of caution with my daughter in the field.',44730),(64810,1,0,0,0,0,0,0,0,'Well done. \n\nLet us hope that this is last time we see the helm used as a weapon.',44730),(64811,1,0,0,0,0,0,0,0,'We\'ve done it. The broken half of the helm is infused with the most advanced pieces of the First Ones\' power that we could readily find.\n\nWe are so close to success.',44730),(64812,669,0,0,0,0,0,0,0,'How appropriate that the place I was imprisoned in will be the setting for how we free ourselves.',44908),(64813,1,0,0,0,0,0,0,0,'This is a power unlike any I have felt before. We have made something new.\n\nIt will be our key to defeating Zovaal.',44908),(64814,0,0,0,0,0,0,0,0,'We must remain vigilant. No one may pass our defenses.',43345),(64815,0,0,0,0,0,0,0,0,'The fewer losses we suffer here, the longer we can hold the line.',43345),(64816,1,0,0,0,0,0,0,0,'There is more work yet to do here in Zereth Mortis before Zovaal\'s influence will be expunged from the Shadowlands.',44908),(64817,0,0,0,0,0,0,0,0,'They managed to hide themselves. This bodes poorly for us.',43345),(64818,0,0,0,0,0,0,0,0,'Mograine will have the forces he needs.',43345),(64820,0,0,0,0,0,0,0,0,'With the defenses working again, hopefully the Mawsworn presence diminishes.',43345),(64821,0,0,0,0,0,0,0,0,'That should slow down their plans. Good work, Maw Walker.',43345),(64822,0,0,0,0,0,0,0,0,'They claimed you gave them their previous orders? Strange.',43345),(64823,0,0,0,0,0,0,0,0,'Mal\'ganis...\n\nWe are losing this race.',43345),(64824,0,0,0,0,0,0,0,0,'Anduin...\n\nWe\'ll save you somehow.',43345),(64825,0,0,0,0,0,0,0,0,'We will look into how to follow them into the Sepulcher. Until then, you should focus your efforts on more immediate issues.',43345),(64830,1,0,0,0,0,0,0,0,'Zereth Mortis has the answers you seek.\n\nIf you know where to look.',43345),(64831,1,0,0,0,0,0,0,0,'Only inert remnants, unfortunately.\n\nBut do not lose hope, my friend!',44730),(64832,1,0,0,0,0,0,0,0,'More devourers will come, but you have lessened their impact for now.',44730),(64833,6,0,0,0,0,0,0,0,'The site below is crawling with devourers. But you can manage, yes?',44730),(64834,1,0,0,0,0,0,0,0,'So the remnants have something to do with the translocator. But what?\n\nWhatever their prior function, they have no power now.',44730),(64835,1,0,0,0,0,0,0,0,'I cannot thank you enough for rescuing the pilgrims who could be saved.',44730),(64836,1,0,0,0,0,0,0,0,'Putting the Cultivator down was the right call.',44730),(64837,1,0,0,0,0,0,0,0,'Welcome to Pilgrim\'s Grace.',44730),(64838,1,0,0,0,0,0,0,0,'Feroz is our best bet? And he has gone missing along with several other pilgrims?\n\nWe should hurry.',44730),(64839,1,0,0,0,0,0,0,0,'These roots are overflowing with growth energy.',44730),(64840,1,22,0,0,0,500,0,0,'Hmm... it replicates rapidly until it kills the host. \n\nThis is more of a curse than a gift!',44730),(64841,1,0,0,0,0,0,0,0,'Well done, Maw Walker!',44730),(64842,1,0,0,0,0,0,0,0,'It was quite poetic, I think, using their own growth energy against them.',44730),(64843,1,0,0,0,0,0,0,0,'We have done it!',44730),(64844,1,0,0,0,0,0,0,0,'The next step is a large one. Are you ready, $n?',44730),(64852,0,0,0,0,0,0,0,0,'This is just what I needed! Take this in appreciation for your efforts!',42698),(64853,669,0,0,0,0,0,0,0,'This Elder has given us an important answer to this puzzle. But now we must act on the information. Though, doing so will be difficult.\n\nFirst we must infuse the helm with those indecipherable phrases from the First Ones that are in the Endless Sands.\n\nBut that will not be enough on its own. We will need more. Let me prepare, while you acquire what we need. I will send word for you after.',44730),(64875,0,0,0,0,0,0,0,0,'We may be on the cusp of a wondrous revelation!',44908),(64876,0,0,0,0,0,0,0,0,'A vision! The oracle communicates with us! You saw it too? Such magnificence! Such... a migraine left in its wake.',44908),(64878,0,0,0,0,0,0,0,0,'Above the sands. Above us. The vessel awaits.',44908),(64879,0,0,0,0,0,0,0,0,'Mortal, I have monumental news. Saezurah has indicated that preparations are complete. It is time to create a new Arbiter!',44908),(64888,0,0,0,0,0,0,0,0,'Power thrums. A renewal of hope.',44908),(64889,0,0,0,0,0,0,0,0,'The last leg of the journey begins.',44908),(64935,0,0,0,0,0,0,0,0,'Our sojourn continues.',44908),(64936,0,0,0,0,0,0,0,0,'One journey ends. Another begins.',44908),(64937,0,0,0,0,0,0,0,0,'Sanctuary, for now. A greater task remains.',44908),(64942,669,0,0,0,0,0,0,0,'There is but one final sigil needed to pursue Zovaal.',43345),(64944,1,274,0,0,0,0,0,0,'This... certainly is not Oribos.',43345),(64945,1,0,0,0,0,0,0,0,'I will not abide agents of the Jailer defiling this land!',43345),(64947,1,0,0,0,0,0,0,0,'Admittedly, I did not foresee this result.',43345),(64949,1,4,0,0,0,0,0,0,'Though the loss of automa is unfortunate, these fragments could prove a boon to my research.',43345),(64950,4,1,1,0,0,0,0,0,'<Firim snatches the core from your hands.>\n\nIntriguing. I have examined many automa cores, but this one glows with an energy unlike any I have seen before.',43345),(64951,1,1,0,0,0,0,0,0,'I can go no further.\n\nMy former colleagues and I have... philosophical differences.',43345),(64952,1,0,0,0,0,0,0,0,'You have bought us time, mortal. First Ones bless us all.',43345),(64953,1,0,0,0,0,0,0,0,'You have proven your mettle, yet the enemy grows bolder.',43345),(64957,669,0,0,0,0,0,0,0,'Maw Walker! Thank the Light you and Pelagos are safe!',43345),(64958,669,0,0,0,0,0,0,0,'You defended Haven, and now you bring allies to preserve this sacred land.\n\nBlessings of the First Ones be upon you, mortal.',43345),(64962,1,0,0,0,0,0,0,0,'The rustle of creation, whisper in the dark. We may begin.',44908),(64963,1,-1,0,0,0,0,0,0,'<A smile creeps across Duchess Mynx\'s face as she looks over the scroll you provided. A moment later, an echoing laugh bursts from her.>\n\nThe forces of the Jailer use such pathetic codes! This scroll of yours doesn\'t say where, but it seems there\'s a weapons cache ready to be claimed. A team of your allies should be able to investigate and retrieve it without too much trouble.',46741),(64969,1,0,0,0,0,0,0,0,'Feroz explained what happened to the missing pilgrims.\n\nThey are trapped inside the Catalyst Wards!',44730),(64970,1,0,0,0,0,0,0,0,'Your tales of adventure are most exciting, my friend! Please, allow me to offer a token of my gratitude.',43206),(64977,1,0,0,0,0,0,0,0,'What a remarkable device. Of course there is clearly some improvement to be made in what it creates. But perhaps it will learn from the lessons you have provided.',42698),(65010,1,0,0,0,0,0,0,0,'Ah, the alpaca. This shape is now yours to call upon.',42538),(65026,1,0,0,0,0,0,0,0,'Ah, the owl. This shape is now yours to call upon.',41359),(65064,669,0,0,0,0,0,0,0,'Perhaps we should do some experiments with other subjects before trying things out on E\'rnee.',42423),(65066,669,0,0,0,0,0,0,0,'These results seem... inconclusive.',42423),(65067,669,0,0,0,0,0,0,0,'Ah. This will certainly be useful.',42423),(65068,669,0,0,0,0,0,0,0,'That was unexpected.',42423),(65069,669,0,0,0,0,0,0,0,'Oh my... what happened to you?',42423),(65070,669,0,0,0,0,0,0,0,'It worked! I cannot thank you enough for your help. And now, he is yours. Take good care of him.\n\nGoodbye, E\'rnee.',42423),(65072,1,0,0,0,0,0,0,0,'Your help is always appreciated, $n.',42423),(65105,0,0,0,0,0,0,0,0,'Another good collection of souls. Not too broken, not too drained, and not too innocent.\n\nI know just where to send these souls on their path to redemption.',40944),(65142,1,0,0,0,0,0,0,0,'This will do fine, but there is still so much more to understand. With my Prying Eyes still out there, we shall be able to collect some more data very soon.',42698),(65145,0,0,0,0,0,0,0,0,'The research is going so well. \n\nPreliminary findings have given me clues on how to find more relics, let me share them with you.',41079),(65146,0,0,0,0,0,0,0,0,'It seems some relics have a trace or unique identifier. \n\nHere are the details, it should allow you to locate even more relics when you find a source.',41079),(65149,669,0,0,0,0,0,0,0,'You have gained a glimpse of knowledge unimaginable. Now, to make use of it.',43345),(65177,1,0,0,0,0,0,0,0,'There is so much to learn from just these little seeds. What will they grow into? Will the vombata eat them?\n\nThank you for helping me to understand this place further.',42698),(65237,0,0,0,0,0,0,0,0,'Dormant no longer. The pattern aligns. But more must be done.',44908),(65238,1,0,0,0,0,0,0,0,'Pelagos is right. But if anyone can accomplish what is needed... I believe it is you, my friend.',44908),(65245,0,0,0,0,0,0,0,0,'The design must be restored.',44908),(65249,0,0,0,0,0,0,0,0,'A new era for the Shadowlands begins today.',44908),(65250,0,0,0,0,0,0,0,0,'Word of Sylvanas\'s arrival has spread throughout the Shadowlands. Many wish to see her pay for her crimes.',42979),(65255,0,0,0,0,0,0,0,0,'Their energy will serve the cycle.',42538),(65256,1,0,0,0,0,0,0,0,'Those poultrid do make quite a mess. Thank you for your assistance.',42560),(65259,1,1,0,0,0,2000,0,0,'At long last, our campaign is at an end. Thanks to you, the Jailer has been defeated.\n\nYour efforts have saved us all, $n.',42698),(65260,0,0,0,0,0,0,0,0,'Thank you for joining us, my friend. \n\nI felt it important that you be here to witness this moment.',42979),(65263,0,0,0,0,0,0,0,0,'How could I possibly pass judgment to Tyrande\'s satisfaction when she and her people were the ones most wronged by the Banshee Queen?',42979),(65264,1,0,0,0,0,0,0,0,'Well done, $n. The avians will be moved to a safer location where we can observe them.',42538),(65265,1,0,0,0,0,0,0,0,'Without the context in which these were first made, they may remain mysteries. But at least they are not trampled underfoot anymore.',42560),(65266,1,0,0,0,0,0,0,0,'The research within these repositories is invaluable. I may ask you to return to the rift again in the future.',41079),(65269,1,0,0,0,0,0,0,0,'Our brightest scholars will track the sensor data. First Ones willing, they will show us the way.',42698),(65271,1,1,0,0,0,300,0,0,'If you do not have the power to help us, then you must go.',43345),(65279,669,153,0,0,0,300,0,0,'Good start... but have bigger plans.',47213),(65297,1,0,0,0,0,0,0,0,'Justice for Teldrassil. Peace for the kaldorei.',42979),(65302,669,0,0,0,0,0,0,0,'Always wanted power stick!\n\nMON-ARK PROVIDES!',47213),(65305,669,0,0,0,0,0,0,0,'You have returned, Maw Walker. What news do you have for me?',43345),(65306,669,0,0,0,0,0,0,0,'Squishy toe junk. Very nice.',47213),(65324,378,0,0,0,0,0,0,0,'We move closer to our goal. Ever onward.',42488),(65325,1,0,0,0,0,0,0,0,'You have recovered our resources. Your assistance is appreciated.',42698),(65328,0,0,0,0,0,0,0,0,'An Arbiter? I had not imagined we could set that to rights.',44908),(65329,1,0,0,0,0,0,0,0,'A new Arbiter has been established? This is excellent news, $n, and a massive step towards restoring balance to the Shadowlands. Your efforts here will not be forgotten. \n\nHowever, it is still only one step towards our goal. We must continue to strengthen our position in Zereth Mortis, and drive the Jailer\'s forces out. \n\nOur work continues--but with you on our side, victory is that much closer. Thank you.',44908),(65331,1,0,0,0,0,0,0,0,'A quasi-successful test run, but a success nonetheless.',44730),(65335,1,0,0,0,0,0,0,0,'Sylvanas\'s experience may be intrinsic to Anduin\'s fate.',43345),(65336,1,0,0,0,0,0,0,0,'<The protoform forge chimes a melancholy song as it draws in the schematic.>',42698),(65349,0,0,0,0,0,0,0,0,'<This automa has been ravaged by devourers. It clutches a curious object in its hand.>',42538),(65350,0,0,0,0,0,0,0,0,'<It seems as though your efforts were successful--the waters are once again flowing through the temple. The wellspring should be restored.>',42538),(65353,0,0,0,0,0,0,0,0,'Stranger, I... I apologize. My trust in you was lacking. In turn, my faith wavered as well. Forgive me, and take with you my thanks--the First Ones truly guide your hand.',42538),(65370,1,0,0,0,0,0,0,0,'<The jiro looks over the guts-spattered device.>\n\nNot ideal. But mostly intact... it will need cleaning.',42538),(65380,1,0,0,0,0,0,0,0,'Excellent. With this schematic and the right components, a new song can begin here to accompany you.',42698),(65385,1,0,0,0,0,0,0,0,'Excellent. With this schematic and the right components, a new song can begin here to accompany you.',42698),(65419,669,0,0,0,0,0,0,0,'<Pocopoc points to some controls on this device, and you understand just enough Dealic to glimpse its purpose in bringing you here. With some materials found across Zereth Mortis and Pocopoc\'s help, you can trigger this machine to create fully realized beings based on specific schematics.>',42488),(65431,0,0,0,0,0,0,0,0,'New knowledge! The First Ones truly did leave such marvelous insights.',42423),(65432,0,0,0,0,0,0,0,0,'<A strange energy surrounds the console.>',42423),(65448,0,0,0,0,0,0,0,0,'As I thought--your arrival was by the design of the First Ones. I look forward to the legacy you forge in this land of our creators.',42538),(65456,1,0,0,0,0,0,0,0,'You are stronger and more patient than you look.',43345),(65460,0,0,0,0,0,0,0,0,'Well done, Maw Walker.\n\nI am sure that with enough energy and effort your companion will be able to help you overcome these challenges, if they become a struggle for you.',42423),(65461,0,0,0,0,0,0,0,0,'Use this knowledge and collect more data from the field, Maw Walker.\n\nThere is still one more Cache of Creation that I must instruct you on.',42423),(65463,2,0,0,0,0,0,0,0,'A mortal, here? The designs of the First Ones are mysterious.',42538),(65466,0,0,0,0,0,0,0,0,'Well done, Maw Walker. That was truly an impressive effort.\n\nRemember, that if you do struggle with these protolocks, your companion can help you overcome them if they have enough energy.\n\nNow take your expanded knowledge out into the field.',42423),(65467,1,0,0,0,0,0,0,0,'Ooh, a turkey! You can gobble like one now, too!',41079),(65519,1,0,0,0,0,0,0,0,'Ooh, a snail! Now you can crawl like one too!',42852),(65594,669,0,0,0,0,0,0,0,'You live this long? Good meat.',47213),(65595,669,0,0,0,0,0,0,0,'Me lead gnolls to better hunt now. You... not so bad. Gnolls hungry though, and you still meat.\n\nLeave. Me no chase.',47213),(65674,1,0,0,0,0,0,0,0,'Oh, now this is a most interesting find indeed, mortal.\n\nI have encountered such material in my research before. In theory, it can alter the fate of various objects--unlocking their potential, as it were. Curious, no?\n\nI will keep this essence as I have need of it. In exchange, I will share with you the knowledge on how to use similar materials in your own creations.',44730),(65717,6,1,22,0,0,300,300,0,'By the First Ones... once again, you bring me the extraordinary. You say you found this when you defeated the Jailer? How curious.\n\nIt almost seems as if it\'s trying to... to communicate somehow. The implications alone are--ah! Forgive me for getting carried away. This will require more than simple research, I\'m afraid. \n\nPlease, take this in return. It was one of my first discoveries--I suspect you have more to gain from its mobility than I do. \n\nThank you, my friend.',44730),(65725,1,0,0,0,0,0,0,0,'Thank you, $p. Let us see if this does the trick.',42423),(65726,1,0,0,0,0,0,0,0,'Thank you, $p. Let us try this for Bud\'s sake, if not our own curiosity.',42488),(65727,1,0,0,0,0,0,0,0,'Thank you, $p. Now, let us see if this will entice that bufonid to emerge.',42423),(65728,1,0,0,0,0,0,0,0,'Thank you, $p. Let us hope this works.',42538),(65735,0,0,0,0,0,0,0,0,'I do not understand why it was behaving in that manner, but we will be safer now that it is gone. This reward shall start you on the way towards some of my finer equipment.',42423),(65748,0,0,0,0,0,0,0,0,'Well met, traveler! What have you found there? Ah, this will help many other travelers in need. You have my thanks--and theirs as well.',42423),(65749,0,0,0,0,0,0,0,0,'You have my thanks $p, and a gift for your future efforts.',42423),(65764,0,0,0,0,0,0,0,0,'This should help us travel directly to Anduin.',43114),(65768,0,0,0,0,0,0,0,0,'This information will help us plan our next move. Thank you, Maw Walker.',43345),(65771,1,0,0,0,0,0,0,0,'May the First Ones accept these offerings as penance for past transgressions. \n\nThank you, Maw Walker.',43345),(65772,0,0,0,0,0,0,0,0,'Thank you. Your efforts are greatly appreciated.',43345),(66042,378,0,0,0,0,0,0,0,'We move closer to our goal. Ever onward.',42698),(66383,1,0,0,0,0,0,0,0,'Welcome. Please view my wares, several of which can assist you in the crafting of Legendaries!',43345),(66395,0,0,0,0,0,0,0,0,'I knew there had to be something there. And to think, they were so close to the portal. Now I can contemplate... other things.\n\nWhile you were hunting, Rymek and I had a lovely conversation. He\'s quite undrstanding and sympathetic. In a way, he reminds me of Solethus...\n\nHe asked if he could see the portal to the Emerald Dream with his own eyes. I see no reason why not, especially since you\'ve cleared those spiders away. I\'m sure he\'ll be quite impressed.',47213),(67071,0,0,0,0,0,0,0,0,'Catch a fish for a mortal, they will eat for a day.\n\nTeach a mortal to cook, they will eat for a lifetime.\n\nGive a mortal your most prized recipe, they will think of you each time they make it. At least we hope you do.\n\n<Morsel and Rumi smile at you like only good friends can.>\n\nCome back any time, $n! The meal is on us!',47213),(72071,0,0,0,0,0,0,0,0,'Now who\'s up one?',47213),(72083,4,0,0,0,0,0,0,0,'No fish can resist me lucky lure, living or dead!',47213),(72405,0,0,0,0,0,0,0,0,'My few interactions with Vanessa told me she isn\'t interested in the banditry of the old Defias Brotherhood. To her, the Brotherhood meant supporting the downtrodden... those that Stormwind had left behind. \n\nThat, I can respect. \n\nBut most of her Brotherhood continue to engage in thievery from innocent travelers. That\'s not revolution, that\'s highway robbery.\n\nShe insists she tries to stop them.',49801),(72409,0,0,0,0,0,0,0,0,'Ah, Windsor...',49801),(72900,6,0,0,0,0,0,0,0,'Shall we begin?',53584),(75667,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75668,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75669,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75670,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75671,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75672,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75673,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75674,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75675,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75676,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75677,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75678,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75679,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75682,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75683,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75684,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75685,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75686,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75687,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75688,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75689,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75690,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75691,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75692,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75693,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75695,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75696,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75697,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75698,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75699,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75700,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75701,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75702,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75703,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(75704,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886),(77698,0,0,0,0,0,0,0,0,'Candy buckets like this are located in inns throughout the realms. Go ahead... take some!',51886);
INSERT  IGNORE INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `EmoteOnCompleteDelay`, `EmoteOnIncompleteDelay`, `CompletionText`, `VerifiedBuild`) VALUES (14001,0,5,0,0,'I still see some out there! Please, $n, go get them before they drown!',52983),(14113,0,6,0,0,'How\'s the party going?$B$BYou look amazing! So dashing and handsome, sir!',52983),(24469,0,6,0,0,'How many of \'em did ya get?',53007),(24470,0,6,0,0,'Well, what\'re ye waitin\' for, $c?',53007),(24471,0,0,0,0,'Thanks for yer help, $n.',53007),(24489,0,0,0,0,'I can\'t even begin to imagine what would make the trolls act like this.',53007),(25667,0,1,0,0,'How goes the fight against the wendigos?',53007),(25724,0,1,0,0,'How is the situation on Shimmer Ridge?',53007),(25792,0,0,0,0,'Was the rune able to destroy the totems? Were we too late?',53007),(25841,0,1,0,0,'Did you signal the air wing to take out the troll buildings?',53007),(25905,0,1,0,0,'',53007),(25932,0,1,0,0,'We\'re glad to have your help, $n.',53007),(25978,0,1,0,0,'Were you able to help any of the mountaineers?',53007),(25979,0,1,0,0,'Something has to be done. We can\'t leave the lake like this. ',53007),(26078,0,1,0,0,'We need to hurry and get those bombers airborne!',53007),(26085,0,1,0,0,'We must do what little we can to keep the defenders\' spirits high.',53007),(26094,0,1,0,0,'At last, we finally have a chance to hurt the Dark Iron attackers.',53007),(26102,0,6,0,0,'If we can defeat General Grimaxe, the Dark Iron forces won\'t be able to regroup.',53007),(26118,0,1,0,0,'We must stop the ambassador before he causes more harm.',53007),(26146,0,6,0,0,'Loch Modan is under siege, $n!  We need every able-bodied member of the Alliance to aid our cause.  Have you killed those troggs yet?',53007),(28394,0,1,0,0,'We cannot afford to allow those golems to be used against us.',0),(28868,0,1,0,0,'Did you show them what it\'s like to be a gnome?',53007),(30033,0,1,0,0,'Picking up your first weapon is also a symbolic gesture. Every $c that leaves these training grounds must be ready to take up arms in defense of their fellow pandaren.',20886),(39262,0,0,0,0,'$n, we need you to scan the cave with your spectral sight.\n\nWe must know if there are Legion forces magically hidden within.',53877),(44546,0,0,0,0,'Did you teach \'em a lesson?',48069),(55879,0,0,0,0,'Please... help! I won\'t last much longer!',53262),(59932,0,0,0,0,'Please... I be needin\'... food...',50401),(65279,0,53,0,0,'GET WITH KILLING!',47213),(65306,53,53,0,0,'NEED MORE OOZE!',47213),(66263,0,603,0,0,'Did I mention I\'m allergic to gnoll fur? My throat gets itchy just thinking about them.',48069),(66264,1,1,0,0,'Surely they\'re just lying about?',48069),(66265,0,1,0,0,'How goes hunting the hunter?',48069),(66266,0,604,0,0,'Why, no I\'m not a \"dog person.\" Why do you ask?',48069),(66267,0,604,0,0,'Have you checked their pockets for keys? They have to keep them somewhere.',48069),(66268,0,603,0,0,'All according to plan!',48069),(66269,0,604,0,0,'Don\'t they know they\'ve been outwitted?',48069),(66270,0,604,0,0,'What are you waiting for?',48069),(67071,0,0,0,0,'Our hoard is just behind the cauldron.\n\nNot to worry though, we lowered the sealing enchantment and deathly magical traps for you!',47213),(72071,0,0,0,0,'It\'s out there. I can feel it.',47213),(72083,1,1,0,0,'No, I don\'t know which one ate it. I was busy being dead at the time.',47213),(72405,0,0,0,0,'We must recover what was stolen from the Keep, at all costs.',49801),(72406,0,0,0,0,'Welcome Valdrakken, $p.',48317),(72409,0,0,0,0,'Drink always seems to be empty... why\'s me drink always empty?',0),(72900,0,0,0,0,'Ah, here to help are we?',53584);
INSERT  IGNORE INTO `quest_description_conditional` (`QuestId`, `PlayerConditionId`, `QuestgiverCreatureId`, `locale`, `Text`, `OrderIndex`, `VerifiedBuild`) VALUES (75890,110815,0,'enUS','<Fine penmanship fills the scroll.>\n\n$n,\n\nIt has been quite some time since we last spoke. I would not be here were it not for your aid in Jaedenar long ago, and I have not forgotten you. \n\nIt seems that your strength is needed in Shadow Hold hold once more -- the Wardens have need of you.\n\nMeet me near the embassy in Stormwind. Tyrande has called the Wardens to action, and your help would be greatly appreciated.\n\nArko\'narin Starshade',0,54630);
